  ('97a19581-8998-5a58-b6ed-d12530788479'::uuid, 1, 'Bloque 1 · Definición de los trabajos', 'Descripción de la labor, ciclo subterráneo, geometría, responsabilidades, interfaces y criterios de parada.'),
  ('3b09195c-4cdd-5f25-9871-49f2b869cdd1'::uuid, 2, 'Bloque 2 · Técnicas preventivas y de protección', 'Riesgo dinámico, terreno y sostenimiento, ventilación, atmósfera, agentes, incendio, agua, voladura y emergencia.'),
  ('cc1a61b0-e9b9-5c15-9a1d-47ac4a80e57b'::uuid, 3, 'Bloque 3 · Equipos de trabajo, EPI y medios auxiliares', 'Equipos móviles y fijos, inspección, consignación de energías, EPI, herramientas, acceso y rescate.'),
  ('0ef2e845-5bec-53ff-95ae-f5ccc849c341'::uuid, 4, 'Bloque 4 · Control y vigilancia del lugar de trabajo', 'Inspecciones, mediciones, hallazgos, entregas entre turnos, gestión del cambio, cierre y reapertura.'),
  ('a993e8b2-e6d5-5923-8e37-63703d6c64e4'::uuid, 5, 'Bloque 5 · Interferencias con otras actividades', 'Actividades simultáneas, servicios conectados, coordinación empresarial, permisos y control conjunto de energías.'),
  ('f2c18773-e4eb-5697-a91a-a65a06218f44'::uuid, 6, 'Bloque 6 · Normativa y legislación', 'Marco preventivo y minero, ITC aplicables, DSS, DIS, alcance formativo y autorización basada en evidencias.');

