create temporary table _tin_units on commit drop as
select * from jsonb_to_recordset($interior_units$[{"slide_number":1,"block_number":1,"lesson_ordinal":1,"segment_position":1,"segment_id":"d03c6921-2fac-58c6-999f-2799e0c092a4","slide_id":"fc99f059-d612-5ec7-be9a-f46e2f1dcb03","note_id":"225efe0a-a6dc-51d1-8c86-8164b0e6525d","title":"Identificación, destinatarios y alcance del curso","narration_text":"En interior, una condición segura debe demostrarse antes de exponer a una persona.\n\nPara empezar, se sitúa el criterio: Formación preventiva para técnicos titulados que trabajan en explotaciones subterráneas. Programa de InmínerCampus, edición 1.0, adaptado al proyecto, al Documento sobre Seguridad y Salud y a las disposiciones internas de seguridad de cada centro. El material sirve de apoyo y debe contextualizarse en la explotación concreta.\n\nEste manual desarrolla un programa preventivo de 20 horas para técnicos titulados que trabajan en explotaciones subterráneas. Debe adaptarse al proyecto, al Documento sobre Seguridad y Salud, a las disposiciones internas de seguridad y a las condiciones de cada centro. No sustituye las autorizaciones, habilitaciones ni instrucciones específicas exigibles. La ITC 02.1.02 incluye a los técnicos titulados de actividades extractivas de interior en el grupo 5.3.a y exige formación preventiva específica, presencial y periódica. La norma fija seis bloques de contenido, una actualización máxima general de cuatro años y un reciclaje mínimo de cinco horas. A la fecha de esta edición no se ha localizado una especificación técnica estatal publicada que asigne al grupo 5.3.a un programa propio de 20 horas. Por ello, la duración y la distribución de este manual constituyen un diseño docente prudente basado en la ITC, en los riesgos de interior y en programas oficiales próximos.\n\nPensemos en una situación de campo. Imagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: marco y destinatarios.","duration_seconds":172,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-001.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-001.png","explanation":"Objetivo\n\nFormación preventiva para técnicos titulados que trabajan en explotaciones subterráneas. Programa de InmínerCampus, edición 1.0, adaptado al proyecto, al Documento sobre Seguridad y Salud y a las DIS de cada centro. El material sirve de apoyo y debe contextualizarse en la explotación concreta.\n\nExplicación detallada\n\nEste manual desarrolla un programa preventivo de 20 horas para técnicos titulados que trabajan en explotaciones subterráneas. Debe adaptarse al proyecto, al Documento sobre Seguridad y Salud, a las disposiciones internas de seguridad y a las condiciones de cada centro. No sustituye las autorizaciones, habilitaciones ni instrucciones específicas exigibles. La ITC 02.1.02 incluye a los técnicos titulados de actividades extractivas de interior en el grupo 5.3.a y exige formación preventiva específica, presencial y periódica. La norma fija seis bloques de contenido, una actualización máxima general de cuatro años y un reciclaje mínimo de cinco horas. A la fecha de esta edición no se ha localizado una especificación técnica estatal publicada que asigne al grupo 5.3.a un programa propio de 20 horas. Por ello, la duración y la distribución de este manual constituyen un diseño docente prudente basado en la ITC, en los riesgos de interior y en programas oficiales próximos.\n\nLectura guiada de la diapositiva\n\n• Formación preventiva para técnicos titulados que trabajan en explotaciones subterráneas. Programa de InmínerCampus, edición 1.0, adaptado al proyecto, al Documento sobre Seguridad y Salud y a las DIS de cada centro. El material sirve de apoyo y debe contextualizarse en la explotación concreta.\n\nAplicación práctica\n\nImagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nMarco y destinatarios","key_points":["Formación preventiva para técnicos titulados que trabajan en explotaciones subterráneas. Programa de InmínerCampus, edición 1.0, adaptado al proyecto, al Documento sobre Seguridad y Salud y a las DIS de cada centro. El material sirve de apoyo y debe contextualizarse en la explotación concreta.","Marco y destinatarios"],"stop_criterion":"Marco y destinatarios","source_pages":"Bloque 1 · diapositiva 01","question":"Respecto a «Identificación, destinatarios y alcance del curso», ¿qué criterio operativo es correcto?","correct_option":"Marco y destinatarios: Formación preventiva para técnicos titulados que trabajan en explotaciones subterráneas. Programa de InmínerCampus, edición 1.0, adaptado al proyecto, al Documento sobre Seguridad y Salud y a las DIS de cada centro. El material sirve de apoyo y debe contextualizarse en la explotación concreta.","question_explanation":"Formación preventiva para técnicos titulados que trabajan en explotaciones subterráneas. Programa de InmínerCampus, edición 1.0, adaptado al proyecto, al Documento sobre Seguridad y Salud y a las DIS de cada centro. El material sirve de apoyo y debe contextualizarse en la explotación concreta."},{"slide_number":2,"block_number":1,"lesson_ordinal":1,"segment_position":2,"segment_id":"d86aa9b6-a44f-5a01-9a0b-b0b6f4bd9a0b","slide_id":"5747dfaa-4de7-5326-9d18-a670d556a7c4","note_id":"da707c66-4458-504b-9992-3072c4210e16","title":"Grupo 5.3.a, duración y límites de la formación","narration_text":"La prevención empieza describiendo el trabajo real, no suponiendo que hoy será igual que ayer.\n\nLa primera referencia es: Itinerario correspondiente al grupo 5.3.a de la ITC 02.1.02. Duración curricular propuesta por InmínerCampus: 20 horas. Modalidad reglamentaria presencial; el soporte digital es complementario. No concede nombramientos ni habilitaciones de director facultativo, vigilante, artillero o rescatista.\n\nLa ITC 02.1.02 incluye a los técnicos titulados de actividades extractivas de interior en el grupo 5.3.a y exige formación preventiva específica, presencial y periódica. La norma fija seis bloques de contenido, una actualización máxima general de cuatro años y un reciclaje mínimo de cinco horas. A la fecha de esta edición no se ha localizado una especificación técnica estatal publicada que asigne al grupo 5.3.a un programa propio de 20 horas. Por ello, la duración y la distribución de este manual constituyen un diseño docente prudente basado en la ITC, en los riesgos de interior y en programas oficiales próximos. La ET 2003-1-10 no ampara este itinerario: su ámbito enumera puestos de los grupos 5.1, 5.2.a, 5.2.b, 5.2.d, 5.2.f y 5.2.h, pero no el grupo 5.3.a. El certificado y la ficha del curso deben identificar el grupo 5.3.a y evitar atribuir una especificación técnica que no corresponda. La autoridad minera competente puede imponer contenidos, duración o condiciones adicionales.\n\nPensemos en una situación de campo. Durante el relevo, el turno entrante recibe solo la frase todo correcto. Sin ubicación, medición, prueba ni responsable, esa comunicación no permite saber si la condición sigue controlada.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: alcance bien delimitado.","duration_seconds":170,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-002.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-002.png","explanation":"Objetivo\n\nItinerario correspondiente al grupo 5.3.a de la ITC 02.1.02. Duración curricular propuesta por InmínerCampus: 20 horas. Modalidad reglamentaria presencial; el soporte digital es complementario. No concede nombramientos ni habilitaciones de director facultativo, vigilante, artillero o rescatista.\n\nExplicación detallada\n\nLa ITC 02.1.02 incluye a los técnicos titulados de actividades extractivas de interior en el grupo 5.3.a y exige formación preventiva específica, presencial y periódica. La norma fija seis bloques de contenido, una actualización máxima general de cuatro años y un reciclaje mínimo de cinco horas. A la fecha de esta edición no se ha localizado una especificación técnica estatal publicada que asigne al grupo 5.3.a un programa propio de 20 horas. Por ello, la duración y la distribución de este manual constituyen un diseño docente prudente basado en la ITC, en los riesgos de interior y en programas oficiales próximos. La ET 2003-1-10 no ampara este itinerario: su ámbito enumera puestos de los grupos 5.1, 5.2.a, 5.2.b, 5.2.d, 5.2.f y 5.2.h, pero no el grupo 5.3.a. El certificado y la ficha del curso deben identificar el grupo 5.3.a y evitar atribuir una especificación técnica que no corresponda. La autoridad minera competente puede imponer contenidos, duración o condiciones adicionales.\n\nLectura guiada de la diapositiva\n\n• Itinerario correspondiente al grupo 5.3.a de la ITC 02.1.02. Duración curricular propuesta por InmínerCampus: 20 horas. Modalidad reglamentaria presencial; el soporte digital es complementario. No concede nombramientos ni habilitaciones de director facultativo, vigilante, artillero o rescatista.\n\nAplicación práctica\n\nDurante el relevo, el turno entrante recibe solo la frase todo correcto. Sin ubicación, medición, prueba ni responsable, esa comunicación no permite saber si la condición sigue controlada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nAlcance bien delimitado","key_points":["Itinerario correspondiente al grupo 5.3.a de la ITC 02.1.02. Duración curricular propuesta por InmínerCampus: 20 horas. Modalidad reglamentaria presencial; el soporte digital es complementario. No concede nombramientos ni habilitaciones de director facultativo, vigilante, artillero o rescatista.","Alcance bien delimitado"],"stop_criterion":"Alcance bien delimitado","source_pages":"Bloque 1 · diapositiva 02","question":"Respecto a «Grupo 5.3.a, duración y límites de la formación», ¿qué criterio operativo es correcto?","correct_option":"Alcance bien delimitado: Itinerario correspondiente al grupo 5.3.a de la ITC 02.1.02. Duración curricular propuesta por InmínerCampus: 20 horas. Modalidad reglamentaria presencial; el soporte digital es complementario. No concede nombramientos ni habilitaciones de director facultativo, vigilante, artillero o rescatista.","question_explanation":"Itinerario correspondiente al grupo 5.3.a de la ITC 02.1.02. Duración curricular propuesta por InmínerCampus: 20 horas. Modalidad reglamentaria presencial; el soporte digital es complementario. No concede nombramientos ni habilitaciones de director facultativo, vigilante, artillero o rescatista."},{"slide_number":3,"block_number":1,"lesson_ordinal":1,"segment_position":3,"segment_id":"bb37efce-3abc-5bb6-b231-6e8a263591fe","slide_id":"774f1e0e-bf7d-52ae-bab6-39859eca81a7","note_id":"def8ff87-1d73-5e2f-a6b1-f81133a5f066","title":"Resultados de aprendizaje","narration_text":"Bajo tierra, terreno, aire, agua, equipos y secuencia pueden cambiar durante el mismo turno.\n\nConviene comprobar lo siguiente: Describir una labor subterránea y explicar cómo el método y la secuencia modifican el riesgo. Supervisar terreno, ventilación, atmósfera, agua, transporte, energías y emergencias. Definir parada, aislamiento, evacuación, reapertura y coordinación con trazabilidad.\n\nUna evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas. Criterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio. El ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia.\n\nPensemos en una situación de campo. Producción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: competencia aplicada.","duration_seconds":154,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-003.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-003.png","explanation":"Objetivo\n\nDescribir una labor subterránea y explicar cómo el método y la secuencia modifican el riesgo. Supervisar terreno, ventilación, atmósfera, agua, transporte, energías y emergencias. Definir parada, aislamiento, evacuación, reapertura y coordinación con trazabilidad.\n\nExplicación detallada\n\nUna evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas. Criterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio. El ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia.\n\nLectura guiada de la diapositiva\n\n• Describir una labor subterránea y explicar cómo el método y la secuencia modifican el riesgo. Supervisar terreno, ventilación, atmósfera, agua, transporte, energías y emergencias. Definir parada, aislamiento, evacuación, reapertura y coordinación con trazabilidad.\n\nAplicación práctica\n\nProducción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nCompetencia aplicada","key_points":["Describir una labor subterránea y explicar cómo el método y la secuencia modifican el riesgo. Supervisar terreno, ventilación, atmósfera, agua, transporte, energías y emergencias. Definir parada, aislamiento, evacuación, reapertura y coordinación con trazabilidad.","Competencia aplicada"],"stop_criterion":"Competencia aplicada","source_pages":"Bloque 1 · diapositiva 03","question":"Respecto a «Resultados de aprendizaje», ¿qué criterio operativo es correcto?","correct_option":"Competencia aplicada: Describir una labor subterránea y explicar cómo el método y la secuencia modifican el riesgo. Supervisar terreno, ventilación, atmósfera, agua, transporte, energías y emergencias. Definir parada, aislamiento, evacuación, reapertura y coordinación con trazabilidad.","question_explanation":"Describir una labor subterránea y explicar cómo el método y la secuencia modifican el riesgo. Supervisar terreno, ventilación, atmósfera, agua, transporte, energías y emergencias. Definir parada, aislamiento, evacuación, reapertura y coordinación con trazabilidad."},{"slide_number":4,"block_number":1,"lesson_ordinal":1,"segment_position":4,"segment_id":"d266b2fe-73b9-5fd7-b9d7-61157d8d3a13","slide_id":"665d906c-ba85-54a9-85e1-02fc4f032452","note_id":"63df1dfb-0e61-5549-a00f-91de139f7b30","title":"La explotación subterránea como sistema conectado","narration_text":"Supervisar consiste en comparar lo que ocurre en campo con un criterio definido de antemano.\n\nEl punto de partida es: Desarrollo, preparación, producción, transporte, servicios y emergencia comparten infraestructuras. Una decisión local puede alterar ventilación, evacuación, estabilidad o circulación lejos del punto de trabajo. La evaluación debe abarcar toda la zona de influencia.\n\nUna evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas. El ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia. Criterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio.\n\nPensemos en una situación de campo. Un ajuste aparentemente local de una puerta de ventilación mejora un frente, pero reduce el caudal en otra labor y modifica su ruta de evacuación.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: pensar en el sistema.","duration_seconds":155,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-004.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-004.png","explanation":"Objetivo\n\nDesarrollo, preparación, producción, transporte, servicios y emergencia comparten infraestructuras. Una decisión local puede alterar ventilación, evacuación, estabilidad o circulación lejos del punto de trabajo. La evaluación debe abarcar toda la zona de influencia.\n\nExplicación detallada\n\nUna evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas. El ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia. Criterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio.\n\nLectura guiada de la diapositiva\n\n• Desarrollo, preparación, producción, transporte, servicios y emergencia comparten infraestructuras. Una decisión local puede alterar ventilación, evacuación, estabilidad o circulación lejos del punto de trabajo. La evaluación debe abarcar toda la zona de influencia.\n\nAplicación práctica\n\nUn ajuste aparentemente local de una puerta de ventilación mejora un frente, pero reduce el caudal en otra labor y modifica su ruta de evacuación.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nPensar en el sistema","key_points":["Desarrollo, preparación, producción, transporte, servicios y emergencia comparten infraestructuras. Una decisión local puede alterar ventilación, evacuación, estabilidad o circulación lejos del punto de trabajo. La evaluación debe abarcar toda la zona de influencia.","Pensar en el sistema"],"stop_criterion":"Pensar en el sistema","source_pages":"Bloque 1 · diapositiva 04","question":"Respecto a «La explotación subterránea como sistema conectado», ¿qué criterio operativo es correcto?","correct_option":"Pensar en el sistema: Desarrollo, preparación, producción, transporte, servicios y emergencia comparten infraestructuras. Una decisión local puede alterar ventilación, evacuación, estabilidad o circulación lejos del punto de trabajo. La evaluación debe abarcar toda la zona de influencia.","question_explanation":"Desarrollo, preparación, producción, transporte, servicios y emergencia comparten infraestructuras. Una decisión local puede alterar ventilación, evacuación, estabilidad o circulación lejos del punto de trabajo. La evaluación debe abarcar toda la zona de influencia."},{"slide_number":5,"block_number":1,"lesson_ordinal":1,"segment_position":5,"segment_id":"f5cd7b7c-fead-5fa0-a881-6ee58b8d9b43","slide_id":"7211764e-055b-54ac-a3d5-a1ab64fb83ac","note_id":"6f18ca32-53b0-53fe-bdf9-1feca08b5972","title":"Fases del ciclo minero subterráneo","narration_text":"Una tarea habitual también necesita límites claros y una comprobación proporcionada al riesgo.\n\nPara empezar, se sitúa el criterio: Desarrollo y arranque: cambios de ventilación, gases, proyecciones y barrenos fallidos. Saneo y sostenimiento: evitar exposición bajo techo no verificado. Carga, transporte, relleno y servicios: interacción vehículo-peatón, agua, aire y energía.\n\nEl ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia. Una evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas. Cámaras y pilares, corte y relleno, subniveles, hundimiento, tajos largos y variantes mecanizadas distribuyen de forma distinta los huecos, las cargas y las rutas. El nombre del método no basta: hay que conocer luces, alturas, pilares, secuencia, relleno, excavaciones próximas y tiempo de exposición. Una modificación en el orden de extracción puede concentrar tensiones, dejar pilares sobrecargados o cerrar una ruta prevista.\n\nPensemos en una situación de campo. Una contrata aplica su procedimiento, pero desconoce un cambio reciente de la explotación. La coordinación debe llevar el cambio hasta el punto de trabajo antes de autorizar la actividad.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: cada fase cambia el riesgo.","duration_seconds":167,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-005.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-005.png","explanation":"Objetivo\n\nDesarrollo y arranque: cambios de ventilación, gases, proyecciones y barrenos fallidos. Saneo y sostenimiento: evitar exposición bajo techo no verificado. Carga, transporte, relleno y servicios: interacción vehículo-peatón, agua, aire y energía.\n\nExplicación detallada\n\nEl ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia. Una evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas. Cámaras y pilares, corte y relleno, subniveles, hundimiento, tajos largos y variantes mecanizadas distribuyen de forma distinta los huecos, las cargas y las rutas. El nombre del método no basta: hay que conocer luces, alturas, pilares, secuencia, relleno, excavaciones próximas y tiempo de exposición. Una modificación en el orden de extracción puede concentrar tensiones, dejar pilares sobrecargados o cerrar una ruta prevista.\n\nLectura guiada de la diapositiva\n\n• Desarrollo y arranque: cambios de ventilación, gases, proyecciones y barrenos fallidos. Saneo y sostenimiento: evitar exposición bajo techo no verificado. Carga, transporte, relleno y servicios: interacción vehículo-peatón, agua, aire y energía.\n\nAplicación práctica\n\nUna contrata aplica su procedimiento, pero desconoce un cambio reciente de la explotación. La coordinación debe llevar el cambio hasta el punto de trabajo antes de autorizar la actividad.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nCada fase cambia el riesgo","key_points":["Desarrollo y arranque: cambios de ventilación, gases, proyecciones y barrenos fallidos. Saneo y sostenimiento: evitar exposición bajo techo no verificado. Carga, transporte, relleno y servicios: interacción vehículo-peatón, agua, aire y energía.","Cada fase cambia el riesgo"],"stop_criterion":"Cada fase cambia el riesgo","source_pages":"Bloque 1 · diapositiva 05","question":"Respecto a «Fases del ciclo minero subterráneo», ¿qué criterio operativo es correcto?","correct_option":"Cada fase cambia el riesgo: Desarrollo y arranque: cambios de ventilación, gases, proyecciones y barrenos fallidos. Saneo y sostenimiento: evitar exposición bajo techo no verificado. Carga, transporte, relleno y servicios: interacción vehículo-peatón, agua, aire y energía.","question_explanation":"Desarrollo y arranque: cambios de ventilación, gases, proyecciones y barrenos fallidos. Saneo y sostenimiento: evitar exposición bajo techo no verificado. Carga, transporte, relleno y servicios: interacción vehículo-peatón, agua, aire y energía."},{"slide_number":6,"block_number":1,"lesson_ordinal":1,"segment_position":6,"segment_id":"548a36a8-d8e0-5a49-8269-e5d36fe17738","slide_id":"e4ecec27-2ca5-52ac-bc54-1db1735fbe5f","note_id":"1dd50283-4f06-5b00-bb3f-ca4be06f8eb3","title":"Estados no productivos que también generan riesgo","narration_text":"La decisión técnica debe precisar qué se acepta, qué obliga a parar y qué permite reanudar.\n\nLa primera referencia es: Espera, limpieza, desatasco, inspección, prueba y mantenimiento tienen peligros propios. El cambio de turno o una parada de ventilación puede degradar barreras. Tras una incidencia, hay que verificar nuevamente las condiciones antes de recuperar la actividad.\n\nEl ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia. Criterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio. La ET 2003-1-10 no ampara este itinerario: su ámbito enumera puestos de los grupos 5.1, 5.2.a, 5.2.b, 5.2.d, 5.2.f y 5.2.h, pero no el grupo 5.3.a. El certificado y la ficha del curso deben identificar el grupo 5.3.a y evitar atribuir una especificación técnica que no corresponda. La autoridad minera competente puede imponer contenidos, duración o condiciones adicionales.\n\nPensemos en una situación de campo. Durante una espera de producción, un equipo queda detenido con presión hidráulica y una persona aprovecha para retirar material sin consignarlo.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: parar no elimina el peligro.","duration_seconds":166,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-006.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-006.png","explanation":"Objetivo\n\nEspera, limpieza, desatasco, inspección, prueba y mantenimiento tienen peligros propios. El cambio de turno o una parada de ventilación puede degradar barreras. Tras una incidencia, hay que verificar nuevamente las condiciones antes de recuperar la actividad.\n\nExplicación detallada\n\nEl ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia. Criterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio. La ET 2003-1-10 no ampara este itinerario: su ámbito enumera puestos de los grupos 5.1, 5.2.a, 5.2.b, 5.2.d, 5.2.f y 5.2.h, pero no el grupo 5.3.a. El certificado y la ficha del curso deben identificar el grupo 5.3.a y evitar atribuir una especificación técnica que no corresponda. La autoridad minera competente puede imponer contenidos, duración o condiciones adicionales.\n\nLectura guiada de la diapositiva\n\n• Espera, limpieza, desatasco, inspección, prueba y mantenimiento tienen peligros propios. El cambio de turno o una parada de ventilación puede degradar barreras. Tras una incidencia, hay que verificar nuevamente las condiciones antes de recuperar la actividad.\n\nAplicación práctica\n\nDurante una espera de producción, un equipo queda detenido con presión hidráulica y una persona aprovecha para retirar material sin consignarlo.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nParar no elimina el peligro","key_points":["Espera, limpieza, desatasco, inspección, prueba y mantenimiento tienen peligros propios. El cambio de turno o una parada de ventilación puede degradar barreras. Tras una incidencia, hay que verificar nuevamente las condiciones antes de recuperar la actividad.","Parar no elimina el peligro"],"stop_criterion":"Parar no elimina el peligro","source_pages":"Bloque 1 · diapositiva 06","question":"Respecto a «Estados no productivos que también generan riesgo», ¿qué criterio operativo es correcto?","correct_option":"Parar no elimina el peligro: Espera, limpieza, desatasco, inspección, prueba y mantenimiento tienen peligros propios. El cambio de turno o una parada de ventilación puede degradar barreras. Tras una incidencia, hay que verificar nuevamente las condiciones antes de recuperar la actividad.","question_explanation":"Espera, limpieza, desatasco, inspección, prueba y mantenimiento tienen peligros propios. El cambio de turno o una parada de ventilación puede degradar barreras. Tras una incidencia, hay que verificar nuevamente las condiciones antes de recuperar la actividad."},{"slide_number":7,"block_number":1,"lesson_ordinal":1,"segment_position":7,"segment_id":"cd3d19a6-a8ff-5b21-bea8-017cda8af9e3","slide_id":"5541a662-73b4-542c-9d94-df4a32308b32","note_id":"1173038f-bcf7-5f07-8e4e-875e4fd55147","title":"Métodos de explotación y geometrías principales","narration_text":"Una barrera preventiva solo es útil cuando puede observarse, medirse o probarse.\n\nConviene comprobar lo siguiente: Cámaras y pilares, corte y relleno, subniveles, hundimiento y tajo largo presentan geometrías distintas. Importan luces, alturas, pilares, relleno, secuencia y excavaciones próximas. Cambiar el orden de extracción puede sobrecargar pilares o cerrar una ruta prevista.\n\nCámaras y pilares, corte y relleno, subniveles, hundimiento, tajos largos y variantes mecanizadas distribuyen de forma distinta los huecos, las cargas y las rutas. El nombre del método no basta: hay que conocer luces, alturas, pilares, secuencia, relleno, excavaciones próximas y tiempo de exposición. Una modificación en el orden de extracción puede concentrar tensiones, dejar pilares sobrecargados o cerrar una ruta prevista. El ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia. Una evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas.\n\nPensemos en una situación de campo. El trabajo empieza dentro de criterio, pero una labor conectada cambia el aire, el agua o la circulación. El equipo debe reconocer el cambio antes de que la condición inicial deje de ser válida.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: la geometría gobierna.","duration_seconds":169,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-007.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-007.png","explanation":"Objetivo\n\nCámaras y pilares, corte y relleno, subniveles, hundimiento y tajo largo presentan geometrías distintas. Importan luces, alturas, pilares, relleno, secuencia y excavaciones próximas. Cambiar el orden de extracción puede sobrecargar pilares o cerrar una ruta prevista.\n\nExplicación detallada\n\nCámaras y pilares, corte y relleno, subniveles, hundimiento, tajos largos y variantes mecanizadas distribuyen de forma distinta los huecos, las cargas y las rutas. El nombre del método no basta: hay que conocer luces, alturas, pilares, secuencia, relleno, excavaciones próximas y tiempo de exposición. Una modificación en el orden de extracción puede concentrar tensiones, dejar pilares sobrecargados o cerrar una ruta prevista. El ciclo puede incluir investigación, excavación de accesos, avance de galerías, preparación de paneles o cámaras, perforación, carga de explosivo, voladura, ventilación, saneo, sostenimiento, carga, transporte, relleno, mantenimiento, bombeo y cierre. Cada fase tiene estados no productivos con riesgo propio: espera, limpieza, desatasco, inspección, prueba, cambio de turno, parada de ventilación o recuperación después de una incidencia. Una evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas.\n\nLectura guiada de la diapositiva\n\n• Cámaras y pilares, corte y relleno, subniveles, hundimiento y tajo largo presentan geometrías distintas. Importan luces, alturas, pilares, relleno, secuencia y excavaciones próximas. Cambiar el orden de extracción puede sobrecargar pilares o cerrar una ruta prevista.\n\nAplicación práctica\n\nEl trabajo empieza dentro de criterio, pero una labor conectada cambia el aire, el agua o la circulación. El equipo debe reconocer el cambio antes de que la condición inicial deje de ser válida.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nLa geometría gobierna","key_points":["Cámaras y pilares, corte y relleno, subniveles, hundimiento y tajo largo presentan geometrías distintas. Importan luces, alturas, pilares, relleno, secuencia y excavaciones próximas. Cambiar el orden de extracción puede sobrecargar pilares o cerrar una ruta prevista.","La geometría gobierna"],"stop_criterion":"La geometría gobierna","source_pages":"Bloque 1 · diapositiva 07","question":"Respecto a «Métodos de explotación y geometrías principales», ¿qué criterio operativo es correcto?","correct_option":"La geometría gobierna: Cámaras y pilares, corte y relleno, subniveles, hundimiento y tajo largo presentan geometrías distintas. Importan luces, alturas, pilares, relleno, secuencia y excavaciones próximas. Cambiar el orden de extracción puede sobrecargar pilares o cerrar una ruta prevista.","question_explanation":"Cámaras y pilares, corte y relleno, subniveles, hundimiento y tajo largo presentan geometrías distintas. Importan luces, alturas, pilares, relleno, secuencia y excavaciones próximas. Cambiar el orden de extracción puede sobrecargar pilares o cerrar una ruta prevista."},{"slide_number":8,"block_number":1,"lesson_ordinal":1,"segment_position":8,"segment_id":"32aeb2df-254d-58a2-bb86-1a606774b068","slide_id":"0dc8693e-2187-5df4-b3a5-9bc8bb382ea3","note_id":"5d7d659f-1d60-56d1-9412-5fdcd9171b32","title":"Propagación de riesgos entre labores","narration_text":"Antes de autorizar hay que entender qué puede cambiar y hasta dónde llegarían sus efectos.\n\nEl punto de partida es: Terreno, aire, agua y tráfico conectan labores diferentes. Un retorno restringido altera varios frentes; una labor antigua cambia agua, terreno y atmósfera. Evaluar siempre los efectos aguas abajo y en las rutas de evacuación.\n\nCriterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio. Situación Se programa un avance de galería igual a los tres anteriores. El plano de control muestra una labor antigua próxima y el retorno de ventilación ha perdido sección por acumulación de material. Una evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas.\n\nPensemos en una situación de campo. Una labor antigua no visible desde el frente empieza a aportar agua turbia y altera al mismo tiempo el terreno, la atmósfera y el acceso.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: riesgo remoto.","duration_seconds":142,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-008.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-008.png","explanation":"Objetivo\n\nTerreno, aire, agua y tráfico conectan labores diferentes. Un retorno restringido altera varios frentes; una labor antigua cambia agua, terreno y atmósfera. Evaluar siempre los efectos aguas abajo y en las rutas de evacuación.\n\nExplicación detallada\n\nCriterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio. Situación Se programa un avance de galería igual a los tres anteriores. El plano de control muestra una labor antigua próxima y el retorno de ventilación ha perdido sección por acumulación de material. Una evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas.\n\nLectura guiada de la diapositiva\n\n• Terreno, aire, agua y tráfico conectan labores diferentes. Un retorno restringido altera varios frentes; una labor antigua cambia agua, terreno y atmósfera. Evaluar siempre los efectos aguas abajo y en las rutas de evacuación.\n\nAplicación práctica\n\nUna labor antigua no visible desde el frente empieza a aportar agua turbia y altera al mismo tiempo el terreno, la atmósfera y el acceso.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nRiesgo remoto","key_points":["Terreno, aire, agua y tráfico conectan labores diferentes. Un retorno restringido altera varios frentes; una labor antigua cambia agua, terreno y atmósfera. Evaluar siempre los efectos aguas abajo y en las rutas de evacuación.","Riesgo remoto"],"stop_criterion":"Riesgo remoto","source_pages":"Bloque 1 · diapositiva 08","question":"Respecto a «Propagación de riesgos entre labores», ¿qué criterio operativo es correcto?","correct_option":"Riesgo remoto: Terreno, aire, agua y tráfico conectan labores diferentes. Un retorno restringido altera varios frentes; una labor antigua cambia agua, terreno y atmósfera. Evaluar siempre los efectos aguas abajo y en las rutas de evacuación.","question_explanation":"Terreno, aire, agua y tráfico conectan labores diferentes. Un retorno restringido altera varios frentes; una labor antigua cambia agua, terreno y atmósfera. Evaluar siempre los efectos aguas abajo y en las rutas de evacuación."},{"slide_number":9,"block_number":1,"lesson_ordinal":1,"segment_position":9,"segment_id":"785abfe5-ce90-53a3-8564-5ed8eb9da223","slide_id":"c0de7882-b212-5ecb-85a7-0edc7d7ce34e","note_id":"58995a3e-61ab-5ca5-a5ea-2a522c95c301","title":"Funciones técnicas, responsabilidades y límites de autoridad","narration_text":"La primera pregunta no es cómo producir más rápido, sino qué condición debe conservarse segura.\n\nPara empezar, se sitúa el criterio: Empresario, dirección facultativa, equipo facultativo, vigilante, técnico, operador y artillero tienen funciones distintas. El título y este curso no conceden por sí solos todos los roles. Actuar dentro del nombramiento, competencia y autoridad asignados.\n\nLa ET 2003-1-10 no ampara este itinerario: su ámbito enumera puestos de los grupos 5.1, 5.2.a, 5.2.b, 5.2.d, 5.2.f y 5.2.h, pero no el grupo 5.3.a. El certificado y la ficha del curso deben identificar el grupo 5.3.a y evitar atribuir una especificación técnica que no corresponda. La autoridad minera competente puede imponer contenidos, duración o condiciones adicionales.\n\nPensemos en una situación de campo. El turno saliente conoce una limitación temporal, pero no la registra. El turno entrante recibe la zona como disponible y actúa con una información incompleta.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: competencia y nombramiento.","duration_seconds":152,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-009.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-009.png","explanation":"Objetivo\n\nEmpresario, dirección facultativa, equipo facultativo, vigilante, técnico, operador y artillero tienen funciones distintas. El título y este curso no conceden por sí solos todos los roles. Actuar dentro del nombramiento, competencia y autoridad asignados.\n\nExplicación detallada\n\nLa ET 2003-1-10 no ampara este itinerario: su ámbito enumera puestos de los grupos 5.1, 5.2.a, 5.2.b, 5.2.d, 5.2.f y 5.2.h, pero no el grupo 5.3.a. El certificado y la ficha del curso deben identificar el grupo 5.3.a y evitar atribuir una especificación técnica que no corresponda. La autoridad minera competente puede imponer contenidos, duración o condiciones adicionales.\n\nLectura guiada de la diapositiva\n\n• Empresario, dirección facultativa, equipo facultativo, vigilante, técnico, operador y artillero tienen funciones distintas. El título y este curso no conceden por sí solos todos los roles. Actuar dentro del nombramiento, competencia y autoridad asignados.\n\nAplicación práctica\n\nEl turno saliente conoce una limitación temporal, pero no la registra. El turno entrante recibe la zona como disponible y actúa con una información incompleta.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nCompetencia y nombramiento","key_points":["Empresario, dirección facultativa, equipo facultativo, vigilante, técnico, operador y artillero tienen funciones distintas. El título y este curso no conceden por sí solos todos los roles. Actuar dentro del nombramiento, competencia y autoridad asignados.","Competencia y nombramiento"],"stop_criterion":"Competencia y nombramiento","source_pages":"Bloque 1 · diapositiva 09","question":"Respecto a «Funciones técnicas, responsabilidades y límites de autoridad», ¿qué criterio operativo es correcto?","correct_option":"Competencia y nombramiento: Empresario, dirección facultativa, equipo facultativo, vigilante, técnico, operador y artillero tienen funciones distintas. El título y este curso no conceden por sí solos todos los roles. Actuar dentro del nombramiento, competencia y autoridad asignados.","question_explanation":"Empresario, dirección facultativa, equipo facultativo, vigilante, técnico, operador y artillero tienen funciones distintas. El título y este curso no conceden por sí solos todos los roles. Actuar dentro del nombramiento, competencia y autoridad asignados."},{"slide_number":10,"block_number":1,"lesson_ordinal":1,"segment_position":10,"segment_id":"7ce7d01d-cbde-55c8-a812-c6690cc1b791","slide_id":"4f54fc7c-75a1-5e9e-b422-3c4b5aa49b5b","note_id":"0948f78f-5271-555e-889e-e1bca7a1d6bf","title":"Ficha para definir un trabajo y caso del avance aparentemente rutinario","narration_text":"En una labor conectada con otras, una decisión local nunca se analiza de forma aislada.\n\nLa primera referencia es: Definir objeto, ubicación, terreno, secuencia, personas, equipos, ventilación, evacuación, interferencias y reapertura. Caso: avance repetido, labor antigua próxima y retorno reducido. Detener la preparación hasta verificar planos, sondeos, ventilación y secuencia.\n\nCriterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio. Una evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas. Situación Se programa un avance de galería igual a los tres anteriores. El plano de control muestra una labor antigua próxima y el retorno de ventilación ha perdido sección por acumulación de material.\n\nPensemos en una situación de campo. El avance se ha repetido varias veces, pero el retorno ha perdido sección y los planos muestran una labor antigua próxima; la rutina ya no es equivalente.\n\nAntes de iniciar, el técnico debe confirmar qué trabajo se va a realizar, qué otras labores pueden verse afectadas y qué documento define la condición aceptable. Durante la ejecución se comprueba si cambian el terreno, el aire, el agua, el tráfico o la secuencia. Si aparece una condición no prevista, se conserva el estado seguro y se eleva la decisión.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: lo rutinario también cambia.","duration_seconds":176,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-010.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-010.png","explanation":"Objetivo\n\nDefinir objeto, ubicación, terreno, secuencia, personas, equipos, ventilación, evacuación, interferencias y reapertura. Caso: avance repetido, labor antigua próxima y retorno reducido. Detener la preparación hasta verificar planos, sondeos, ventilación y secuencia.\n\nExplicación detallada\n\nCriterio de resolución La proximidad a trabajos antiguos y la restricción del retorno cambian agua terreno y atmósfera. Se detiene la preparación hasta verificar planos sondeos ventilación y secuencia. La repetición de una tarea no elimina la gestión del cambio. Una evaluación fiable empieza por describir la labor real, el método, la secuencia, las personas, los equipos y los cambios previsibles. En interior, una decisión local puede alterar ventilación, evacuación, estabilidad o circulación en zonas alejadas. Situación Se programa un avance de galería igual a los tres anteriores. El plano de control muestra una labor antigua próxima y el retorno de ventilación ha perdido sección por acumulación de material.\n\nLectura guiada de la diapositiva\n\n• Definir objeto, ubicación, terreno, secuencia, personas, equipos, ventilación, evacuación, interferencias y reapertura. Caso: avance repetido, labor antigua próxima y retorno reducido. Detener la preparación hasta verificar planos, sondeos, ventilación y secuencia.\n\nAplicación práctica\n\nEl avance se ha repetido varias veces, pero el retorno ha perdido sección y los planos muestran una labor antigua próxima; la rutina ya no es equivalente.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nLo rutinario también cambia","key_points":["Definir objeto, ubicación, terreno, secuencia, personas, equipos, ventilación, evacuación, interferencias y reapertura. Caso: avance repetido, labor antigua próxima y retorno reducido. Detener la preparación hasta verificar planos, sondeos, ventilación y secuencia.","Lo rutinario también cambia"],"stop_criterion":"Lo rutinario también cambia","source_pages":"Bloque 1 · diapositiva 10","question":"Respecto a «Ficha para definir un trabajo y caso del avance aparentemente rutinario», ¿qué criterio operativo es correcto?","correct_option":"Lo rutinario también cambia: Definir objeto, ubicación, terreno, secuencia, personas, equipos, ventilación, evacuación, interferencias y reapertura. Caso: avance repetido, labor antigua próxima y retorno reducido. Detener la preparación hasta verificar planos, sondeos, ventilación y secuencia.","question_explanation":"Definir objeto, ubicación, terreno, secuencia, personas, equipos, ventilación, evacuación, interferencias y reapertura. Caso: avance repetido, labor antigua próxima y retorno reducido. Detener la preparación hasta verificar planos, sondeos, ventilación y secuencia."},{"slide_number":11,"block_number":2,"lesson_ordinal":2,"segment_position":1,"segment_id":"3336fc2c-04d7-5cc5-a602-2277daeb7ed6","slide_id":"522df832-5096-5bc1-87dc-e76c426aa239","note_id":"885758be-923f-5e47-86ce-de97177cb29f","title":"Riesgo dinámico en minería subterránea","narration_text":"El control empieza por reconocer la señal temprana, antes de que el peligro alcance a alguien.\n\nConviene comprobar lo siguiente: La supervisión confirma que las barreras previstas siguen presentes y funcionan. El riesgo combina probabilidad, exposición y consecuencia. Terreno, atmósfera, agua o equipos pueden cambiar dentro del mismo turno.\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nPensemos en una situación de campo. Dos tareas autorizadas coinciden en una instalación común. La incompatibilidad aparece en la interacción, no en la revisión aislada de cada permiso.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: verificar antes de exponer.","duration_seconds":159,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-011.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-011.png","explanation":"Objetivo\n\nLa supervisión confirma que las barreras previstas siguen presentes y funcionan. El riesgo combina probabilidad, exposición y consecuencia. Terreno, atmósfera, agua o equipos pueden cambiar dentro del mismo turno.\n\nExplicación detallada\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nLectura guiada de la diapositiva\n\n• La supervisión confirma que las barreras previstas siguen presentes y funcionan. El riesgo combina probabilidad, exposición y consecuencia. Terreno, atmósfera, agua o equipos pueden cambiar dentro del mismo turno.\n\nAplicación práctica\n\nDos tareas autorizadas coinciden en una instalación común. La incompatibilidad aparece en la interacción, no en la revisión aislada de cada permiso.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nVerificar antes de exponer","key_points":["La supervisión confirma que las barreras previstas siguen presentes y funcionan. El riesgo combina probabilidad, exposición y consecuencia. Terreno, atmósfera, agua o equipos pueden cambiar dentro del mismo turno.","Verificar antes de exponer"],"stop_criterion":"Verificar antes de exponer","source_pages":"Bloque 2 · diapositiva 11","question":"Respecto a «Riesgo dinámico en minería subterránea», ¿qué criterio operativo es correcto?","correct_option":"Verificar antes de exponer: La supervisión confirma que las barreras previstas siguen presentes y funcionan. El riesgo combina probabilidad, exposición y consecuencia. Terreno, atmósfera, agua o equipos pueden cambiar dentro del mismo turno.","question_explanation":"La supervisión confirma que las barreras previstas siguen presentes y funcionan. El riesgo combina probabilidad, exposición y consecuencia. Terreno, atmósfera, agua o equipos pueden cambiar dentro del mismo turno."},{"slide_number":12,"block_number":2,"lesson_ordinal":2,"segment_position":2,"segment_id":"9cd6781b-480d-56a8-82e1-386ea1a05dc7","slide_id":"c4dbd683-2a3c-5809-b4d0-fd33f058edd1","note_id":"f7ca1cbe-ae1d-5bcd-a8de-d47470aa29d1","title":"Peligro, exposición, consecuencia y barrera","narration_text":"Una comprobación útil termina en una decisión concreta: continuar, corregir o detener.\n\nEl punto de partida es: Peligro: fuente con capacidad de causar daño. Exposición: quién entra, dónde y durante cuánto tiempo. Consecuencia: daño posible. Barrera: control que evita el suceso o limita el resultado.\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nPensemos en una situación de campo. El instrumento ofrece una lectura, pero no representa el punto de mayor exposición. Medir sin elegir bien lugar y momento puede producir una falsa sensación de control.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: cuatro conceptos.","duration_seconds":159,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-012.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-012.png","explanation":"Objetivo\n\nPeligro: fuente con capacidad de causar daño. Exposición: quién entra, dónde y durante cuánto tiempo. Consecuencia: daño posible. Barrera: control que evita el suceso o limita el resultado.\n\nExplicación detallada\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nLectura guiada de la diapositiva\n\n• Peligro: fuente con capacidad de causar daño. Exposición: quién entra, dónde y durante cuánto tiempo. Consecuencia: daño posible. Barrera: control que evita el suceso o limita el resultado.\n\nAplicación práctica\n\nEl instrumento ofrece una lectura, pero no representa el punto de mayor exposición. Medir sin elegir bien lugar y momento puede producir una falsa sensación de control.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nCuatro conceptos","key_points":["Peligro: fuente con capacidad de causar daño. Exposición: quién entra, dónde y durante cuánto tiempo. Consecuencia: daño posible. Barrera: control que evita el suceso o limita el resultado.","Cuatro conceptos"],"stop_criterion":"Cuatro conceptos","source_pages":"Bloque 2 · diapositiva 12","question":"Respecto a «Peligro, exposición, consecuencia y barrera», ¿qué criterio operativo es correcto?","correct_option":"Cuatro conceptos: Peligro: fuente con capacidad de causar daño. Exposición: quién entra, dónde y durante cuánto tiempo. Consecuencia: daño posible. Barrera: control que evita el suceso o limita el resultado.","question_explanation":"Peligro: fuente con capacidad de causar daño. Exposición: quién entra, dónde y durante cuánto tiempo. Consecuencia: daño posible. Barrera: control que evita el suceso o limita el resultado."},{"slide_number":13,"block_number":2,"lesson_ordinal":2,"segment_position":3,"segment_id":"82be4b92-da4d-5b30-862d-cb81403a0fd6","slide_id":"f4e7b6f1-5d94-5b12-9de9-39df6a2d80ca","note_id":"afd997cf-1a28-5af8-b704-0ed084791ad0","title":"Evidencias de que una barrera funciona","narration_text":"La ausencia de un incidente no demuestra que las barreras sigan disponibles.\n\nPara empezar, se sitúa el criterio: Inspección del contorno, lectura del detector o prueba de comunicación. Registro con hora, ubicación, condiciones y autorización de reentrada. Una firma sin observación, medición o prueba no demuestra eficacia.\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nPensemos en una situación de campo. Imagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: evidencia objetiva.","duration_seconds":143,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-013.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-013.png","explanation":"Objetivo\n\nInspección del contorno, lectura del detector o prueba de comunicación. Registro con hora, ubicación, condiciones y autorización de reentrada. Una firma sin observación, medición o prueba no demuestra eficacia.\n\nExplicación detallada\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nLectura guiada de la diapositiva\n\n• Inspección del contorno, lectura del detector o prueba de comunicación. Registro con hora, ubicación, condiciones y autorización de reentrada. Una firma sin observación, medición o prueba no demuestra eficacia.\n\nAplicación práctica\n\nImagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nEvidencia objetiva","key_points":["Inspección del contorno, lectura del detector o prueba de comunicación. Registro con hora, ubicación, condiciones y autorización de reentrada. Una firma sin observación, medición o prueba no demuestra eficacia.","Evidencia objetiva"],"stop_criterion":"Evidencia objetiva","source_pages":"Bloque 2 · diapositiva 13","question":"Respecto a «Evidencias de que una barrera funciona», ¿qué criterio operativo es correcto?","correct_option":"Evidencia objetiva: Inspección del contorno, lectura del detector o prueba de comunicación. Registro con hora, ubicación, condiciones y autorización de reentrada. Una firma sin observación, medición o prueba no demuestra eficacia.","question_explanation":"Inspección del contorno, lectura del detector o prueba de comunicación. Registro con hora, ubicación, condiciones y autorización de reentrada. Una firma sin observación, medición o prueba no demuestra eficacia."},{"slide_number":14,"block_number":2,"lesson_ordinal":2,"segment_position":4,"segment_id":"e6769664-bca3-5b5e-994b-312c7434b514","slide_id":"6668a012-fa4d-50cb-92b1-849be7326598","note_id":"a67d7969-0aeb-5076-8438-74672cbf39a1","title":"Jerarquía de medidas preventivas","narration_text":"Cuando falta un dato crítico, conservar el estado seguro es también una decisión técnica.\n\nLa primera referencia es: Priorizar diseño e ingeniería: método húmedo, captación, ventilación y separación. Después, organización: limitar presencia, secuenciar y prohibir prácticas inseguras. El equipo de protección individual completa las medidas y nunca compensa ventilación o sostenimiento deficientes.\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nPensemos en una situación de campo. Durante el relevo, el turno entrante recibe solo la frase todo correcto. Sin ubicación, medición, prueba ni responsable, esa comunicación no permite saber si la condición sigue controlada.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: controlar en origen.","duration_seconds":145,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-014.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-014.png","explanation":"Objetivo\n\nPriorizar diseño e ingeniería: método húmedo, captación, ventilación y separación. Después, organización: limitar presencia, secuenciar y prohibir prácticas inseguras. El EPI completa las medidas y nunca compensa ventilación o sostenimiento deficientes.\n\nExplicación detallada\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nLectura guiada de la diapositiva\n\n• Priorizar diseño e ingeniería: método húmedo, captación, ventilación y separación. Después, organización: limitar presencia, secuenciar y prohibir prácticas inseguras. El EPI completa las medidas y nunca compensa ventilación o sostenimiento deficientes.\n\nAplicación práctica\n\nDurante el relevo, el turno entrante recibe solo la frase todo correcto. Sin ubicación, medición, prueba ni responsable, esa comunicación no permite saber si la condición sigue controlada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nControlar en origen","key_points":["Priorizar diseño e ingeniería: método húmedo, captación, ventilación y separación. Después, organización: limitar presencia, secuenciar y prohibir prácticas inseguras. El EPI completa las medidas y nunca compensa ventilación o sostenimiento deficientes.","Controlar en origen"],"stop_criterion":"Controlar en origen","source_pages":"Bloque 2 · diapositiva 14","question":"Respecto a «Jerarquía de medidas preventivas», ¿qué criterio operativo es correcto?","correct_option":"Controlar en origen: Priorizar diseño e ingeniería: método húmedo, captación, ventilación y separación. Después, organización: limitar presencia, secuenciar y prohibir prácticas inseguras. El EPI completa las medidas y nunca compensa ventilación o sostenimiento deficientes.","question_explanation":"Priorizar diseño e ingeniería: método húmedo, captación, ventilación y separación. Después, organización: limitar presencia, secuenciar y prohibir prácticas inseguras. El EPI completa las medidas y nunca compensa ventilación o sostenimiento deficientes."},{"slide_number":15,"block_number":2,"lesson_ordinal":2,"segment_position":5,"segment_id":"8f350b95-44bd-55b2-98fd-b485816df029","slide_id":"dca312ad-c96b-5c80-8175-0e435114c5db","note_id":"adc265c5-cc75-5f49-9645-8a335291d4f1","title":"Autoridad de parada","narration_text":"El criterio debe ser comprensible para quien ejecuta, para quien supervisa y para el turno siguiente.\n\nConviene comprobar lo siguiente: Parar ante deformación no prevista del terreno o del sostenimiento. Parar por pérdida, inversión o reducción no autorizada de ventilación. Parar ante alarma de gas, humo, agua anómala, fallo crítico, pérdida de salida o trabajo fuera de autorización.\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nPensemos en una situación de campo. A mitad del turno aparece una fisura nueva y producción propone terminar el ciclo antes de parar; el criterio debe estar definido antes de esa presión.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: parar es prevenir.","duration_seconds":147,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-015.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-015.png","explanation":"Objetivo\n\nParar ante deformación no prevista del terreno o del sostenimiento. Parar por pérdida, inversión o reducción no autorizada de ventilación. Parar ante alarma de gas, humo, agua anómala, fallo crítico, pérdida de salida o trabajo fuera de autorización.\n\nExplicación detallada\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nLectura guiada de la diapositiva\n\n• Parar ante deformación no prevista del terreno o del sostenimiento. Parar por pérdida, inversión o reducción no autorizada de ventilación. Parar ante alarma de gas, humo, agua anómala, fallo crítico, pérdida de salida o trabajo fuera de autorización.\n\nAplicación práctica\n\nA mitad del turno aparece una fisura nueva y producción propone terminar el ciclo antes de parar; el criterio debe estar definido antes de esa presión.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nParar es prevenir","key_points":["Parar ante deformación no prevista del terreno o del sostenimiento. Parar por pérdida, inversión o reducción no autorizada de ventilación. Parar ante alarma de gas, humo, agua anómala, fallo crítico, pérdida de salida o trabajo fuera de autorización.","Parar es prevenir"],"stop_criterion":"Parar es prevenir","source_pages":"Bloque 2 · diapositiva 15","question":"Respecto a «Autoridad de parada», ¿qué criterio operativo es correcto?","correct_option":"Parar es prevenir: Parar ante deformación no prevista del terreno o del sostenimiento. Parar por pérdida, inversión o reducción no autorizada de ventilación. Parar ante alarma de gas, humo, agua anómala, fallo crítico, pérdida de salida o trabajo fuera de autorización.","question_explanation":"Parar ante deformación no prevista del terreno o del sostenimiento. Parar por pérdida, inversión o reducción no autorizada de ventilación. Parar ante alarma de gas, humo, agua anómala, fallo crítico, pérdida de salida o trabajo fuera de autorización."},{"slide_number":16,"block_number":2,"lesson_ordinal":2,"segment_position":6,"segment_id":"86f9a5ff-f5be-5458-be6c-d5fb6134dee8","slide_id":"e273f138-4cfd-588b-af19-c92d7cc359d3","note_id":"92c63ee7-3ad7-51d0-ab1e-92c5c2daf867","title":"Secuencia de parada, aislamiento, comunicación y verificación","narration_text":"Cada autorización necesita una condición de partida y una señal inequívoca de pérdida de control.\n\nEl punto de partida es: Detener la tarea y retirar a las personas. Aislar energía o área; comunicar hechos, ubicación, hora y medidas. Evaluar, corregir, verificar y autorizar la reapertura dejando registro.\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nPensemos en una situación de campo. La tarea se ha realizado muchas veces sin incidente. Ese historial no demuestra que el peligro haya desaparecido; puede significar únicamente que todavía no coincidieron fallo y exposición.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: secuencia obligatoria.","duration_seconds":160,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-016.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-016.png","explanation":"Objetivo\n\nDetener la tarea y retirar a las personas. Aislar energía o área; comunicar hechos, ubicación, hora y medidas. Evaluar, corregir, verificar y autorizar la reapertura dejando registro.\n\nExplicación detallada\n\nUn peligro es una fuente de daño; el riesgo combina probabilidad, exposición y consecuencia. El control reduce una o varias de esas dimensiones. La verificación demuestra que el control existe y funciona. Una firma sin observación, medición o prueba no es evidencia suficiente cuando se controla ventilación, sostenimiento, frenado, aislamiento o detección de gases.\n\nLectura guiada de la diapositiva\n\n• Detener la tarea y retirar a las personas. Aislar energía o área; comunicar hechos, ubicación, hora y medidas. Evaluar, corregir, verificar y autorizar la reapertura dejando registro.\n\nAplicación práctica\n\nLa tarea se ha realizado muchas veces sin incidente. Ese historial no demuestra que el peligro haya desaparecido; puede significar únicamente que todavía no coincidieron fallo y exposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nSecuencia obligatoria","key_points":["Detener la tarea y retirar a las personas. Aislar energía o área; comunicar hechos, ubicación, hora y medidas. Evaluar, corregir, verificar y autorizar la reapertura dejando registro.","Secuencia obligatoria"],"stop_criterion":"Secuencia obligatoria","source_pages":"Bloque 2 · diapositiva 16","question":"Respecto a «Secuencia de parada, aislamiento, comunicación y verificación», ¿qué criterio operativo es correcto?","correct_option":"Secuencia obligatoria: Detener la tarea y retirar a las personas. Aislar energía o área; comunicar hechos, ubicación, hora y medidas. Evaluar, corregir, verificar y autorizar la reapertura dejando registro.","question_explanation":"Detener la tarea y retirar a las personas. Aislar energía o área; comunicar hechos, ubicación, hora y medidas. Evaluar, corregir, verificar y autorizar la reapertura dejando registro."},{"slide_number":17,"block_number":2,"lesson_ordinal":2,"segment_position":7,"segment_id":"58a96720-8c3a-52c0-b678-09f1ca62b485","slide_id":"f5ab0a66-7e55-5689-9133-b6ca0d33cd66","note_id":"f7b3c71d-1eb8-58df-a097-fc639fa777b6","title":"El macizo rocoso y sus discontinuidades","narration_text":"En interior, una condición segura debe demostrarse antes de exponer a una persona.\n\nPara empezar, se sitúa el criterio: La excavación elimina confinamiento y redistribuye tensiones. Litología, fallas, juntas, estratificación, agua y labores cercanas condicionan el comportamiento. Una sección estable puede volverse inestable al cruzar una discontinuidad.\n\nLa roca excavada deja de estar confinada y redistribuye tensiones. Litología, alteración, fallas, juntas, estratificación, orientación, agua, esfuerzos y excavaciones cercanas condicionan el comportamiento. El técnico compara la realidad con el modelo y busca cambios: la misma sección puede ser estable en una orientación e inestable al cruzar una falla o un contacto. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles. El sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones.\n\nPensemos en una situación de campo. Una contrata aplica su procedimiento, pero desconoce un cambio reciente de la explotación. La coordinación debe llevar el cambio hasta el punto de trabajo antes de autorizar la actividad.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: el terreno evoluciona.","duration_seconds":151,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-017.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-017.png","explanation":"Objetivo\n\nLa excavación elimina confinamiento y redistribuye tensiones. Litología, fallas, juntas, estratificación, agua y labores cercanas condicionan el comportamiento. Una sección estable puede volverse inestable al cruzar una discontinuidad.\n\nExplicación detallada\n\nLa roca excavada deja de estar confinada y redistribuye tensiones. Litología, alteración, fallas, juntas, estratificación, orientación, agua, esfuerzos y excavaciones cercanas condicionan el comportamiento. El técnico compara la realidad con el modelo y busca cambios: la misma sección puede ser estable en una orientación e inestable al cruzar una falla o un contacto. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles. El sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones.\n\nLectura guiada de la diapositiva\n\n• La excavación elimina confinamiento y redistribuye tensiones. Litología, fallas, juntas, estratificación, agua y labores cercanas condicionan el comportamiento. Una sección estable puede volverse inestable al cruzar una discontinuidad.\n\nAplicación práctica\n\nUna contrata aplica su procedimiento, pero desconoce un cambio reciente de la explotación. La coordinación debe llevar el cambio hasta el punto de trabajo antes de autorizar la actividad.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nEl terreno evoluciona","key_points":["La excavación elimina confinamiento y redistribuye tensiones. Litología, fallas, juntas, estratificación, agua y labores cercanas condicionan el comportamiento. Una sección estable puede volverse inestable al cruzar una discontinuidad.","El terreno evoluciona"],"stop_criterion":"El terreno evoluciona","source_pages":"Bloque 2 · diapositiva 17","question":"Respecto a «El macizo rocoso y sus discontinuidades», ¿qué criterio operativo es correcto?","correct_option":"El terreno evoluciona: La excavación elimina confinamiento y redistribuye tensiones. Litología, fallas, juntas, estratificación, agua y labores cercanas condicionan el comportamiento. Una sección estable puede volverse inestable al cruzar una discontinuidad.","question_explanation":"La excavación elimina confinamiento y redistribuye tensiones. Litología, fallas, juntas, estratificación, agua y labores cercanas condicionan el comportamiento. Una sección estable puede volverse inestable al cruzar una discontinuidad."},{"slide_number":18,"block_number":2,"lesson_ordinal":2,"segment_position":8,"segment_id":"293a1517-4270-5bf9-8f56-dcf7e4fbd85d","slide_id":"b43cd2c9-3329-5eb3-a548-de4c0da8b22b","note_id":"8b969cab-5ef8-57e6-8333-67ebfa661417","title":"Señales precursoras de inestabilidad","narration_text":"La prevención empieza describiendo el trabajo real, no suponiendo que hoy será igual que ayer.\n\nLa primera referencia es: Roca fresca en el piso, chasquidos, lajas, fisuras nuevas o pernos rotos. Malla abombada, convergencia, levantamiento y agua nueva o turbia. Respuesta: excluir, marcar, medir y solicitar evaluación competente.\n\nSituación En una intersección la malla está abombada pero no se aprecia roca en el suelo. El turno propone trabajar debajo porque la malla ha cumplido su función. La roca excavada deja de estar confinada y redistribuye tensiones. Litología, alteración, fallas, juntas, estratificación, orientación, agua, esfuerzos y excavaciones cercanas condicionan el comportamiento. El técnico compara la realidad con el modelo y busca cambios: la misma sección puede ser estable en una orientación e inestable al cruzar una falla o un contacto. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles.\n\nPensemos en una situación de campo. Una malla comienza a abombarse y aparecen fragmentos frescos en el suelo, aunque el sostenimiento no se ha desprendido completamente.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: detectar antes del fallo.","duration_seconds":167,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-018.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-018.png","explanation":"Objetivo\n\nRoca fresca en el piso, chasquidos, lajas, fisuras nuevas o pernos rotos. Malla abombada, convergencia, levantamiento y agua nueva o turbia. Respuesta: excluir, marcar, medir y solicitar evaluación competente.\n\nExplicación detallada\n\nSituación En una intersección la malla está abombada pero no se aprecia roca en el suelo. El turno propone trabajar debajo porque la malla ha cumplido su función. La roca excavada deja de estar confinada y redistribuye tensiones. Litología, alteración, fallas, juntas, estratificación, orientación, agua, esfuerzos y excavaciones cercanas condicionan el comportamiento. El técnico compara la realidad con el modelo y busca cambios: la misma sección puede ser estable en una orientación e inestable al cruzar una falla o un contacto. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles.\n\nLectura guiada de la diapositiva\n\n• Roca fresca en el piso, chasquidos, lajas, fisuras nuevas o pernos rotos. Malla abombada, convergencia, levantamiento y agua nueva o turbia. Respuesta: excluir, marcar, medir y solicitar evaluación competente.\n\nAplicación práctica\n\nUna malla comienza a abombarse y aparecen fragmentos frescos en el suelo, aunque el sostenimiento no se ha desprendido completamente.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nDetectar antes del fallo","key_points":["Roca fresca en el piso, chasquidos, lajas, fisuras nuevas o pernos rotos. Malla abombada, convergencia, levantamiento y agua nueva o turbia. Respuesta: excluir, marcar, medir y solicitar evaluación competente.","Detectar antes del fallo"],"stop_criterion":"Detectar antes del fallo","source_pages":"Bloque 2 · diapositiva 18","question":"Respecto a «Señales precursoras de inestabilidad», ¿qué criterio operativo es correcto?","correct_option":"Detectar antes del fallo: Roca fresca en el piso, chasquidos, lajas, fisuras nuevas o pernos rotos. Malla abombada, convergencia, levantamiento y agua nueva o turbia. Respuesta: excluir, marcar, medir y solicitar evaluación competente.","question_explanation":"Roca fresca en el piso, chasquidos, lajas, fisuras nuevas o pernos rotos. Malla abombada, convergencia, levantamiento y agua nueva o turbia. Respuesta: excluir, marcar, medir y solicitar evaluación competente."},{"slide_number":19,"block_number":2,"lesson_ordinal":2,"segment_position":9,"segment_id":"314ec4ec-2439-5f05-a639-03d0560913da","slide_id":"186c2393-2477-59c6-8afb-48d9424e1371","note_id":"c417b51c-0e8b-5699-aded-360555648e54","title":"Factores que modifican la estabilidad","narration_text":"Bajo tierra, terreno, aire, agua, equipos y secuencia pueden cambiar durante el mismo turno.\n\nConviene comprobar lo siguiente: Orientación de discontinuidades, alteración, esfuerzos y agua. Método, secuencia, dimensiones y excavaciones próximas. Comparar continuamente la realidad observada con el modelo y el diseño.\n\nLa roca excavada deja de estar confinada y redistribuye tensiones. Litología, alteración, fallas, juntas, estratificación, orientación, agua, esfuerzos y excavaciones cercanas condicionan el comportamiento. El técnico compara la realidad con el modelo y busca cambios: la misma sección puede ser estable en una orientación e inestable al cruzar una falla o un contacto. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles. El sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones.\n\nPensemos en una situación de campo. El trabajo empieza dentro de criterio, pero una labor conectada cambia el aire, el agua o la circulación. El equipo debe reconocer el cambio antes de que la condición inicial deje de ser válida.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: buscar cambios.","duration_seconds":150,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-019.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-019.png","explanation":"Objetivo\n\nOrientación de discontinuidades, alteración, esfuerzos y agua. Método, secuencia, dimensiones y excavaciones próximas. Comparar continuamente la realidad observada con el modelo y el diseño.\n\nExplicación detallada\n\nLa roca excavada deja de estar confinada y redistribuye tensiones. Litología, alteración, fallas, juntas, estratificación, orientación, agua, esfuerzos y excavaciones cercanas condicionan el comportamiento. El técnico compara la realidad con el modelo y busca cambios: la misma sección puede ser estable en una orientación e inestable al cruzar una falla o un contacto. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles. El sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones.\n\nLectura guiada de la diapositiva\n\n• Orientación de discontinuidades, alteración, esfuerzos y agua. Método, secuencia, dimensiones y excavaciones próximas. Comparar continuamente la realidad observada con el modelo y el diseño.\n\nAplicación práctica\n\nEl trabajo empieza dentro de criterio, pero una labor conectada cambia el aire, el agua o la circulación. El equipo debe reconocer el cambio antes de que la condición inicial deje de ser válida.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nBuscar cambios","key_points":["Orientación de discontinuidades, alteración, esfuerzos y agua. Método, secuencia, dimensiones y excavaciones próximas. Comparar continuamente la realidad observada con el modelo y el diseño.","Buscar cambios"],"stop_criterion":"Buscar cambios","source_pages":"Bloque 2 · diapositiva 19","question":"Respecto a «Factores que modifican la estabilidad», ¿qué criterio operativo es correcto?","correct_option":"Buscar cambios: Orientación de discontinuidades, alteración, esfuerzos y agua. Método, secuencia, dimensiones y excavaciones próximas. Comparar continuamente la realidad observada con el modelo y el diseño.","question_explanation":"Orientación de discontinuidades, alteración, esfuerzos y agua. Método, secuencia, dimensiones y excavaciones próximas. Comparar continuamente la realidad observada con el modelo y el diseño."},{"slide_number":20,"block_number":2,"lesson_ordinal":2,"segment_position":10,"segment_id":"ca0d3dbc-b9b1-5ac2-96d6-42973534ab2d","slide_id":"72eae674-5b3b-5bed-aaad-dbc896cd5939","note_id":"c3cedc1f-a0e0-504f-9577-6891f6cb9015","title":"Diseño y función del sostenimiento","narration_text":"Supervisar consiste en comparar lo que ocurre en campo con un criterio definido de antemano.\n\nEl punto de partida es: Bulones, cables, malla, hormigón proyectado, cerchas, relleno o soporte hidráulico. Se selecciona según mecanismo de fallo, vida de la labor, deformación admisible y secuencia. Debe definir patrón, capacidad, ensayos y tratamiento de desviaciones.\n\nEl sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles. Situación En una intersección la malla está abombada pero no se aprecia roca en el suelo. El turno propone trabajar debajo porque la malla ha cumplido su función.\n\nPensemos en una situación de campo. Una corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: sostener el mecanismo correcto.","duration_seconds":169,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-020.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-020.png","explanation":"Objetivo\n\nBulones, cables, malla, hormigón proyectado, cerchas, relleno o soporte hidráulico. Se selecciona según mecanismo de fallo, vida de la labor, deformación admisible y secuencia. Debe definir patrón, capacidad, ensayos y tratamiento de desviaciones.\n\nExplicación detallada\n\nEl sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles. Situación En una intersección la malla está abombada pero no se aprecia roca en el suelo. El turno propone trabajar debajo porque la malla ha cumplido su función.\n\nLectura guiada de la diapositiva\n\n• Bulones, cables, malla, hormigón proyectado, cerchas, relleno o soporte hidráulico. Se selecciona según mecanismo de fallo, vida de la labor, deformación admisible y secuencia. Debe definir patrón, capacidad, ensayos y tratamiento de desviaciones.\n\nAplicación práctica\n\nUna corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nSostener el mecanismo correcto","key_points":["Bulones, cables, malla, hormigón proyectado, cerchas, relleno o soporte hidráulico. Se selecciona según mecanismo de fallo, vida de la labor, deformación admisible y secuencia. Debe definir patrón, capacidad, ensayos y tratamiento de desviaciones.","Sostener el mecanismo correcto"],"stop_criterion":"Sostener el mecanismo correcto","source_pages":"Bloque 2 · diapositiva 20","question":"Respecto a «Diseño y función del sostenimiento», ¿qué criterio operativo es correcto?","correct_option":"Sostener el mecanismo correcto: Bulones, cables, malla, hormigón proyectado, cerchas, relleno o soporte hidráulico. Se selecciona según mecanismo de fallo, vida de la labor, deformación admisible y secuencia. Debe definir patrón, capacidad, ensayos y tratamiento de desviaciones.","question_explanation":"Bulones, cables, malla, hormigón proyectado, cerchas, relleno o soporte hidráulico. Se selecciona según mecanismo de fallo, vida de la labor, deformación admisible y secuencia. Debe definir patrón, capacidad, ensayos y tratamiento de desviaciones."},{"slide_number":21,"block_number":2,"lesson_ordinal":3,"segment_position":1,"segment_id":"c018a982-9bf7-5f82-bc29-d3ecba15fa60","slide_id":"b581186c-b0df-5122-ad2e-ae62b507c8a6","note_id":"b87bf748-be8b-5a69-9aba-4e0d506ebd94","title":"Instalación y comprobación del sostenimiento","narration_text":"Una tarea habitual también necesita límites claros y una comprobación proporcionada al riesgo.\n\nPara empezar, se sitúa el criterio: Bulón o cable: taladro, longitud, orientación, resina o lechada, placa y tensión. Malla y hormigón: solape, fijación, espesor, adherencia, drenaje y curado. Cerchas: apoyo, alineación y arriostramiento; revisar deterioro y carga en servicio.\n\nEl sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones. Criterio de resolución La malla ha retenido una carga y su capacidad residual no está demostrada. Se excluye la zona, se evalúa la extensión y se descarga o refuerza con un método aprobado antes de reabrir. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles.\n\nPensemos en una situación de campo. El turno saliente conoce una limitación temporal, pero no la registra. El turno entrante recibe la zona como disponible y actúa con una información incompleta.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: calidad de instalación.","duration_seconds":142,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-021.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-021.png","explanation":"Objetivo\n\nBulón o cable: taladro, longitud, orientación, resina o lechada, placa y tensión. Malla y hormigón: solape, fijación, espesor, adherencia, drenaje y curado. Cerchas: apoyo, alineación y arriostramiento; revisar deterioro y carga en servicio.\n\nExplicación detallada\n\nEl sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones. Criterio de resolución La malla ha retenido una carga y su capacidad residual no está demostrada. Se excluye la zona, se evalúa la extensión y se descarga o refuerza con un método aprobado antes de reabrir. La caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles.\n\nLectura guiada de la diapositiva\n\n• Bulón o cable: taladro, longitud, orientación, resina o lechada, placa y tensión. Malla y hormigón: solape, fijación, espesor, adherencia, drenaje y curado. Cerchas: apoyo, alineación y arriostramiento; revisar deterioro y carga en servicio.\n\nAplicación práctica\n\nEl turno saliente conoce una limitación temporal, pero no la registra. El turno entrante recibe la zona como disponible y actúa con una información incompleta.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nCalidad de instalación","key_points":["Bulón o cable: taladro, longitud, orientación, resina o lechada, placa y tensión. Malla y hormigón: solape, fijación, espesor, adherencia, drenaje y curado. Cerchas: apoyo, alineación y arriostramiento; revisar deterioro y carga en servicio.","Calidad de instalación"],"stop_criterion":"Calidad de instalación","source_pages":"Bloque 2 · diapositiva 21","question":"Respecto a «Instalación y comprobación del sostenimiento», ¿qué criterio operativo es correcto?","correct_option":"Calidad de instalación: Bulón o cable: taladro, longitud, orientación, resina o lechada, placa y tensión. Malla y hormigón: solape, fijación, espesor, adherencia, drenaje y curado. Cerchas: apoyo, alineación y arriostramiento; revisar deterioro y carga en servicio.","question_explanation":"Bulón o cable: taladro, longitud, orientación, resina o lechada, placa y tensión. Malla y hormigón: solape, fijación, espesor, adherencia, drenaje y curado. Cerchas: apoyo, alineación y arriostramiento; revisar deterioro y carga en servicio."},{"slide_number":22,"block_number":2,"lesson_ordinal":3,"segment_position":2,"segment_id":"70be64b2-c547-5bf4-90e1-827a9cbad6b2","slide_id":"3788691e-5806-545f-93cc-e0dd8127fe7b","note_id":"9e65ed16-5784-5e2e-a813-675bcd6d2dbd","title":"Saneo e inspección del terreno","narration_text":"La decisión técnica debe precisar qué se acepta, qué obliga a parar y qué permite reanudar.\n\nLa primera referencia es: Delimitar y evitar exposición bajo roca suelta. Inspeccionar desde terreno confirmado seguro y sanear fuera de la trayectoria con retirada disponible. Sostener en la secuencia definida, comprobar calidad y registrar anomalías.\n\nLa caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles. El sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones. La roca excavada deja de estar confinada y redistribuye tensiones. Litología, alteración, fallas, juntas, estratificación, orientación, agua, esfuerzos y excavaciones cercanas condicionan el comportamiento. El técnico compara la realidad con el modelo y busca cambios: la misma sección puede ser estable en una orientación e inestable al cruzar una falla o un contacto.\n\nPensemos en una situación de campo. La medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: nunca trabajar bajo lo no verificado.","duration_seconds":152,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-022.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-022.png","explanation":"Objetivo\n\nDelimitar y evitar exposición bajo roca suelta. Inspeccionar desde terreno confirmado seguro y sanear fuera de la trayectoria con retirada disponible. Sostener en la secuencia definida, comprobar calidad y registrar anomalías.\n\nExplicación detallada\n\nLa caída de rocas y la inestabilidad del macizo se controlan desde el diseño hasta la inspección diaria. El sostenimiento no corrige un método o una secuencia incompatibles. El sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones. La roca excavada deja de estar confinada y redistribuye tensiones. Litología, alteración, fallas, juntas, estratificación, orientación, agua, esfuerzos y excavaciones cercanas condicionan el comportamiento. El técnico compara la realidad con el modelo y busca cambios: la misma sección puede ser estable en una orientación e inestable al cruzar una falla o un contacto.\n\nLectura guiada de la diapositiva\n\n• Delimitar y evitar exposición bajo roca suelta. Inspeccionar desde terreno confirmado seguro y sanear fuera de la trayectoria con retirada disponible. Sostener en la secuencia definida, comprobar calidad y registrar anomalías.\n\nAplicación práctica\n\nLa medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nNunca trabajar bajo lo no verificado","key_points":["Delimitar y evitar exposición bajo roca suelta. Inspeccionar desde terreno confirmado seguro y sanear fuera de la trayectoria con retirada disponible. Sostener en la secuencia definida, comprobar calidad y registrar anomalías.","Nunca trabajar bajo lo no verificado"],"stop_criterion":"Nunca trabajar bajo lo no verificado","source_pages":"Bloque 2 · diapositiva 22","question":"Respecto a «Saneo e inspección del terreno», ¿qué criterio operativo es correcto?","correct_option":"Nunca trabajar bajo lo no verificado: Delimitar y evitar exposición bajo roca suelta. Inspeccionar desde terreno confirmado seguro y sanear fuera de la trayectoria con retirada disponible. Sostener en la secuencia definida, comprobar calidad y registrar anomalías.","question_explanation":"Delimitar y evitar exposición bajo roca suelta. Inspeccionar desde terreno confirmado seguro y sanear fuera de la trayectoria con retirada disponible. Sostener en la secuencia definida, comprobar calidad y registrar anomalías."},{"slide_number":23,"block_number":2,"lesson_ordinal":3,"segment_position":3,"segment_id":"c9a07790-bb68-5db7-8182-525052b52244","slide_id":"9e9d06a0-db4e-5de5-b074-6bd82a439a05","note_id":"e076e45a-f8db-5fca-8c0f-5f08144cd867","title":"Caso práctico de control geotécnico","narration_text":"Una barrera preventiva solo es útil cuando puede observarse, medirse o probarse.\n\nConviene comprobar lo siguiente: Una malla abombada indica que ha retenido carga, aunque no haya roca en el suelo. Su capacidad residual no está demostrada. Excluir la zona, evaluar la extensión y descargar o reforzar mediante un método aprobado antes de reabrir.\n\nCriterio de resolución La malla ha retenido una carga y su capacidad residual no está demostrada. Se excluye la zona, se evalúa la extensión y se descarga o refuerza con un método aprobado antes de reabrir. Situación En una intersección la malla está abombada pero no se aprecia roca en el suelo. El turno propone trabajar debajo porque la malla ha cumplido su función. El sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones.\n\nPensemos en una situación de campo. La malla ha retenido roca en una intersección. Trabajar debajo porque no ha caído material confunde contención inicial con capacidad residual demostrada.\n\nLa aplicación práctica sigue siempre el mismo orden: observar desde una zona confirmada segura, retirar la exposición, delimitar el alcance y comparar la realidad con el diseño y la disposición interna de seguridad. Después se corrige mediante un método aprobado y se verifica el resultado. La ausencia de caída, alarma o lesión no demuestra que la barrera conserve capacidad.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: la ausencia de caída no prueba seguridad.","duration_seconds":176,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-023.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-023.png","explanation":"Objetivo\n\nUna malla abombada indica que ha retenido carga, aunque no haya roca en el suelo. Su capacidad residual no está demostrada. Excluir la zona, evaluar la extensión y descargar o reforzar mediante un método aprobado antes de reabrir.\n\nExplicación detallada\n\nCriterio de resolución La malla ha retenido una carga y su capacidad residual no está demostrada. Se excluye la zona, se evalúa la extensión y se descarga o refuerza con un método aprobado antes de reabrir. Situación En una intersección la malla está abombada pero no se aprecia roca en el suelo. El turno propone trabajar debajo porque la malla ha cumplido su función. El sistema puede combinar bulones, cables, malla, hormigón proyectado, cerchas, madera, relleno o sostenimiento hidráulico. La selección depende del mecanismo de fallo, la vida de la labor, la deformación admisible y la secuencia. Deben definirse patrón, longitud, orientación, capacidad, solapes, calidad de instalación, ensayos y tratamiento de desviaciones.\n\nLectura guiada de la diapositiva\n\n• Una malla abombada indica que ha retenido carga, aunque no haya roca en el suelo. Su capacidad residual no está demostrada. Excluir la zona, evaluar la extensión y descargar o reforzar mediante un método aprobado antes de reabrir.\n\nAplicación práctica\n\nLa malla ha retenido roca en una intersección. Trabajar debajo porque no ha caído material confunde contención inicial con capacidad residual demostrada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nLa ausencia de caída no prueba seguridad","key_points":["Una malla abombada indica que ha retenido carga, aunque no haya roca en el suelo. Su capacidad residual no está demostrada. Excluir la zona, evaluar la extensión y descargar o reforzar mediante un método aprobado antes de reabrir.","La ausencia de caída no prueba seguridad"],"stop_criterion":"La ausencia de caída no prueba seguridad","source_pages":"Bloque 2 · diapositiva 23","question":"Respecto a «Caso práctico de control geotécnico», ¿qué criterio operativo es correcto?","correct_option":"La ausencia de caída no prueba seguridad: Una malla abombada indica que ha retenido carga, aunque no haya roca en el suelo. Su capacidad residual no está demostrada. Excluir la zona, evaluar la extensión y descargar o reforzar mediante un método aprobado antes de reabrir.","question_explanation":"Una malla abombada indica que ha retenido carga, aunque no haya roca en el suelo. Su capacidad residual no está demostrada. Excluir la zona, evaluar la extensión y descargar o reforzar mediante un método aprobado antes de reabrir."},{"slide_number":24,"block_number":2,"lesson_ordinal":3,"segment_position":4,"segment_id":"755c1870-e91b-5db9-9ddb-fb070807dcee","slide_id":"beb1ad2b-2eba-5cbf-860f-7992d030f0f4","note_id":"38db44ba-ee57-58fe-8138-a8d25b00543c","title":"Objetivos de la ventilación subterránea","narration_text":"Antes de autorizar hay que entender qué puede cambiar y hasta dónde llegarían sus efectos.\n\nEl punto de partida es: Aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal total no demuestra que el frente reciba aire limpio. También debe comprobarse que el retorno sea seguro y no recircule contaminantes.\n\nLa ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. El sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nPensemos en una situación de campo. El instrumento ofrece una lectura, pero no representa el punto de mayor exposición. Medir sin elegir bien lugar y momento puede producir una falsa sensación de control.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: aire útil en el puesto.","duration_seconds":167,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-024.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-024.png","explanation":"Objetivo\n\nAportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal total no demuestra que el frente reciba aire limpio. También debe comprobarse que el retorno sea seguro y no recircule contaminantes.\n\nExplicación detallada\n\nLa ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. El sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nLectura guiada de la diapositiva\n\n• Aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal total no demuestra que el frente reciba aire limpio. También debe comprobarse que el retorno sea seguro y no recircule contaminantes.\n\nAplicación práctica\n\nEl instrumento ofrece una lectura, pero no representa el punto de mayor exposición. Medir sin elegir bien lugar y momento puede producir una falsa sensación de control.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nAire útil en el puesto","key_points":["Aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal total no demuestra que el frente reciba aire limpio. También debe comprobarse que el retorno sea seguro y no recircule contaminantes.","Aire útil en el puesto"],"stop_criterion":"Aire útil en el puesto","source_pages":"Bloque 2 · diapositiva 24","question":"Respecto a «Objetivos de la ventilación subterránea», ¿qué criterio operativo es correcto?","correct_option":"Aire útil en el puesto: Aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal total no demuestra que el frente reciba aire limpio. También debe comprobarse que el retorno sea seguro y no recircule contaminantes.","question_explanation":"Aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal total no demuestra que el frente reciba aire limpio. También debe comprobarse que el retorno sea seguro y no recircule contaminantes."},{"slide_number":25,"block_number":2,"lesson_ordinal":3,"segment_position":5,"segment_id":"ccd631f0-6f64-559d-bcb1-cc182abc66fe","slide_id":"ddd7cbf5-2d9b-5bc9-80ff-bf475172b7fe","note_id":"2b3f67c9-9f8f-5836-96d8-146261c32939","title":"Circuito principal de ventilación","narration_text":"La primera pregunta no es cómo producir más rápido, sino qué condición debe conservarse segura.\n\nPara empezar, se sitúa el criterio: Entradas, retornos, ventiladores, puertas, esclusas, tabiques, reguladores, cruces y sellados. Abrir, cerrar u obstruir un elemento redistribuye el aire. Los planos deben reflejar el circuito real y todo cambio temporal debe diseñarse, comunicarse y comprobarse.\n\nEl sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse. La ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nPensemos en una situación de campo. Imagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: circuito real y actualizado.","duration_seconds":170,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-025.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-025.png","explanation":"Objetivo\n\nEntradas, retornos, ventiladores, puertas, esclusas, tabiques, reguladores, cruces y sellados. Abrir, cerrar u obstruir un elemento redistribuye el aire. Los planos deben reflejar el circuito real y todo cambio temporal debe diseñarse, comunicarse y comprobarse.\n\nExplicación detallada\n\nEl sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse. La ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nLectura guiada de la diapositiva\n\n• Entradas, retornos, ventiladores, puertas, esclusas, tabiques, reguladores, cruces y sellados. Abrir, cerrar u obstruir un elemento redistribuye el aire. Los planos deben reflejar el circuito real y todo cambio temporal debe diseñarse, comunicarse y comprobarse.\n\nAplicación práctica\n\nImagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nCircuito real y actualizado","key_points":["Entradas, retornos, ventiladores, puertas, esclusas, tabiques, reguladores, cruces y sellados. Abrir, cerrar u obstruir un elemento redistribuye el aire. Los planos deben reflejar el circuito real y todo cambio temporal debe diseñarse, comunicarse y comprobarse.","Circuito real y actualizado"],"stop_criterion":"Circuito real y actualizado","source_pages":"Bloque 2 · diapositiva 25","question":"Respecto a «Circuito principal de ventilación», ¿qué criterio operativo es correcto?","correct_option":"Circuito real y actualizado: Entradas, retornos, ventiladores, puertas, esclusas, tabiques, reguladores, cruces y sellados. Abrir, cerrar u obstruir un elemento redistribuye el aire. Los planos deben reflejar el circuito real y todo cambio temporal debe diseñarse, comunicarse y comprobarse.","question_explanation":"Entradas, retornos, ventiladores, puertas, esclusas, tabiques, reguladores, cruces y sellados. Abrir, cerrar u obstruir un elemento redistribuye el aire. Los planos deben reflejar el circuito real y todo cambio temporal debe diseñarse, comunicarse y comprobarse."},{"slide_number":26,"block_number":2,"lesson_ordinal":3,"segment_position":6,"segment_id":"d4ca7544-fa08-511c-b321-19e0fc2463b6","slide_id":"eb864d33-d531-5360-8c8f-57b6418cd90c","note_id":"45ebb4d2-f959-54fe-bb62-11a05320c201","title":"Ventilación secundaria y conductos","narration_text":"En una labor conectada con otras, una decisión local nunca se analiza de forma aislada.\n\nLa primera referencia es: El ventilador auxiliar lleva aire hasta el frente ciego. Fallos: parada, giro incorrecto, recirculación, mala ubicación o distancia excesiva. El conducto puede romperse, separarse, aplastarse, fugar o terminar lejos del frente.\n\nEl sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse. Situación El anemómetro confirma caudal en la galería. El conducto auxiliar termina lejos del frente y el equipo diésel trabaja entre el extremo y la zona de perforación. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nPensemos en una situación de campo. El ventilador auxiliar funciona, pero el conducto termina lejos del frente y el aire limpio no barre la zona donde opera un equipo diésel.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: el extremo importa.","duration_seconds":160,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-026.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-026.png","explanation":"Objetivo\n\nEl ventilador auxiliar lleva aire hasta el frente ciego. Fallos: parada, giro incorrecto, recirculación, mala ubicación o distancia excesiva. El conducto puede romperse, separarse, aplastarse, fugar o terminar lejos del frente.\n\nExplicación detallada\n\nEl sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse. Situación El anemómetro confirma caudal en la galería. El conducto auxiliar termina lejos del frente y el equipo diésel trabaja entre el extremo y la zona de perforación. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nLectura guiada de la diapositiva\n\n• El ventilador auxiliar lleva aire hasta el frente ciego. Fallos: parada, giro incorrecto, recirculación, mala ubicación o distancia excesiva. El conducto puede romperse, separarse, aplastarse, fugar o terminar lejos del frente.\n\nAplicación práctica\n\nEl ventilador auxiliar funciona, pero el conducto termina lejos del frente y el aire limpio no barre la zona donde opera un equipo diésel.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nEl extremo importa","key_points":["El ventilador auxiliar lleva aire hasta el frente ciego. Fallos: parada, giro incorrecto, recirculación, mala ubicación o distancia excesiva. El conducto puede romperse, separarse, aplastarse, fugar o terminar lejos del frente.","El extremo importa"],"stop_criterion":"El extremo importa","source_pages":"Bloque 2 · diapositiva 26","question":"Respecto a «Ventilación secundaria y conductos», ¿qué criterio operativo es correcto?","correct_option":"El extremo importa: El ventilador auxiliar lleva aire hasta el frente ciego. Fallos: parada, giro incorrecto, recirculación, mala ubicación o distancia excesiva. El conducto puede romperse, separarse, aplastarse, fugar o terminar lejos del frente.","question_explanation":"El ventilador auxiliar lleva aire hasta el frente ciego. Fallos: parada, giro incorrecto, recirculación, mala ubicación o distancia excesiva. El conducto puede romperse, separarse, aplastarse, fugar o terminar lejos del frente."},{"slide_number":27,"block_number":2,"lesson_ordinal":3,"segment_position":7,"segment_id":"726180be-747f-5f66-9840-cbfe711393b1","slide_id":"dc61999b-8d3d-59b2-8bae-6827ccc3ed36","note_id":"453ff9b8-42b8-5492-adcf-30051b4a0c4c","title":"Caudal, velocidad y distribución del aire","narration_text":"El control empieza por reconocer la señal temprana, antes de que el peligro alcance a alguien.\n\nConviene comprobar lo siguiente: Medir con método y sección adecuados y registrar ubicación, hora y estado productivo. Comparar con el criterio definido en el Documento sobre Seguridad y Salud o la disposición interna de seguridad. Caudal en la galería no equivale a aire limpio en la zona respiratoria.\n\nLa ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. Situación El anemómetro confirma caudal en la galería. El conducto auxiliar termina lejos del frente y el equipo diésel trabaja entre el extremo y la zona de perforación. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nPensemos en una situación de campo. Producción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: medir donde importa.","duration_seconds":164,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-027.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-027.png","explanation":"Objetivo\n\nMedir con método y sección adecuados y registrar ubicación, hora y estado productivo. Comparar con el criterio definido en el DSS o la DIS. Caudal en la galería no equivale a aire limpio en la zona respiratoria.\n\nExplicación detallada\n\nLa ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. Situación El anemómetro confirma caudal en la galería. El conducto auxiliar termina lejos del frente y el equipo diésel trabaja entre el extremo y la zona de perforación. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nLectura guiada de la diapositiva\n\n• Medir con método y sección adecuados y registrar ubicación, hora y estado productivo. Comparar con el criterio definido en el DSS o la DIS. Caudal en la galería no equivale a aire limpio en la zona respiratoria.\n\nAplicación práctica\n\nProducción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nMedir donde importa","key_points":["Medir con método y sección adecuados y registrar ubicación, hora y estado productivo. Comparar con el criterio definido en el DSS o la DIS. Caudal en la galería no equivale a aire limpio en la zona respiratoria.","Medir donde importa"],"stop_criterion":"Medir donde importa","source_pages":"Bloque 2 · diapositiva 27","question":"Respecto a «Caudal, velocidad y distribución del aire», ¿qué criterio operativo es correcto?","correct_option":"Medir donde importa: Medir con método y sección adecuados y registrar ubicación, hora y estado productivo. Comparar con el criterio definido en el DSS o la DIS. Caudal en la galería no equivale a aire limpio en la zona respiratoria.","question_explanation":"Medir con método y sección adecuados y registrar ubicación, hora y estado productivo. Comparar con el criterio definido en el DSS o la DIS. Caudal en la galería no equivale a aire limpio en la zona respiratoria."},{"slide_number":28,"block_number":2,"lesson_ordinal":3,"segment_position":8,"segment_id":"8b82164c-b890-5a2d-8308-4ef0b1f3f871","slide_id":"b760b0d7-ba0a-567b-8e94-86b2737d8229","note_id":"66890192-c5b4-5618-a892-f9143298fab4","title":"Recirculación, fugas y cortocircuitos","narration_text":"Una comprobación útil termina en una decisión concreta: continuar, corregir o detener.\n\nEl punto de partida es: Un cortocircuito lleva aire de entrada a retorno sin barrer la zona prevista. Puertas, tabiques, sellados y conductos dañados provocan fugas. La recirculación devuelve contaminantes: corregir la causa y repetir la medición.\n\nEl sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse. La ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nPensemos en una situación de campo. La tarea se ha realizado muchas veces sin incidente. Ese historial no demuestra que el peligro haya desaparecido; puede significar únicamente que todavía no coincidieron fallo y exposición.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: corregir y volver a medir.","duration_seconds":163,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-028.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-028.png","explanation":"Objetivo\n\nUn cortocircuito lleva aire de entrada a retorno sin barrer la zona prevista. Puertas, tabiques, sellados y conductos dañados provocan fugas. La recirculación devuelve contaminantes: corregir la causa y repetir la medición.\n\nExplicación detallada\n\nEl sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse. La ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar.\n\nLectura guiada de la diapositiva\n\n• Un cortocircuito lleva aire de entrada a retorno sin barrer la zona prevista. Puertas, tabiques, sellados y conductos dañados provocan fugas. La recirculación devuelve contaminantes: corregir la causa y repetir la medición.\n\nAplicación práctica\n\nLa tarea se ha realizado muchas veces sin incidente. Ese historial no demuestra que el peligro haya desaparecido; puede significar únicamente que todavía no coincidieron fallo y exposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nCorregir y volver a medir","key_points":["Un cortocircuito lleva aire de entrada a retorno sin barrer la zona prevista. Puertas, tabiques, sellados y conductos dañados provocan fugas. La recirculación devuelve contaminantes: corregir la causa y repetir la medición.","Corregir y volver a medir"],"stop_criterion":"Corregir y volver a medir","source_pages":"Bloque 2 · diapositiva 28","question":"Respecto a «Recirculación, fugas y cortocircuitos», ¿qué criterio operativo es correcto?","correct_option":"Corregir y volver a medir: Un cortocircuito lleva aire de entrada a retorno sin barrer la zona prevista. Puertas, tabiques, sellados y conductos dañados provocan fugas. La recirculación devuelve contaminantes: corregir la causa y repetir la medición.","question_explanation":"Un cortocircuito lleva aire de entrada a retorno sin barrer la zona prevista. Puertas, tabiques, sellados y conductos dañados provocan fugas. La recirculación devuelve contaminantes: corregir la causa y repetir la medición."},{"slide_number":29,"block_number":2,"lesson_ordinal":3,"segment_position":9,"segment_id":"24dc0c37-30c3-50fa-8764-3ec04cbd465a","slide_id":"45baf6ad-06f2-5d06-8b87-16d17caae4e0","note_id":"aa9e7a85-d818-54ce-9d10-9d162bfb1e93","title":"Comprobación de la ventilación en un frente","narration_text":"La ausencia de un incidente no demuestra que las barreras sigan disponibles.\n\nPara empezar, se sitúa el criterio: Confirmar el sistema en servicio y sin recirculación. Medir caudal o velocidad, revisar conducto y medir oxígeno y contaminantes en puntos representativos. Aplicar el criterio de parada y reentrada cuando el resultado esté fuera de rango.\n\nLa ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar. Situación El anemómetro confirma caudal en la galería. El conducto auxiliar termina lejos del frente y el equipo diésel trabaja entre el extremo y la zona de perforación.\n\nPensemos en una situación de campo. Una lectura correcta junto al conducto no representa necesariamente la zona respiratoria ni los puntos donde pueden acumularse gases.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: verificación completa.","duration_seconds":155,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-029.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-029.png","explanation":"Objetivo\n\nConfirmar el sistema en servicio y sin recirculación. Medir caudal o velocidad, revisar conducto y medir oxígeno y contaminantes en puntos representativos. Aplicar el criterio de parada y reentrada cuando el resultado esté fuera de rango.\n\nExplicación detallada\n\nLa ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. Criterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar. Situación El anemómetro confirma caudal en la galería. El conducto auxiliar termina lejos del frente y el equipo diésel trabaja entre el extremo y la zona de perforación.\n\nLectura guiada de la diapositiva\n\n• Confirmar el sistema en servicio y sin recirculación. Medir caudal o velocidad, revisar conducto y medir oxígeno y contaminantes en puntos representativos. Aplicar el criterio de parada y reentrada cuando el resultado esté fuera de rango.\n\nAplicación práctica\n\nUna lectura correcta junto al conducto no representa necesariamente la zona respiratoria ni los puntos donde pueden acumularse gases.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nVerificación completa","key_points":["Confirmar el sistema en servicio y sin recirculación. Medir caudal o velocidad, revisar conducto y medir oxígeno y contaminantes en puntos representativos. Aplicar el criterio de parada y reentrada cuando el resultado esté fuera de rango.","Verificación completa"],"stop_criterion":"Verificación completa","source_pages":"Bloque 2 · diapositiva 29","question":"Respecto a «Comprobación de la ventilación en un frente», ¿qué criterio operativo es correcto?","correct_option":"Verificación completa: Confirmar el sistema en servicio y sin recirculación. Medir caudal o velocidad, revisar conducto y medir oxígeno y contaminantes en puntos representativos. Aplicar el criterio de parada y reentrada cuando el resultado esté fuera de rango.","question_explanation":"Confirmar el sistema en servicio y sin recirculación. Medir caudal o velocidad, revisar conducto y medir oxígeno y contaminantes en puntos representativos. Aplicar el criterio de parada y reentrada cuando el resultado esté fuera de rango."},{"slide_number":30,"block_number":2,"lesson_ordinal":3,"segment_position":10,"segment_id":"ee277abf-b745-526b-b02b-74f35dbe6484","slide_id":"9100187d-799d-55c6-bcd7-1c4962f78b19","note_id":"9972f675-279e-5ab0-b7b2-78b4e10a5d3c","title":"Fallos de ventilación y condiciones de parada","narration_text":"Cuando falta un dato crítico, conservar el estado seguro es también una decisión técnica.\n\nLa primera referencia es: Parar ante pérdida, inversión, reducción no autorizada, recirculación, alarma o imposibilidad de medir. Retirar exposición, aislar y corregir. Verificar condiciones representativas antes de autorizar la reentrada.\n\nCriterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar. La ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. El sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse.\n\nPensemos en una situación de campo. La observación parece tranquilizadora, aunque falta una comprobación instrumental o funcional. Si la decisión depende de ese dato, la actividad permanece detenida hasta obtenerlo.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: sin verificación no hay reapertura.","duration_seconds":161,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-030.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-030.png","explanation":"Objetivo\n\nParar ante pérdida, inversión, reducción no autorizada, recirculación, alarma o imposibilidad de medir. Retirar exposición, aislar y corregir. Verificar condiciones representativas antes de autorizar la reentrada.\n\nExplicación detallada\n\nCriterio de resolución El aire puede cortocircuitar o no barrer el volumen del frente, mientras los gases se generan aguas abajo del punto medido. Se corrige el conducto y se miden contaminantes en condiciones representativas antes de reanudar. La ventilación debe aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal por sí solo no demuestra que el frente reciba aire limpio ni que el retorno sea seguro. El sistema incluye entradas, retornos, ventiladores, puertas, tabiques, reguladores, cruces, sellados y ventilación auxiliar. Cada apertura o bloqueo modifica resistencias y puede redistribuir el aire. Los planos deben reflejar el circuito real, y los cambios temporales deben diseñarse, comunicarse y comprobarse.\n\nLectura guiada de la diapositiva\n\n• Parar ante pérdida, inversión, reducción no autorizada, recirculación, alarma o imposibilidad de medir. Retirar exposición, aislar y corregir. Verificar condiciones representativas antes de autorizar la reentrada.\n\nAplicación práctica\n\nLa observación parece tranquilizadora, aunque falta una comprobación instrumental o funcional. Si la decisión depende de ese dato, la actividad permanece detenida hasta obtenerlo.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nSin verificación no hay reapertura","key_points":["Parar ante pérdida, inversión, reducción no autorizada, recirculación, alarma o imposibilidad de medir. Retirar exposición, aislar y corregir. Verificar condiciones representativas antes de autorizar la reentrada.","Sin verificación no hay reapertura"],"stop_criterion":"Sin verificación no hay reapertura","source_pages":"Bloque 2 · diapositiva 30","question":"Respecto a «Fallos de ventilación y condiciones de parada», ¿qué criterio operativo es correcto?","correct_option":"Sin verificación no hay reapertura: Parar ante pérdida, inversión, reducción no autorizada, recirculación, alarma o imposibilidad de medir. Retirar exposición, aislar y corregir. Verificar condiciones representativas antes de autorizar la reentrada.","question_explanation":"Parar ante pérdida, inversión, reducción no autorizada, recirculación, alarma o imposibilidad de medir. Retirar exposición, aislar y corregir. Verificar condiciones representativas antes de autorizar la reentrada."},{"slide_number":31,"block_number":2,"lesson_ordinal":4,"segment_position":1,"segment_id":"7999d4d6-0163-5afc-a95c-eafa2f509e23","slide_id":"0fa1656b-831a-5617-aaf5-f3299eb9039f","note_id":"d2979efc-4720-5bcd-9144-8e72b7196bd4","title":"Atmósferas peligrosas y deficiencia de oxígeno","narration_text":"El criterio debe ser comprensible para quien ejecuta, para quien supervisa y para el turno siguiente.\n\nConviene comprobar lo siguiente: Los gases no se detectan de forma fiable por olor ni por síntomas. Con carácter general, el oxígeno no debe ser inferior al 19 % en volumen. El déficit puede reducir juicio y consciencia; deben prevalecer los criterios más restrictivos.\n\nLos gases no se perciben de forma fiable por el olor o por síntomas. La medición debe planificarse, realizarse con instrumentos aptos y conducir a una acción definida. La ITC 04.7.06 fija valores límite ambientales para gases tóxicos en actividades subterráneas. La tabla resume VLA ED y VLA EC en partes por millón. La evaluación debe considerar mezclas, picos, duración, ubicación y condiciones del trabajo. Alcanzar un límite no es un objetivo de operación. Para minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC. La explotación debe aplicar sus alarmas y desconexiones reglamentarias y, si son más restrictivas, las del Documento sobre Seguridad y Salud o la disposición interna de seguridad.\n\nPensemos en una situación de campo. Tras una parada prolongada, el acceso parece normal y no hay olor, pero la atmósfera puede haber perdido oxígeno o acumulado contaminantes.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: medir antes de entrar.","duration_seconds":162,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-031.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-031.png","explanation":"Objetivo\n\nLos gases no se detectan de forma fiable por olor ni por síntomas. Con carácter general, el oxígeno no debe ser inferior al 19 % en volumen. El déficit puede reducir juicio y consciencia; deben prevalecer los criterios más restrictivos.\n\nExplicación detallada\n\nLos gases no se perciben de forma fiable por el olor o por síntomas. La medición debe planificarse, realizarse con instrumentos aptos y conducir a una acción definida. La ITC 04.7.06 fija valores límite ambientales para gases tóxicos en actividades subterráneas. La tabla resume VLA ED y VLA EC en partes por millón. La evaluación debe considerar mezclas, picos, duración, ubicación y condiciones del trabajo. Alcanzar un límite no es un objetivo de operación. Para minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC. La explotación debe aplicar sus alarmas y desconexiones reglamentarias y, si son más restrictivas, las del Documento sobre Seguridad y Salud o la disposición interna de seguridad.\n\nLectura guiada de la diapositiva\n\n• Los gases no se detectan de forma fiable por olor ni por síntomas. Con carácter general, el oxígeno no debe ser inferior al 19 % en volumen. El déficit puede reducir juicio y consciencia; deben prevalecer los criterios más restrictivos.\n\nAplicación práctica\n\nTras una parada prolongada, el acceso parece normal y no hay olor, pero la atmósfera puede haber perdido oxígeno o acumulado contaminantes.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nMedir antes de entrar","key_points":["Los gases no se detectan de forma fiable por olor ni por síntomas. Con carácter general, el oxígeno no debe ser inferior al 19 % en volumen. El déficit puede reducir juicio y consciencia; deben prevalecer los criterios más restrictivos.","Medir antes de entrar"],"stop_criterion":"Medir antes de entrar","source_pages":"Bloque 2 · diapositiva 31","question":"Respecto a «Atmósferas peligrosas y deficiencia de oxígeno», ¿qué criterio operativo es correcto?","correct_option":"Medir antes de entrar: Los gases no se detectan de forma fiable por olor ni por síntomas. Con carácter general, el oxígeno no debe ser inferior al 19 % en volumen. El déficit puede reducir juicio y consciencia; deben prevalecer los criterios más restrictivos.","question_explanation":"Los gases no se detectan de forma fiable por olor ni por síntomas. Con carácter general, el oxígeno no debe ser inferior al 19 % en volumen. El déficit puede reducir juicio y consciencia; deben prevalecer los criterios más restrictivos."},{"slide_number":32,"block_number":2,"lesson_ordinal":4,"segment_position":2,"segment_id":"9ec0a576-50c9-58ea-a213-75a85d4ae35a","slide_id":"336a03b4-cabe-5895-9c8c-aff6fc766a01","note_id":"19bcac34-f4fd-583e-b933-7699ce33a047","title":"Gases tóxicos y valores de referencia","narration_text":"Cada autorización necesita una condición de partida y una señal inequívoca de pérdida de control.\n\nEl punto de partida es: CO: 25 partes por millón valor límite ambiental de exposición diaria y 100 partes por millón valor límite ambiental de corta duración. dióxido de carbono: 5.000 y 12.500 partes por millón. dióxido de azufre: 0,5 y 1 partes por millón. sulfuro de hidrógeno: 5 y 10 partes por millón. NO: 25 y 30 partes por millón. dióxido de nitrógeno: 3 y 5 partes por millón. Considerar mezclas, picos, duración, lugar y condiciones; alcanzar el límite no es un objetivo.\n\nLa ITC 04.7.06 fija valores límite ambientales para gases tóxicos en actividades subterráneas. La tabla resume VLA ED y VLA EC en partes por millón. La evaluación debe considerar mezclas, picos, duración, ubicación y condiciones del trabajo. Alcanzar un límite no es un objetivo de operación. Los gases no se perciben de forma fiable por el olor o por síntomas. La medición debe planificarse, realizarse con instrumentos aptos y conducir a una acción definida. Para minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC.\n\nPensemos en una situación de campo. Una corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: valores del manual.","duration_seconds":168,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-032.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-032.png","explanation":"Objetivo\n\nCO: 25 ppm VLA-ED y 100 ppm VLA-EC. CO2: 5.000 y 12.500 ppm. SO2: 0,5 y 1 ppm. H2S: 5 y 10 ppm. NO: 25 y 30 ppm. NO2: 3 y 5 ppm. Considerar mezclas, picos, duración, lugar y condiciones; alcanzar el límite no es un objetivo.\n\nExplicación detallada\n\nLa ITC 04.7.06 fija valores límite ambientales para gases tóxicos en actividades subterráneas. La tabla resume VLA ED y VLA EC en partes por millón. La evaluación debe considerar mezclas, picos, duración, ubicación y condiciones del trabajo. Alcanzar un límite no es un objetivo de operación. Los gases no se perciben de forma fiable por el olor o por síntomas. La medición debe planificarse, realizarse con instrumentos aptos y conducir a una acción definida. Para minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC. La explotación debe aplicar sus alarmas y desconexiones reglamentarias y, si son más restrictivas, las del Documento sobre Seguridad y Salud o la disposición interna de seguridad.\n\nLectura guiada de la diapositiva\n\n• CO: 25 ppm VLA-ED y 100 ppm VLA-EC. CO2: 5.000 y 12.500 ppm. SO2: 0,5 y 1 ppm. H2S: 5 y 10 ppm. NO: 25 y 30 ppm. NO2: 3 y 5 ppm. Considerar mezclas, picos, duración, lugar y condiciones; alcanzar el límite no es un objetivo.\n\nAplicación práctica\n\nUna corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nValores del manual","key_points":["CO: 25 ppm VLA-ED y 100 ppm VLA-EC. CO2: 5.000 y 12.500 ppm. SO2: 0,5 y 1 ppm. H2S: 5 y 10 ppm. NO: 25 y 30 ppm. NO2: 3 y 5 ppm. Considerar mezclas, picos, duración, lugar y condiciones; alcanzar el límite no es un objetivo.","Valores del manual"],"stop_criterion":"Valores del manual","source_pages":"Bloque 2 · diapositiva 32","question":"Respecto a «Gases tóxicos y valores de referencia», ¿qué criterio operativo es correcto?","correct_option":"Valores del manual: CO: 25 ppm VLA-ED y 100 ppm VLA-EC. CO2: 5.000 y 12.500 ppm. SO2: 0,5 y 1 ppm. H2S: 5 y 10 ppm. NO: 25 y 30 ppm. NO2: 3 y 5 ppm. Considerar mezclas, picos, duración, lugar y condiciones; alcanzar el límite no es un objetivo.","question_explanation":"CO: 25 ppm VLA-ED y 100 ppm VLA-EC. CO2: 5.000 y 12.500 ppm. SO2: 0,5 y 1 ppm. H2S: 5 y 10 ppm. NO: 25 y 30 ppm. NO2: 3 y 5 ppm. Considerar mezclas, picos, duración, lugar y condiciones; alcanzar el límite no es un objetivo."},{"slide_number":33,"block_number":2,"lesson_ordinal":4,"segment_position":3,"segment_id":"c2e6ab79-8d70-55e3-87b8-e2d9bb4ff644","slide_id":"ddc429cc-6aba-5872-9f51-b0c7d2d9d1e9","note_id":"aa225fe7-76b0-50e2-a2f5-64669d214caf","title":"Instrumentos, calibración y prueba funcional","narration_text":"En interior, una condición segura debe demostrarse antes de exponer a una persona.\n\nPara empezar, se sitúa el criterio: Comprobar identificación, rango, sensores, calibración, batería y respuesta funcional. Configurar el equipo para los gases previsibles y medir a distancia si existe sospecha. Retirar instrumentos fuera de calibración, saturados, incoherentes o que fallen la prueba.\n\nLos gases no se perciben de forma fiable por el olor o por síntomas. La medición debe planificarse, realizarse con instrumentos aptos y conducir a una acción definida. La ITC 04.7.06 fija valores límite ambientales para gases tóxicos en actividades subterráneas. La tabla resume VLA ED y VLA EC en partes por millón. La evaluación debe considerar mezclas, picos, duración, ubicación y condiciones del trabajo. Alcanzar un límite no es un objetivo de operación. Para minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC. La explotación debe aplicar sus alarmas y desconexiones reglamentarias y, si son más restrictivas, las del Documento sobre Seguridad y Salud o la disposición interna de seguridad.\n\nPensemos en una situación de campo. El detector enciende y muestra batería suficiente, pero ha fallado la prueba funcional; usarlo trasladaría una suposición al criterio de entrada.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: instrumento apto y probado.","duration_seconds":158,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-033.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-033.png","explanation":"Objetivo\n\nComprobar identificación, rango, sensores, calibración, batería y respuesta funcional. Configurar el equipo para los gases previsibles y medir a distancia si existe sospecha. Retirar instrumentos fuera de calibración, saturados, incoherentes o que fallen la prueba.\n\nExplicación detallada\n\nLos gases no se perciben de forma fiable por el olor o por síntomas. La medición debe planificarse, realizarse con instrumentos aptos y conducir a una acción definida. La ITC 04.7.06 fija valores límite ambientales para gases tóxicos en actividades subterráneas. La tabla resume VLA ED y VLA EC en partes por millón. La evaluación debe considerar mezclas, picos, duración, ubicación y condiciones del trabajo. Alcanzar un límite no es un objetivo de operación. Para minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC. La explotación debe aplicar sus alarmas y desconexiones reglamentarias y, si son más restrictivas, las del Documento sobre Seguridad y Salud o la disposición interna de seguridad.\n\nLectura guiada de la diapositiva\n\n• Comprobar identificación, rango, sensores, calibración, batería y respuesta funcional. Configurar el equipo para los gases previsibles y medir a distancia si existe sospecha. Retirar instrumentos fuera de calibración, saturados, incoherentes o que fallen la prueba.\n\nAplicación práctica\n\nEl detector enciende y muestra batería suficiente, pero ha fallado la prueba funcional; usarlo trasladaría una suposición al criterio de entrada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nInstrumento apto y probado","key_points":["Comprobar identificación, rango, sensores, calibración, batería y respuesta funcional. Configurar el equipo para los gases previsibles y medir a distancia si existe sospecha. Retirar instrumentos fuera de calibración, saturados, incoherentes o que fallen la prueba.","Instrumento apto y probado"],"stop_criterion":"Instrumento apto y probado","source_pages":"Bloque 2 · diapositiva 33","question":"Respecto a «Instrumentos, calibración y prueba funcional», ¿qué criterio operativo es correcto?","correct_option":"Instrumento apto y probado: Comprobar identificación, rango, sensores, calibración, batería y respuesta funcional. Configurar el equipo para los gases previsibles y medir a distancia si existe sospecha. Retirar instrumentos fuera de calibración, saturados, incoherentes o que fallen la prueba.","question_explanation":"Comprobar identificación, rango, sensores, calibración, batería y respuesta funcional. Configurar el equipo para los gases previsibles y medir a distancia si existe sospecha. Retirar instrumentos fuera de calibración, saturados, incoherentes o que fallen la prueba."},{"slide_number":34,"block_number":2,"lesson_ordinal":4,"segment_position":4,"segment_id":"cd25bc47-00d3-5a61-8c0c-5547a71259d9","slide_id":"c060ccbb-d171-59e2-8dbc-8cd80550a6f8","note_id":"ff871190-2496-50d1-a752-a7986a5b86f3","title":"Estrategia de medición y registro","narration_text":"La prevención empieza describiendo el trabajo real, no suponiendo que hoy será igual que ayer.\n\nLa primera referencia es: Barrer alturas, huecos y zonas respiratorias según geometría y comportamiento del gas. Una lectura puntual no equivale a exposición diaria ni demuestra ausencia permanente. Registrar equipo, lugar, hora, condiciones, lectura, persona y decisión.\n\nCriterio de resolución Se interrumpe la reentrada, se mantiene o corrige la ventilación y se evita exponer personas. La ausencia de olor no invalida la alarma. Se repite la medición con equipo apto y se autoriza solo cuando el criterio del centro se cumple de forma estable. Para minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC. La explotación debe aplicar sus alarmas y desconexiones reglamentarias y, si son más restrictivas, las del Documento sobre Seguridad y Salud o la disposición interna de seguridad. Los gases no se perciben de forma fiable por el olor o por síntomas. La medición debe planificarse, realizarse con instrumentos aptos y conducir a una acción definida.\n\nPensemos en una situación de campo. La medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: medir para decidir.","duration_seconds":159,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-034.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-034.png","explanation":"Objetivo\n\nBarrer alturas, huecos y zonas respiratorias según geometría y comportamiento del gas. Una lectura puntual no equivale a exposición diaria ni demuestra ausencia permanente. Registrar equipo, lugar, hora, condiciones, lectura, persona y decisión.\n\nExplicación detallada\n\nCriterio de resolución Se interrumpe la reentrada, se mantiene o corrige la ventilación y se evita exponer personas. La ausencia de olor no invalida la alarma. Se repite la medición con equipo apto y se autoriza solo cuando el criterio del centro se cumple de forma estable. Para minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC. La explotación debe aplicar sus alarmas y desconexiones reglamentarias y, si son más restrictivas, las del Documento sobre Seguridad y Salud o la disposición interna de seguridad. Los gases no se perciben de forma fiable por el olor o por síntomas. La medición debe planificarse, realizarse con instrumentos aptos y conducir a una acción definida.\n\nLectura guiada de la diapositiva\n\n• Barrer alturas, huecos y zonas respiratorias según geometría y comportamiento del gas. Una lectura puntual no equivale a exposición diaria ni demuestra ausencia permanente. Registrar equipo, lugar, hora, condiciones, lectura, persona y decisión.\n\nAplicación práctica\n\nLa medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nMedir para decidir","key_points":["Barrer alturas, huecos y zonas respiratorias según geometría y comportamiento del gas. Una lectura puntual no equivale a exposición diaria ni demuestra ausencia permanente. Registrar equipo, lugar, hora, condiciones, lectura, persona y decisión.","Medir para decidir"],"stop_criterion":"Medir para decidir","source_pages":"Bloque 2 · diapositiva 34","question":"Respecto a «Estrategia de medición y registro», ¿qué criterio operativo es correcto?","correct_option":"Medir para decidir: Barrer alturas, huecos y zonas respiratorias según geometría y comportamiento del gas. Una lectura puntual no equivale a exposición diaria ni demuestra ausencia permanente. Registrar equipo, lugar, hora, condiciones, lectura, persona y decisión.","question_explanation":"Barrer alturas, huecos y zonas respiratorias según geometría y comportamiento del gas. Una lectura puntual no equivale a exposición diaria ni demuestra ausencia permanente. Registrar equipo, lugar, hora, condiciones, lectura, persona y decisión."},{"slide_number":35,"block_number":2,"lesson_ordinal":4,"segment_position":5,"segment_id":"bebb2a94-2d13-571f-baf9-41593ea81d07","slide_id":"d1cdccfa-b6b9-5cde-b35a-d2b33b10f7ae","note_id":"669189bc-6205-51a1-bb3f-2a9e3742ca31","title":"Metano y atmósferas explosivas","narration_text":"Bajo tierra, terreno, aire, agua, equipos y secuencia pueden cambiar durante el mismo turno.\n\nConviene comprobar lo siguiente: Aplicable a minas de carbón y labores con riesgo de explosión. ITC 05.0.02: 0,80 % en retornos generales; 1,50 % en restantes labores; 1,00 % en retornos de talleres electrificados. Aplicar alarmas, desconexiones y criterios más restrictivos del Documento sobre Seguridad y Salud o la disposición interna de seguridad.\n\nPara minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC. La explotación debe aplicar sus alarmas y desconexiones reglamentarias y, si son más restrictivas, las del Documento sobre Seguridad y Salud o la disposición interna de seguridad.\n\nPensemos en una situación de campo. Una alarma de metano se interpreta fuera del contexto de una labor con riesgo específico; primero hay que confirmar aplicabilidad, punto de medida y procedimiento.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: contexto específico.","duration_seconds":159,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-035.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-035.png","explanation":"Objetivo\n\nAplicable a minas de carbón y labores con riesgo de explosión. ITC 05.0.02: 0,80 % en retornos generales; 1,50 % en restantes labores; 1,00 % en retornos de talleres electrificados. Aplicar alarmas, desconexiones y criterios más restrictivos del DSS o la DIS.\n\nExplicación detallada\n\nPara minas subterráneas de carbón y labores con riesgo de explosión, la ITC 05.0.02 establece límites específicos de metano: 0,80 por ciento en retornos generales, 1,50 por ciento en las restantes labores y 1,00 por ciento en retornos de talleres electrificados. La autoridad minera puede admitir determinados límites superiores cuando existe control automático permanente y se cumplen las condiciones de la ITC. La explotación debe aplicar sus alarmas y desconexiones reglamentarias y, si son más restrictivas, las del Documento sobre Seguridad y Salud o la disposición interna de seguridad.\n\nLectura guiada de la diapositiva\n\n• Aplicable a minas de carbón y labores con riesgo de explosión. ITC 05.0.02: 0,80 % en retornos generales; 1,50 % en restantes labores; 1,00 % en retornos de talleres electrificados. Aplicar alarmas, desconexiones y criterios más restrictivos del DSS o la DIS.\n\nAplicación práctica\n\nUna alarma de metano se interpreta fuera del contexto de una labor con riesgo específico; primero hay que confirmar aplicabilidad, punto de medida y procedimiento.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nContexto específico","key_points":["Aplicable a minas de carbón y labores con riesgo de explosión. ITC 05.0.02: 0,80 % en retornos generales; 1,50 % en restantes labores; 1,00 % en retornos de talleres electrificados. Aplicar alarmas, desconexiones y criterios más restrictivos del DSS o la DIS.","Contexto específico"],"stop_criterion":"Contexto específico","source_pages":"Bloque 2 · diapositiva 35","question":"Respecto a «Metano y atmósferas explosivas», ¿qué criterio operativo es correcto?","correct_option":"Contexto específico: Aplicable a minas de carbón y labores con riesgo de explosión. ITC 05.0.02: 0,80 % en retornos generales; 1,50 % en restantes labores; 1,00 % en retornos de talleres electrificados. Aplicar alarmas, desconexiones y criterios más restrictivos del DSS o la DIS.","question_explanation":"Aplicable a minas de carbón y labores con riesgo de explosión. ITC 05.0.02: 0,80 % en retornos generales; 1,50 % en restantes labores; 1,00 % en retornos de talleres electrificados. Aplicar alarmas, desconexiones y criterios más restrictivos del DSS o la DIS."},{"slide_number":36,"block_number":2,"lesson_ordinal":4,"segment_position":6,"segment_id":"5c15ff19-02d9-5171-b5cc-3c1a890380e7","slide_id":"bd56c9d0-1fc0-5cd0-834d-81295c1219cb","note_id":"04073779-bea8-5ca2-b9d3-5a2720c947df","title":"Polvo respirable y sílice cristalina","narration_text":"Supervisar consiste en comparar lo que ocurre en campo con un criterio definido de antemano.\n\nEl punto de partida es: Perforación, voladura, carga, trituración, transferencia y tráfico generan fracción respirable. valor límite ambiental de exposición diaria: 3 miligramos por metro cúbico de polvo respirable y 0,05 miligramos por metro cúbico de sílice cristalina respirable. Controlar por diseño, captación, supresión, ventilación, organización y finalmente equipo de protección individual.\n\nPerforación, voladura, carga, trituración, transferencia, circulación y limpieza en seco generan fracción respirable. La sílice cristalina respirable puede causar silicosis y cáncer de pulmón. La ITC 02.0.02 fija simultáneamente 3 mg por metro cúbico para polvo respirable y 0,05 mg por metro cúbico para sílice cristalina respirable como VLA ED. La evaluación se revisa cuando cambian las condiciones y, en todo caso, al menos cada tres años. La exposición se controla en la fuente y en la ruta de dispersión. El equipo de protección individual respiratorio completa el sistema, pero no convierte una atmósfera sin controlar en un puesto aceptable.\n\nPensemos en una situación de campo. El instrumento ofrece una lectura, pero no representa el punto de mayor exposición. Medir sin elegir bien lugar y momento puede producir una falsa sensación de control.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: control en la fuente.","duration_seconds":170,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-036.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-036.png","explanation":"Objetivo\n\nPerforación, voladura, carga, trituración, transferencia y tráfico generan fracción respirable. VLA-ED: 3 mg/m3 de polvo respirable y 0,05 mg/m3 de sílice cristalina respirable. Controlar por diseño, captación, supresión, ventilación, organización y finalmente EPI.\n\nExplicación detallada\n\nPerforación, voladura, carga, trituración, transferencia, circulación y limpieza en seco generan fracción respirable. La sílice cristalina respirable puede causar silicosis y cáncer de pulmón. La ITC 02.0.02 fija simultáneamente 3 mg por metro cúbico para polvo respirable y 0,05 mg por metro cúbico para sílice cristalina respirable como VLA ED. La evaluación se revisa cuando cambian las condiciones y, en todo caso, al menos cada tres años. La exposición se controla en la fuente y en la ruta de dispersión. El equipo de protección individual respiratorio completa el sistema, pero no convierte una atmósfera sin controlar en un puesto aceptable.\n\nLectura guiada de la diapositiva\n\n• Perforación, voladura, carga, trituración, transferencia y tráfico generan fracción respirable. VLA-ED: 3 mg/m3 de polvo respirable y 0,05 mg/m3 de sílice cristalina respirable. Controlar por diseño, captación, supresión, ventilación, organización y finalmente EPI.\n\nAplicación práctica\n\nEl instrumento ofrece una lectura, pero no representa el punto de mayor exposición. Medir sin elegir bien lugar y momento puede producir una falsa sensación de control.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nControl en la fuente","key_points":["Perforación, voladura, carga, trituración, transferencia y tráfico generan fracción respirable. VLA-ED: 3 mg/m3 de polvo respirable y 0,05 mg/m3 de sílice cristalina respirable. Controlar por diseño, captación, supresión, ventilación, organización y finalmente EPI.","Control en la fuente"],"stop_criterion":"Control en la fuente","source_pages":"Bloque 2 · diapositiva 36","question":"Respecto a «Polvo respirable y sílice cristalina», ¿qué criterio operativo es correcto?","correct_option":"Control en la fuente: Perforación, voladura, carga, trituración, transferencia y tráfico generan fracción respirable. VLA-ED: 3 mg/m3 de polvo respirable y 0,05 mg/m3 de sílice cristalina respirable. Controlar por diseño, captación, supresión, ventilación, organización y finalmente EPI.","question_explanation":"Perforación, voladura, carga, trituración, transferencia y tráfico generan fracción respirable. VLA-ED: 3 mg/m3 de polvo respirable y 0,05 mg/m3 de sílice cristalina respirable. Controlar por diseño, captación, supresión, ventilación, organización y finalmente EPI."},{"slide_number":37,"block_number":2,"lesson_ordinal":4,"segment_position":7,"segment_id":"0543c820-e18f-5451-b7cb-2d75b8f80003","slide_id":"5eff2010-93df-55f4-8baf-ed1e5fc49c30","note_id":"0d00013c-6f60-556a-b331-c55b9afd68ac","title":"Emisiones diésel, ruido, vibraciones, calor e iluminación","narration_text":"Una tarea habitual también necesita límites claros y una comprobación proporcionada al riesgo.\n\nPara empezar, se sitúa el criterio: Diésel: bajas emisiones, mantenimiento, ventilación y reducción de ralentí. Ruido y vibración: selección, encapsulado, mantenimiento, distancia y tiempo. Calor e iluminación: ventilación, hidratación, aclimatación, pausas y luz suficiente sin deslumbrar.\n\nLa exposición se controla en la fuente y en la ruta de dispersión. El equipo de protección individual respiratorio completa el sistema, pero no convierte una atmósfera sin controlar en un puesto aceptable.\n\nPensemos en una situación de campo. Imagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: riesgos combinados.","duration_seconds":147,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-037.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-037.png","explanation":"Objetivo\n\nDiésel: bajas emisiones, mantenimiento, ventilación y reducción de ralentí. Ruido y vibración: selección, encapsulado, mantenimiento, distancia y tiempo. Calor e iluminación: ventilación, hidratación, aclimatación, pausas y luz suficiente sin deslumbrar.\n\nExplicación detallada\n\nLa exposición se controla en la fuente y en la ruta de dispersión. El equipo de protección individual respiratorio completa el sistema, pero no convierte una atmósfera sin controlar en un puesto aceptable.\n\nLectura guiada de la diapositiva\n\n• Diésel: bajas emisiones, mantenimiento, ventilación y reducción de ralentí. Ruido y vibración: selección, encapsulado, mantenimiento, distancia y tiempo. Calor e iluminación: ventilación, hidratación, aclimatación, pausas y luz suficiente sin deslumbrar.\n\nAplicación práctica\n\nImagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nRiesgos combinados","key_points":["Diésel: bajas emisiones, mantenimiento, ventilación y reducción de ralentí. Ruido y vibración: selección, encapsulado, mantenimiento, distancia y tiempo. Calor e iluminación: ventilación, hidratación, aclimatación, pausas y luz suficiente sin deslumbrar.","Riesgos combinados"],"stop_criterion":"Riesgos combinados","source_pages":"Bloque 2 · diapositiva 37","question":"Respecto a «Emisiones diésel, ruido, vibraciones, calor e iluminación», ¿qué criterio operativo es correcto?","correct_option":"Riesgos combinados: Diésel: bajas emisiones, mantenimiento, ventilación y reducción de ralentí. Ruido y vibración: selección, encapsulado, mantenimiento, distancia y tiempo. Calor e iluminación: ventilación, hidratación, aclimatación, pausas y luz suficiente sin deslumbrar.","question_explanation":"Diésel: bajas emisiones, mantenimiento, ventilación y reducción de ralentí. Ruido y vibración: selección, encapsulado, mantenimiento, distancia y tiempo. Calor e iluminación: ventilación, hidratación, aclimatación, pausas y luz suficiente sin deslumbrar."},{"slide_number":38,"block_number":2,"lesson_ordinal":4,"segment_position":8,"segment_id":"2a62e8cf-5006-539f-9e7a-b1db9910627f","slide_id":"933efb0d-e515-5383-be58-392db80bbe5b","note_id":"493df93c-a31f-53cc-b9a8-70da8ddcb640","title":"Incendio, humo y trabajos en caliente","narration_text":"La decisión técnica debe precisar qué se acepta, qué obliga a parar y qué permite reanudar.\n\nLa primera referencia es: Cintas, neumáticos, aceites, combustible, madera, cables y baterías aportan carga de fuego. La ventilación transporta humo y calor; las decisiones siguen el plan de emergencia. Trabajo en caliente: permiso, atmósfera controlada, combustibles retirados, extinción, vigilancia e inspección posterior.\n\nEl incendio necesita combustible, comburente y una fuente de ignición. En una mina, cintas, neumáticos, aceites, combustible, madera, cables y baterías pueden sostenerlo. El flujo de ventilación transporta humo y calor, y un cambio de ventilación puede alterar la zona afectada. Las decisiones sobre ventiladores y puertas durante un incendio pertenecen al plan de emergencia y no deben improvisarse. Las minas con posibilidad de grisú o polvo combustible requieren clasificación, equipos y procedimientos específicos. La prevención combina ventilación, control de fuentes de ignición, equipos aptos, limpieza, inertización o barreras cuando proceda, medición continua o periódica y desconexión. Ninguna orden de producción justifica mantener energía o personas cuando se supera un umbral de seguridad.\n\nPensemos en una situación de campo. Un trabajo en caliente termina sin incidente visible, pero una partícula permanece en un material combustible y el humo podría propagarse después por el circuito.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: humo y evacuación.","duration_seconds":166,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-038.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-038.png","explanation":"Objetivo\n\nCintas, neumáticos, aceites, combustible, madera, cables y baterías aportan carga de fuego. La ventilación transporta humo y calor; las decisiones siguen el plan de emergencia. Trabajo en caliente: permiso, atmósfera controlada, combustibles retirados, extinción, vigilancia e inspección posterior.\n\nExplicación detallada\n\nEl incendio necesita combustible, comburente y una fuente de ignición. En una mina, cintas, neumáticos, aceites, combustible, madera, cables y baterías pueden sostenerlo. El flujo de ventilación transporta humo y calor, y un cambio de ventilación puede alterar la zona afectada. Las decisiones sobre ventiladores y puertas durante un incendio pertenecen al plan de emergencia y no deben improvisarse. Las minas con posibilidad de grisú o polvo combustible requieren clasificación, equipos y procedimientos específicos. La prevención combina ventilación, control de fuentes de ignición, equipos aptos, limpieza, inertización o barreras cuando proceda, medición continua o periódica y desconexión. Ninguna orden de producción justifica mantener energía o personas cuando se supera un umbral de seguridad.\n\nLectura guiada de la diapositiva\n\n• Cintas, neumáticos, aceites, combustible, madera, cables y baterías aportan carga de fuego. La ventilación transporta humo y calor; las decisiones siguen el plan de emergencia. Trabajo en caliente: permiso, atmósfera controlada, combustibles retirados, extinción, vigilancia e inspección posterior.\n\nAplicación práctica\n\nUn trabajo en caliente termina sin incidente visible, pero una partícula permanece en un material combustible y el humo podría propagarse después por el circuito.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nHumo y evacuación","key_points":["Cintas, neumáticos, aceites, combustible, madera, cables y baterías aportan carga de fuego. La ventilación transporta humo y calor; las decisiones siguen el plan de emergencia. Trabajo en caliente: permiso, atmósfera controlada, combustibles retirados, extinción, vigilancia e inspección posterior.","Humo y evacuación"],"stop_criterion":"Humo y evacuación","source_pages":"Bloque 2 · diapositiva 38","question":"Respecto a «Incendio, humo y trabajos en caliente», ¿qué criterio operativo es correcto?","correct_option":"Humo y evacuación: Cintas, neumáticos, aceites, combustible, madera, cables y baterías aportan carga de fuego. La ventilación transporta humo y calor; las decisiones siguen el plan de emergencia. Trabajo en caliente: permiso, atmósfera controlada, combustibles retirados, extinción, vigilancia e inspección posterior.","question_explanation":"Cintas, neumáticos, aceites, combustible, madera, cables y baterías aportan carga de fuego. La ventilación transporta humo y calor; las decisiones siguen el plan de emergencia. Trabajo en caliente: permiso, atmósfera controlada, combustibles retirados, extinción, vigilancia e inspección posterior."},{"slide_number":39,"block_number":2,"lesson_ordinal":4,"segment_position":9,"segment_id":"0ba5034b-20a1-5c42-85fc-7462220fedb3","slide_id":"568851a9-bdcb-5909-8b05-08c67a84f702","note_id":"2ecebdde-eaab-5ede-8793-94ed7a7115f6","title":"Agua, inundación, labores antiguas, accesos y transporte","narration_text":"Una barrera preventiva solo es útil cuando puede observarse, medirse o probarse.\n\nConviene comprobar lo siguiente: El agua erosiona, oculta huecos, vence barreras, afecta la electricidad y corta rutas. Ante sospecha: sondeos, solapes, control de presión, bombeo redundante, alarmas y ruta de descarga. Mantener salidas, control de presencia y un plan de tráfico con segregación.\n\nCuando exista sospecha de agua o huecos, el proyecto y la disposición interna de seguridad deben definir longitud, orientación, solape, número de barrenos, equipos de control y reacción ante presión o flujo. El sondeo es una barrera solo si cubre el volumen de avance y se interpreta. El bombeo debe considerar redundancia, alimentación, alarmas, capacidad frente al escenario y ruta del agua descargada. Criterio de resolución El cambio puede indicar apertura progresiva o conexión con una labor. Se retira la exposición, se controla presión y caudal, se notifica y se reevalúa el plan. Se registran hora ubicación orientación profundidad aspecto del agua evolución y medidas. Toda explotación subterránea debe disponer de al menos dos salidas diferentes, sólidamente establecidas, señalizadas y accesibles, salvo las condiciones reglamentarias específicas durante determinadas fases. Debe conocerse quién está en interior y, cuando resulte posible, su zona. El sistema de presencia debe seguir siendo útil durante una emergencia y conciliar control operativo, visitantes, contratas y cambios de turno.\n\nPensemos en una situación de campo. Producción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: agua y movilidad.","duration_seconds":161,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-039.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-039.png","explanation":"Objetivo\n\nEl agua erosiona, oculta huecos, vence barreras, afecta la electricidad y corta rutas. Ante sospecha: sondeos, solapes, control de presión, bombeo redundante, alarmas y ruta de descarga. Mantener salidas, control de presencia y un plan de tráfico con segregación.\n\nExplicación detallada\n\nCuando exista sospecha de agua o huecos, el proyecto y la disposición interna de seguridad deben definir longitud, orientación, solape, número de barrenos, equipos de control y reacción ante presión o flujo. El sondeo es una barrera solo si cubre el volumen de avance y se interpreta. El bombeo debe considerar redundancia, alimentación, alarmas, capacidad frente al escenario y ruta del agua descargada. Criterio de resolución El cambio puede indicar apertura progresiva o conexión con una labor. Se retira la exposición, se controla presión y caudal, se notifica y se reevalúa el plan. Se registran hora ubicación orientación profundidad aspecto del agua evolución y medidas. Toda explotación subterránea debe disponer de al menos dos salidas diferentes, sólidamente establecidas, señalizadas y accesibles, salvo las condiciones reglamentarias específicas durante determinadas fases. Debe conocerse quién está en interior y, cuando resulte posible, su zona. El sistema de presencia debe seguir siendo útil durante una emergencia y conciliar control operativo, visitantes, contratas y cambios de turno.\n\nLectura guiada de la diapositiva\n\n• El agua erosiona, oculta huecos, vence barreras, afecta la electricidad y corta rutas. Ante sospecha: sondeos, solapes, control de presión, bombeo redundante, alarmas y ruta de descarga. Mantener salidas, control de presencia y un plan de tráfico con segregación.\n\nAplicación práctica\n\nProducción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nAgua y movilidad","key_points":["El agua erosiona, oculta huecos, vence barreras, afecta la electricidad y corta rutas. Ante sospecha: sondeos, solapes, control de presión, bombeo redundante, alarmas y ruta de descarga. Mantener salidas, control de presencia y un plan de tráfico con segregación.","Agua y movilidad"],"stop_criterion":"Agua y movilidad","source_pages":"Bloque 2 · diapositiva 39","question":"Respecto a «Agua, inundación, labores antiguas, accesos y transporte», ¿qué criterio operativo es correcto?","correct_option":"Agua y movilidad: El agua erosiona, oculta huecos, vence barreras, afecta la electricidad y corta rutas. Ante sospecha: sondeos, solapes, control de presión, bombeo redundante, alarmas y ruta de descarga. Mantener salidas, control de presencia y un plan de tráfico con segregación.","question_explanation":"El agua erosiona, oculta huecos, vence barreras, afecta la electricidad y corta rutas. Ante sospecha: sondeos, solapes, control de presión, bombeo redundante, alarmas y ruta de descarga. Mantener salidas, control de presencia y un plan de tráfico con segregación."},{"slide_number":40,"block_number":2,"lesson_ordinal":4,"segment_position":10,"segment_id":"853750c0-108f-5513-9561-224a8b2d8121","slide_id":"44426e8e-1e61-5089-b478-a745b931c0eb","note_id":"21a8aaaa-1691-5f1c-8c1d-7dd8487d32b1","title":"Perforación, voladura, reentrada, evacuación y emergencias","narration_text":"Antes de autorizar hay que entender qué puede cambiar y hasta dónde llegarían sus efectos.\n\nEl punto de partida es: Explosivos solo por personal autorizado y con exclusiones e interferencias controladas. Tras el disparo: espera, ventilación, medición, terreno, sostenimiento, servicios y fallidos. Evacuar, contar personas y no improvisar rescates en atmósfera desconocida o terreno inestable.\n\nEl Real Decreto 1389/1997 exige una organización de salvamento adecuada para las labores subterráneas, con brigadistas entrenados y material de intervención suficiente. Una persona no entra a rescatar por iniciativa propia en una atmósfera desconocida o bajo terreno inestable; el segundo accidentado agrava la emergencia. Un barreno fallido no se perfora ni manipula como si fuera roca ordinaria. Se señaliza, protege y comunica. La localización, el tiempo de espera, la investigación y la eliminación siguen la normativa de explosivos y la disposición interna de seguridad de la explotación. El autorrescatador permite atravesar una atmósfera peligrosa durante un tiempo limitado; no sustituye una ruta viable ni un equipo respiratorio de rescate. Cada usuario debe conocer ubicación, inspección, activación, limitaciones y conducta durante la evacuación. Los refugios, cuando existen, requieren capacidad, aire, comunicaciones, agua, control de dióxido de carbono, mantenimiento y reglas claras de uso.\n\nPensemos en una situación de campo. Después de una voladura, la visibilidad mejora antes de que se hayan comprobado gases, terreno, sostenimiento y posibles barrenos fallidos.\n\nEn atmósferas subterráneas no basta una impresión visual. Hay que saber dónde medir, con qué instrumento, en qué estado productivo y con qué criterio se tomará la decisión. La lectura se interpreta junto con ventilación, geometría, duración y contaminantes previsibles.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: reentrada autorizada.","duration_seconds":147,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-040.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-040.png","explanation":"Objetivo\n\nExplosivos solo por personal autorizado y con exclusiones e interferencias controladas. Tras el disparo: espera, ventilación, medición, terreno, sostenimiento, servicios y fallidos. Evacuar, contar personas y no improvisar rescates en atmósfera desconocida o terreno inestable.\n\nExplicación detallada\n\nEl Real Decreto 1389/1997 exige una organización de salvamento adecuada para las labores subterráneas, con brigadistas entrenados y material de intervención suficiente. Una persona no entra a rescatar por iniciativa propia en una atmósfera desconocida o bajo terreno inestable; el segundo accidentado agrava la emergencia. Un barreno fallido no se perfora ni manipula como si fuera roca ordinaria. Se señaliza, protege y comunica. La localización, el tiempo de espera, la investigación y la eliminación siguen la normativa de explosivos y la disposición interna de seguridad de la explotación. El autorrescatador permite atravesar una atmósfera peligrosa durante un tiempo limitado; no sustituye una ruta viable ni un equipo respiratorio de rescate. Cada usuario debe conocer ubicación, inspección, activación, limitaciones y conducta durante la evacuación. Los refugios, cuando existen, requieren capacidad, aire, comunicaciones, agua, control de dióxido de carbono, mantenimiento y reglas claras de uso.\n\nLectura guiada de la diapositiva\n\n• Explosivos solo por personal autorizado y con exclusiones e interferencias controladas. Tras el disparo: espera, ventilación, medición, terreno, sostenimiento, servicios y fallidos. Evacuar, contar personas y no improvisar rescates en atmósfera desconocida o terreno inestable.\n\nAplicación práctica\n\nDespués de una voladura, la visibilidad mejora antes de que se hayan comprobado gases, terreno, sostenimiento y posibles barrenos fallidos.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nReentrada autorizada","key_points":["Explosivos solo por personal autorizado y con exclusiones e interferencias controladas. Tras el disparo: espera, ventilación, medición, terreno, sostenimiento, servicios y fallidos. Evacuar, contar personas y no improvisar rescates en atmósfera desconocida o terreno inestable.","Reentrada autorizada"],"stop_criterion":"Reentrada autorizada","source_pages":"Bloque 2 · diapositiva 40","question":"Respecto a «Perforación, voladura, reentrada, evacuación y emergencias», ¿qué criterio operativo es correcto?","correct_option":"Reentrada autorizada: Explosivos solo por personal autorizado y con exclusiones e interferencias controladas. Tras el disparo: espera, ventilación, medición, terreno, sostenimiento, servicios y fallidos. Evacuar, contar personas y no improvisar rescates en atmósfera desconocida o terreno inestable.","question_explanation":"Explosivos solo por personal autorizado y con exclusiones e interferencias controladas. Tras el disparo: espera, ventilación, medición, terreno, sostenimiento, servicios y fallidos. Evacuar, contar personas y no improvisar rescates en atmósfera desconocida o terreno inestable."},{"slide_number":41,"block_number":3,"lesson_ordinal":5,"segment_position":1,"segment_id":"02b51bad-f64f-5bb7-9bdb-9d1d687a9247","slide_id":"d79d2c12-3aaa-5642-801f-fd731e02300f","note_id":"d9dfe1cb-2ce2-5721-9fb8-9415866aba09","title":"Equipos móviles y riesgos críticos","narration_text":"La primera pregunta no es cómo producir más rápido, sino qué condición debe conservarse segura.\n\nPara empezar, se sitúa el criterio: Comprobar frenos, dirección, neumáticos, luces, alarmas, cámara, extinción, cinturón y fugas. Controlar puntos ciegos, pendientes, radios de giro, prioridad y segregación. Un fallo crítico retira el equipo de servicio.\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nPensemos en una situación de campo. Un equipo puede desplazarse aunque el freno de servicio no supere la prueba; que la máquina se mueva no significa que conserve sus funciones de seguridad.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: probar funciones críticas.","duration_seconds":143,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-041.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-041.png","explanation":"Objetivo\n\nComprobar frenos, dirección, neumáticos, luces, alarmas, cámara, extinción, cinturón y fugas. Controlar puntos ciegos, pendientes, radios de giro, prioridad y segregación. Un fallo crítico retira el equipo de servicio.\n\nExplicación detallada\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nLectura guiada de la diapositiva\n\n• Comprobar frenos, dirección, neumáticos, luces, alarmas, cámara, extinción, cinturón y fugas. Controlar puntos ciegos, pendientes, radios de giro, prioridad y segregación. Un fallo crítico retira el equipo de servicio.\n\nAplicación práctica\n\nUn equipo puede desplazarse aunque el freno de servicio no supere la prueba; que la máquina se mueva no significa que conserve sus funciones de seguridad.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nProbar funciones críticas","key_points":["Comprobar frenos, dirección, neumáticos, luces, alarmas, cámara, extinción, cinturón y fugas. Controlar puntos ciegos, pendientes, radios de giro, prioridad y segregación. Un fallo crítico retira el equipo de servicio.","Probar funciones críticas"],"stop_criterion":"Probar funciones críticas","source_pages":"Bloque 3 · diapositiva 41","question":"Respecto a «Equipos móviles y riesgos críticos», ¿qué criterio operativo es correcto?","correct_option":"Probar funciones críticas: Comprobar frenos, dirección, neumáticos, luces, alarmas, cámara, extinción, cinturón y fugas. Controlar puntos ciegos, pendientes, radios de giro, prioridad y segregación. Un fallo crítico retira el equipo de servicio.","question_explanation":"Comprobar frenos, dirección, neumáticos, luces, alarmas, cámara, extinción, cinturón y fugas. Controlar puntos ciegos, pendientes, radios de giro, prioridad y segregación. Un fallo crítico retira el equipo de servicio."},{"slide_number":42,"block_number":3,"lesson_ordinal":5,"segment_position":2,"segment_id":"5bdede83-2bd9-5076-a521-13fdb58354dd","slide_id":"6932e36c-d5f9-5abb-b5df-6867beff8158","note_id":"18d7664b-a26c-5732-a3bc-ed32e23951f2","title":"Perforadoras y equipos de avance","narration_text":"En una labor conectada con otras, una decisión local nunca se analiza de forma aislada.\n\nLa primera referencia es: Comprobar estabilidad, apoyos, mangueras, barras, protecciones y captación de polvo. Mantener al operador fuera de trayectorias de proyección, atrapamiento y latigazo. No acceder a la zona peligrosa mientras exista energía disponible.\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Situación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera.\n\nPensemos en una situación de campo. La observación parece tranquilizadora, aunque falta una comprobación instrumental o funcional. Si la decisión depende de ese dato, la actividad permanece detenida hasta obtenerlo.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: estabilidad y exclusión.","duration_seconds":160,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-042.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-042.png","explanation":"Objetivo\n\nComprobar estabilidad, apoyos, mangueras, barras, protecciones y captación de polvo. Mantener al operador fuera de trayectorias de proyección, atrapamiento y latigazo. No acceder a la zona peligrosa mientras exista energía disponible.\n\nExplicación detallada\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Situación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera.\n\nLectura guiada de la diapositiva\n\n• Comprobar estabilidad, apoyos, mangueras, barras, protecciones y captación de polvo. Mantener al operador fuera de trayectorias de proyección, atrapamiento y latigazo. No acceder a la zona peligrosa mientras exista energía disponible.\n\nAplicación práctica\n\nLa observación parece tranquilizadora, aunque falta una comprobación instrumental o funcional. Si la decisión depende de ese dato, la actividad permanece detenida hasta obtenerlo.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nEstabilidad y exclusión","key_points":["Comprobar estabilidad, apoyos, mangueras, barras, protecciones y captación de polvo. Mantener al operador fuera de trayectorias de proyección, atrapamiento y latigazo. No acceder a la zona peligrosa mientras exista energía disponible.","Estabilidad y exclusión"],"stop_criterion":"Estabilidad y exclusión","source_pages":"Bloque 3 · diapositiva 42","question":"Respecto a «Perforadoras y equipos de avance», ¿qué criterio operativo es correcto?","correct_option":"Estabilidad y exclusión: Comprobar estabilidad, apoyos, mangueras, barras, protecciones y captación de polvo. Mantener al operador fuera de trayectorias de proyección, atrapamiento y latigazo. No acceder a la zona peligrosa mientras exista energía disponible.","question_explanation":"Comprobar estabilidad, apoyos, mangueras, barras, protecciones y captación de polvo. Mantener al operador fuera de trayectorias de proyección, atrapamiento y latigazo. No acceder a la zona peligrosa mientras exista energía disponible."},{"slide_number":43,"block_number":3,"lesson_ordinal":5,"segment_position":3,"segment_id":"104c26c9-ce2e-541e-b479-ac7dcdc4cbc7","slide_id":"9ea2fa23-9c74-5fe6-baf2-4f4de579c4e5","note_id":"8672ce06-facc-514e-8132-08314eced078","title":"Cintas, trituradores y puntos de atrapamiento","narration_text":"El control empieza por reconocer la señal temprana, antes de que el peligro alcance a alguien.\n\nConviene comprobar lo siguiente: Revisar resguardos, enclavamientos, paradas, accesos, derrames, atascos y caída de material. Un atasco no se libera mientras exista energía. Rozamiento, humo, protección anulada o parada inaccesible exigen detener y consignar.\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Situación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera.\n\nPensemos en una situación de campo. Una cinta se atasca y alguien propone pulsar la parada de emergencia para retirar material; todavía existen tensión, gravedad y posible rearme remoto.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: consignar antes de intervenir.","duration_seconds":156,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-043.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-043.png","explanation":"Objetivo\n\nRevisar resguardos, enclavamientos, paradas, accesos, derrames, atascos y caída de material. Un atasco no se libera mientras exista energía. Rozamiento, humo, protección anulada o parada inaccesible exigen detener y consignar.\n\nExplicación detallada\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Situación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera.\n\nLectura guiada de la diapositiva\n\n• Revisar resguardos, enclavamientos, paradas, accesos, derrames, atascos y caída de material. Un atasco no se libera mientras exista energía. Rozamiento, humo, protección anulada o parada inaccesible exigen detener y consignar.\n\nAplicación práctica\n\nUna cinta se atasca y alguien propone pulsar la parada de emergencia para retirar material; todavía existen tensión, gravedad y posible rearme remoto.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nConsignar antes de intervenir","key_points":["Revisar resguardos, enclavamientos, paradas, accesos, derrames, atascos y caída de material. Un atasco no se libera mientras exista energía. Rozamiento, humo, protección anulada o parada inaccesible exigen detener y consignar.","Consignar antes de intervenir"],"stop_criterion":"Consignar antes de intervenir","source_pages":"Bloque 3 · diapositiva 43","question":"Respecto a «Cintas, trituradores y puntos de atrapamiento», ¿qué criterio operativo es correcto?","correct_option":"Consignar antes de intervenir: Revisar resguardos, enclavamientos, paradas, accesos, derrames, atascos y caída de material. Un atasco no se libera mientras exista energía. Rozamiento, humo, protección anulada o parada inaccesible exigen detener y consignar.","question_explanation":"Revisar resguardos, enclavamientos, paradas, accesos, derrames, atascos y caída de material. Un atasco no se libera mientras exista energía. Rozamiento, humo, protección anulada o parada inaccesible exigen detener y consignar."},{"slide_number":44,"block_number":3,"lesson_ordinal":5,"segment_position":4,"segment_id":"a1e18d63-0f7a-5549-98dc-db66b9ab3285","slide_id":"0639071d-2bbb-5758-a833-398f0e24cfda","note_id":"dbf17adc-9119-5140-b7c6-6978108e6c77","title":"Bombas, ventiladores y equipos de izado","narration_text":"Una comprobación útil termina en una decisión concreta: continuar, corregir o detener.\n\nEl punto de partida es: Bomba: base, acoplamientos, tuberías, válvulas, presión, cebado y alimentación. Ventilador: anclaje, resguardo, sentido, vibración, conducto, protección y alarma. Izado: capacidad, identificación, accesorios, pestillos, apoyos, recorrido y exclusión.\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Criterio de resolución Persisten articulación movimiento por pendiente presión residual y posible arranque. Se inmoviliza articula calza aísla bloquea descarga verifica y controla la llave conforme al procedimiento.\n\nPensemos en una situación de campo. Una corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: equipo y entorno.","duration_seconds":154,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-044.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-044.png","explanation":"Objetivo\n\nBomba: base, acoplamientos, tuberías, válvulas, presión, cebado y alimentación. Ventilador: anclaje, resguardo, sentido, vibración, conducto, protección y alarma. Izado: capacidad, identificación, accesorios, pestillos, apoyos, recorrido y exclusión.\n\nExplicación detallada\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Criterio de resolución Persisten articulación movimiento por pendiente presión residual y posible arranque. Se inmoviliza articula calza aísla bloquea descarga verifica y controla la llave conforme al procedimiento.\n\nLectura guiada de la diapositiva\n\n• Bomba: base, acoplamientos, tuberías, válvulas, presión, cebado y alimentación. Ventilador: anclaje, resguardo, sentido, vibración, conducto, protección y alarma. Izado: capacidad, identificación, accesorios, pestillos, apoyos, recorrido y exclusión.\n\nAplicación práctica\n\nUna corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nEquipo y entorno","key_points":["Bomba: base, acoplamientos, tuberías, válvulas, presión, cebado y alimentación. Ventilador: anclaje, resguardo, sentido, vibración, conducto, protección y alarma. Izado: capacidad, identificación, accesorios, pestillos, apoyos, recorrido y exclusión.","Equipo y entorno"],"stop_criterion":"Equipo y entorno","source_pages":"Bloque 3 · diapositiva 44","question":"Respecto a «Bombas, ventiladores y equipos de izado», ¿qué criterio operativo es correcto?","correct_option":"Equipo y entorno: Bomba: base, acoplamientos, tuberías, válvulas, presión, cebado y alimentación. Ventilador: anclaje, resguardo, sentido, vibración, conducto, protección y alarma. Izado: capacidad, identificación, accesorios, pestillos, apoyos, recorrido y exclusión.","question_explanation":"Bomba: base, acoplamientos, tuberías, válvulas, presión, cebado y alimentación. Ventilador: anclaje, resguardo, sentido, vibración, conducto, protección y alarma. Izado: capacidad, identificación, accesorios, pestillos, apoyos, recorrido y exclusión."},{"slide_number":45,"block_number":3,"lesson_ordinal":5,"segment_position":5,"segment_id":"8e3308bc-0844-5968-8462-e53430bb976b","slide_id":"a310ffbf-a2d5-5376-bd64-573b8f34297b","note_id":"4820dba2-e07a-545f-9165-7902206d63be","title":"Inspección previa de los equipos","narration_text":"La ausencia de un incidente no demuestra que las barreras sigan disponibles.\n\nPara empezar, se sitúa el criterio: Identificar el equipo, revisar estado físico, protecciones, fugas y documentación. Probar funciones críticas desde una posición segura. Comunicar defectos, inmovilizar y etiquetar cuando afecten a la seguridad.\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Situación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera.\n\nPensemos en una situación de campo. El turno saliente conoce una limitación temporal, pero no la registra. El turno entrante recibe la zona como disponible y actúa con una información incompleta.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: mirar, probar y decidir.","duration_seconds":158,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-045.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-045.png","explanation":"Objetivo\n\nIdentificar el equipo, revisar estado físico, protecciones, fugas y documentación. Probar funciones críticas desde una posición segura. Comunicar defectos, inmovilizar y etiquetar cuando afecten a la seguridad.\n\nExplicación detallada\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Situación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera.\n\nLectura guiada de la diapositiva\n\n• Identificar el equipo, revisar estado físico, protecciones, fugas y documentación. Probar funciones críticas desde una posición segura. Comunicar defectos, inmovilizar y etiquetar cuando afecten a la seguridad.\n\nAplicación práctica\n\nEl turno saliente conoce una limitación temporal, pero no la registra. El turno entrante recibe la zona como disponible y actúa con una información incompleta.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nMirar, probar y decidir","key_points":["Identificar el equipo, revisar estado físico, protecciones, fugas y documentación. Probar funciones críticas desde una posición segura. Comunicar defectos, inmovilizar y etiquetar cuando afecten a la seguridad.","Mirar, probar y decidir"],"stop_criterion":"Mirar, probar y decidir","source_pages":"Bloque 3 · diapositiva 45","question":"Respecto a «Inspección previa de los equipos», ¿qué criterio operativo es correcto?","correct_option":"Mirar, probar y decidir: Identificar el equipo, revisar estado físico, protecciones, fugas y documentación. Probar funciones críticas desde una posición segura. Comunicar defectos, inmovilizar y etiquetar cuando afecten a la seguridad.","question_explanation":"Identificar el equipo, revisar estado físico, protecciones, fugas y documentación. Probar funciones críticas desde una posición segura. Comunicar defectos, inmovilizar y etiquetar cuando afecten a la seguridad."},{"slide_number":46,"block_number":3,"lesson_ordinal":5,"segment_position":6,"segment_id":"4caaa6df-ec83-5ac0-81b9-313a46916af8","slide_id":"f0bf0d20-7ca6-54b0-9a45-0223b787287b","note_id":"29d779b0-5691-5495-a8a2-3fe7b34af273","title":"Identificación de energías peligrosas","narration_text":"Cuando falta un dato crítico, conservar el estado seguro es también una decisión técnica.\n\nLa primera referencia es: Eléctrica, hidráulica, neumática, mecánica, térmica, química, gravedad y presión almacenada. Incluir alimentaciones remotas, energías cruzadas y equipos aguas arriba o abajo. Un mando apagado no demuestra ausencia de energía.\n\nSituación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera. El fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Criterio de resolución Persisten articulación movimiento por pendiente presión residual y posible arranque. Se inmoviliza articula calza aísla bloquea descarga verifica y controla la llave conforme al procedimiento.\n\nPensemos en una situación de campo. La medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: todas las fuentes.","duration_seconds":152,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-046.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-046.png","explanation":"Objetivo\n\nEléctrica, hidráulica, neumática, mecánica, térmica, química, gravedad y presión almacenada. Incluir alimentaciones remotas, energías cruzadas y equipos aguas arriba o abajo. Un mando apagado no demuestra ausencia de energía.\n\nExplicación detallada\n\nSituación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera. El fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía. Criterio de resolución Persisten articulación movimiento por pendiente presión residual y posible arranque. Se inmoviliza articula calza aísla bloquea descarga verifica y controla la llave conforme al procedimiento.\n\nLectura guiada de la diapositiva\n\n• Eléctrica, hidráulica, neumática, mecánica, térmica, química, gravedad y presión almacenada. Incluir alimentaciones remotas, energías cruzadas y equipos aguas arriba o abajo. Un mando apagado no demuestra ausencia de energía.\n\nAplicación práctica\n\nLa medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nTodas las fuentes","key_points":["Eléctrica, hidráulica, neumática, mecánica, térmica, química, gravedad y presión almacenada. Incluir alimentaciones remotas, energías cruzadas y equipos aguas arriba o abajo. Un mando apagado no demuestra ausencia de energía.","Todas las fuentes"],"stop_criterion":"Todas las fuentes","source_pages":"Bloque 3 · diapositiva 46","question":"Respecto a «Identificación de energías peligrosas», ¿qué criterio operativo es correcto?","correct_option":"Todas las fuentes: Eléctrica, hidráulica, neumática, mecánica, térmica, química, gravedad y presión almacenada. Incluir alimentaciones remotas, energías cruzadas y equipos aguas arriba o abajo. Un mando apagado no demuestra ausencia de energía.","question_explanation":"Eléctrica, hidráulica, neumática, mecánica, térmica, química, gravedad y presión almacenada. Incluir alimentaciones remotas, energías cruzadas y equipos aguas arriba o abajo. Un mando apagado no demuestra ausencia de energía."},{"slide_number":47,"block_number":3,"lesson_ordinal":5,"segment_position":7,"segment_id":"43c658f2-61d2-5c91-a412-cc1ea62580e0","slide_id":"6ebb4908-26d5-51d8-ae28-32e2009f69ae","note_id":"99e99625-e863-5149-a412-8caab58f80b8","title":"Preparación, parada y aislamiento","narration_text":"El criterio debe ser comprensible para quien ejecuta, para quien supervisa y para el turno siguiente.\n\nConviene comprobar lo siguiente: Definir alcance, comunicar a afectados e identificar todas las energías. Detener mediante el mando normal y separar físicamente con seccionadores o válvulas. Evitar realimentaciones; una parada de emergencia no equivale a aislamiento.\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nPensemos en una situación de campo. Dos tareas autorizadas coinciden en una instalación común. La incompatibilidad aparece en la interacción, no en la revisión aislada de cada permiso.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: aislamiento físico.","duration_seconds":141,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-047.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-047.png","explanation":"Objetivo\n\nDefinir alcance, comunicar a afectados e identificar todas las energías. Detener mediante el mando normal y separar físicamente con seccionadores o válvulas. Evitar realimentaciones; una parada de emergencia no equivale a aislamiento.\n\nExplicación detallada\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nLectura guiada de la diapositiva\n\n• Definir alcance, comunicar a afectados e identificar todas las energías. Detener mediante el mando normal y separar físicamente con seccionadores o válvulas. Evitar realimentaciones; una parada de emergencia no equivale a aislamiento.\n\nAplicación práctica\n\nDos tareas autorizadas coinciden en una instalación común. La incompatibilidad aparece en la interacción, no en la revisión aislada de cada permiso.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nAislamiento físico","key_points":["Definir alcance, comunicar a afectados e identificar todas las energías. Detener mediante el mando normal y separar físicamente con seccionadores o válvulas. Evitar realimentaciones; una parada de emergencia no equivale a aislamiento.","Aislamiento físico"],"stop_criterion":"Aislamiento físico","source_pages":"Bloque 3 · diapositiva 47","question":"Respecto a «Preparación, parada y aislamiento», ¿qué criterio operativo es correcto?","correct_option":"Aislamiento físico: Definir alcance, comunicar a afectados e identificar todas las energías. Detener mediante el mando normal y separar físicamente con seccionadores o válvulas. Evitar realimentaciones; una parada de emergencia no equivale a aislamiento.","question_explanation":"Definir alcance, comunicar a afectados e identificar todas las energías. Detener mediante el mando normal y separar físicamente con seccionadores o válvulas. Evitar realimentaciones; una parada de emergencia no equivale a aislamiento."},{"slide_number":48,"block_number":3,"lesson_ordinal":5,"segment_position":8,"segment_id":"a08197db-eafb-5cf3-b117-dc7cd668eb03","slide_id":"4a1ba11f-4bad-5c3d-a663-66fdf3eab131","note_id":"3c8f6b62-8127-5ba4-a194-23e1c80ab880","title":"Bloqueo, etiquetado y control de llaves","narration_text":"Cada autorización necesita una condición de partida y una señal inequívoca de pérdida de control.\n\nEl punto de partida es: Cada persona expuesta mantiene control de su bloqueo. El bloqueo grupal requiere caja o sistema trazable; la etiqueta informa pero no sustituye el bloqueo. Los cambios de turno deben transferirse sin huecos de protección.\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nPensemos en una situación de campo. En una consignación grupal cambia el turno y una llave queda sin titular activo; el hueco de custodia puede permitir una reenergización inesperada.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: control personal.","duration_seconds":141,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-048.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-048.png","explanation":"Objetivo\n\nCada persona expuesta mantiene control de su bloqueo. El bloqueo grupal requiere caja o sistema trazable; la etiqueta informa pero no sustituye el bloqueo. Los cambios de turno deben transferirse sin huecos de protección.\n\nExplicación detallada\n\nEl fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nLectura guiada de la diapositiva\n\n• Cada persona expuesta mantiene control de su bloqueo. El bloqueo grupal requiere caja o sistema trazable; la etiqueta informa pero no sustituye el bloqueo. Los cambios de turno deben transferirse sin huecos de protección.\n\nAplicación práctica\n\nEn una consignación grupal cambia el turno y una llave queda sin titular activo; el hueco de custodia puede permitir una reenergización inesperada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nControl personal","key_points":["Cada persona expuesta mantiene control de su bloqueo. El bloqueo grupal requiere caja o sistema trazable; la etiqueta informa pero no sustituye el bloqueo. Los cambios de turno deben transferirse sin huecos de protección.","Control personal"],"stop_criterion":"Control personal","source_pages":"Bloque 3 · diapositiva 48","question":"Respecto a «Bloqueo, etiquetado y control de llaves», ¿qué criterio operativo es correcto?","correct_option":"Control personal: Cada persona expuesta mantiene control de su bloqueo. El bloqueo grupal requiere caja o sistema trazable; la etiqueta informa pero no sustituye el bloqueo. Los cambios de turno deben transferirse sin huecos de protección.","question_explanation":"Cada persona expuesta mantiene control de su bloqueo. El bloqueo grupal requiere caja o sistema trazable; la etiqueta informa pero no sustituye el bloqueo. Los cambios de turno deben transferirse sin huecos de protección."},{"slide_number":49,"block_number":3,"lesson_ordinal":5,"segment_position":9,"segment_id":"41833f57-7272-5f68-8d65-e646a764f23a","slide_id":"ac25a38d-d337-5218-9087-5320cab6b7bc","note_id":"39f6a1fe-b3fc-53f7-a3cc-9d977e902079","title":"Eliminación de energía residual","narration_text":"En interior, una condición segura debe demostrarse antes de exponer a una persona.\n\nPara empezar, se sitúa el criterio: Descargar acumuladores, purgar líneas, comprobar presión cero y descargar condensadores. Bloquear partes elevadas, inmovilizar articulaciones, calzar ruedas y asegurar muelles o cargas. Verificar la estabilidad después de eliminar o contener la energía.\n\nSituación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera. Criterio de resolución Persisten articulación movimiento por pendiente presión residual y posible arranque. Se inmoviliza articula calza aísla bloquea descarga verifica y controla la llave conforme al procedimiento. El fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nPensemos en una situación de campo. Imagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: residual no significa inocua.","duration_seconds":158,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-049.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-049.png","explanation":"Objetivo\n\nDescargar acumuladores, purgar líneas, comprobar presión cero y descargar condensadores. Bloquear partes elevadas, inmovilizar articulaciones, calzar ruedas y asegurar muelles o cargas. Verificar la estabilidad después de eliminar o contener la energía.\n\nExplicación detallada\n\nSituación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera. Criterio de resolución Persisten articulación movimiento por pendiente presión residual y posible arranque. Se inmoviliza articula calza aísla bloquea descarga verifica y controla la llave conforme al procedimiento. El fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nLectura guiada de la diapositiva\n\n• Descargar acumuladores, purgar líneas, comprobar presión cero y descargar condensadores. Bloquear partes elevadas, inmovilizar articulaciones, calzar ruedas y asegurar muelles o cargas. Verificar la estabilidad después de eliminar o contener la energía.\n\nAplicación práctica\n\nImagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nResidual no significa inocua","key_points":["Descargar acumuladores, purgar líneas, comprobar presión cero y descargar condensadores. Bloquear partes elevadas, inmovilizar articulaciones, calzar ruedas y asegurar muelles o cargas. Verificar la estabilidad después de eliminar o contener la energía.","Residual no significa inocua"],"stop_criterion":"Residual no significa inocua","source_pages":"Bloque 3 · diapositiva 49","question":"Respecto a «Eliminación de energía residual», ¿qué criterio operativo es correcto?","correct_option":"Residual no significa inocua: Descargar acumuladores, purgar líneas, comprobar presión cero y descargar condensadores. Bloquear partes elevadas, inmovilizar articulaciones, calzar ruedas y asegurar muelles o cargas. Verificar la estabilidad después de eliminar o contener la energía.","question_explanation":"Descargar acumuladores, purgar líneas, comprobar presión cero y descargar condensadores. Bloquear partes elevadas, inmovilizar articulaciones, calzar ruedas y asegurar muelles o cargas. Verificar la estabilidad después de eliminar o contener la energía."},{"slide_number":50,"block_number":3,"lesson_ordinal":5,"segment_position":10,"segment_id":"d4a90b26-e005-5c7a-9530-6b3fe5432165","slide_id":"6cb69a4f-9146-5173-9a6f-59c0dd36954f","note_id":"ec86471c-e1ac-5c00-ac9d-8b7488e93f56","title":"Verificación de ausencia de energía y restitución","narration_text":"La prevención empieza describiendo el trabajo real, no suponiendo que hoy será igual que ayer.\n\nLa primera referencia es: Intentar arranque controlado y medir cero tensión o presión con instrumento comprobado. Antes de restituir, revisar montaje, resguardos, herramientas, personas y zona. Reenergizar solo con autorización, comunicación y prueba funcional segura.\n\nSituación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera. Criterio de resolución Persisten articulación movimiento por pendiente presión residual y posible arranque. Se inmoviliza articula calza aísla bloquea descarga verifica y controla la llave conforme al procedimiento. El fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nPensemos en una situación de campo. Tras una reparación, todos los bloqueos se han retirado, pero aún quedan herramientas y una persona dentro de la zona de movimiento.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: verificar antes de tocar.","duration_seconds":151,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-050.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-050.png","explanation":"Objetivo\n\nIntentar arranque controlado y medir cero tensión o presión con instrumento comprobado. Antes de restituir, revisar montaje, resguardos, herramientas, personas y zona. Reenergizar solo con autorización, comunicación y prueba funcional segura.\n\nExplicación detallada\n\nSituación Un LHD está parado con el cazo apoyado en el suelo. El mecánico considera que la energía hidráulica está eliminada y entra entre articulaciones para revisar una manguera. Criterio de resolución Persisten articulación movimiento por pendiente presión residual y posible arranque. Se inmoviliza articula calza aísla bloquea descarga verifica y controla la llave conforme al procedimiento. El fallo crítico no siempre impide que la máquina se mueva. Por eso la inspección debe centrarse en frenos dirección protección contra incendio visibilidad y control de energía.\n\nLectura guiada de la diapositiva\n\n• Intentar arranque controlado y medir cero tensión o presión con instrumento comprobado. Antes de restituir, revisar montaje, resguardos, herramientas, personas y zona. Reenergizar solo con autorización, comunicación y prueba funcional segura.\n\nAplicación práctica\n\nTras una reparación, todos los bloqueos se han retirado, pero aún quedan herramientas y una persona dentro de la zona de movimiento.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nVerificar antes de tocar","key_points":["Intentar arranque controlado y medir cero tensión o presión con instrumento comprobado. Antes de restituir, revisar montaje, resguardos, herramientas, personas y zona. Reenergizar solo con autorización, comunicación y prueba funcional segura.","Verificar antes de tocar"],"stop_criterion":"Verificar antes de tocar","source_pages":"Bloque 3 · diapositiva 50","question":"Respecto a «Verificación de ausencia de energía y restitución», ¿qué criterio operativo es correcto?","correct_option":"Verificar antes de tocar: Intentar arranque controlado y medir cero tensión o presión con instrumento comprobado. Antes de restituir, revisar montaje, resguardos, herramientas, personas y zona. Reenergizar solo con autorización, comunicación y prueba funcional segura.","question_explanation":"Intentar arranque controlado y medir cero tensión o presión con instrumento comprobado. Antes de restituir, revisar montaje, resguardos, herramientas, personas y zona. Reenergizar solo con autorización, comunicación y prueba funcional segura."},{"slide_number":51,"block_number":3,"lesson_ordinal":6,"segment_position":1,"segment_id":"3d0450b4-4c1c-57e6-9b37-f12c1372470b","slide_id":"b7ca876f-7a31-54b9-a901-40801594688e","note_id":"9170b2af-5e1e-5186-873f-50139d7311f8","title":"Selección, ajuste y compatibilidad de los EPI","narration_text":"Bajo tierra, terreno, aire, agua, equipos y secuencia pueden cambiar durante el mismo turno.\n\nConviene comprobar lo siguiente: Seleccionar según riesgo, tarea, ambiente, usuario y tiempo de uso. Verificar talla, ajuste, estado, vida útil, limpieza, almacenamiento y mantenimiento. Comprobar compatibilidad entre casco, lámpara, gafas, protección respiratoria, auditiva, arnés y comunicación.\n\nEl equipo de protección individual debe ser adecuado, ajustarse al usuario y ser compatible con casco lámpara gafas comunicación y otros elementos. Su uso no compensa una ventilación o sostenimiento deficientes.\n\nPensemos en una situación de campo. Producción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: la última barrera.","duration_seconds":145,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-051.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-051.png","explanation":"Objetivo\n\nSeleccionar según riesgo, tarea, ambiente, usuario y tiempo de uso. Verificar talla, ajuste, estado, vida útil, limpieza, almacenamiento y mantenimiento. Comprobar compatibilidad entre casco, lámpara, gafas, protección respiratoria, auditiva, arnés y comunicación.\n\nExplicación detallada\n\nEl equipo de protección individual debe ser adecuado, ajustarse al usuario y ser compatible con casco lámpara gafas comunicación y otros elementos. Su uso no compensa una ventilación o sostenimiento deficientes.\n\nLectura guiada de la diapositiva\n\n• Seleccionar según riesgo, tarea, ambiente, usuario y tiempo de uso. Verificar talla, ajuste, estado, vida útil, limpieza, almacenamiento y mantenimiento. Comprobar compatibilidad entre casco, lámpara, gafas, protección respiratoria, auditiva, arnés y comunicación.\n\nAplicación práctica\n\nProducción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nLa última barrera","key_points":["Seleccionar según riesgo, tarea, ambiente, usuario y tiempo de uso. Verificar talla, ajuste, estado, vida útil, limpieza, almacenamiento y mantenimiento. Comprobar compatibilidad entre casco, lámpara, gafas, protección respiratoria, auditiva, arnés y comunicación.","La última barrera"],"stop_criterion":"La última barrera","source_pages":"Bloque 3 · diapositiva 51","question":"Respecto a «Selección, ajuste y compatibilidad de los EPI», ¿qué criterio operativo es correcto?","correct_option":"La última barrera: Seleccionar según riesgo, tarea, ambiente, usuario y tiempo de uso. Verificar talla, ajuste, estado, vida útil, limpieza, almacenamiento y mantenimiento. Comprobar compatibilidad entre casco, lámpara, gafas, protección respiratoria, auditiva, arnés y comunicación.","question_explanation":"Seleccionar según riesgo, tarea, ambiente, usuario y tiempo de uso. Verificar talla, ajuste, estado, vida útil, limpieza, almacenamiento y mantenimiento. Comprobar compatibilidad entre casco, lámpara, gafas, protección respiratoria, auditiva, arnés y comunicación."},{"slide_number":52,"block_number":3,"lesson_ordinal":6,"segment_position":2,"segment_id":"6f9a3a71-70ab-59cc-8f19-a8aaa36eee8c","slide_id":"df22c400-5660-55be-b29e-84e3c0b00842","note_id":"93d99401-cf2d-5513-a7e7-e36fcc4ca942","title":"Protección respiratoria, autorrescatadores, herramientas, plataformas y rescate","narration_text":"Supervisar consiste en comparar lo que ocurre en campo con un criterio definido de antemano.\n\nEl punto de partida es: El filtro y ajuste deben corresponder al contaminante; los equipos filtrantes no sirven con oxígeno insuficiente. El autorrescatador facilita el escape y no sustituye una ruta viable. Retirar herramientas defectuosas y definir acceso, anclajes, comunicación y rescate antes de trabajos complejos.\n\nEl equipo de protección individual debe ser adecuado, ajustarse al usuario y ser compatible con casco lámpara gafas comunicación y otros elementos. Su uso no compensa una ventilación o sostenimiento deficientes.\n\nPensemos en una situación de campo. Un respirador filtrante se entrega para una atmósfera con oxígeno insuficiente; el equipo no aporta oxígeno y no controla ese escenario.\n\nPara intervenir de forma segura, primero se identifica el sistema completo y todas sus energías, incluidas las remotas y las residuales. Después se detiene, se aísla físicamente, se bloquea, se descarga y se verifica la ausencia de energía. La restitución exige revisar montaje, resguardos, herramientas y personas.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: conocer las limitaciones.","duration_seconds":146,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-052.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-052.png","explanation":"Objetivo\n\nEl filtro y ajuste deben corresponder al contaminante; los equipos filtrantes no sirven con oxígeno insuficiente. El autorrescatador facilita el escape y no sustituye una ruta viable. Retirar herramientas defectuosas y definir acceso, anclajes, comunicación y rescate antes de trabajos complejos.\n\nExplicación detallada\n\nEl equipo de protección individual debe ser adecuado, ajustarse al usuario y ser compatible con casco lámpara gafas comunicación y otros elementos. Su uso no compensa una ventilación o sostenimiento deficientes.\n\nLectura guiada de la diapositiva\n\n• El filtro y ajuste deben corresponder al contaminante; los equipos filtrantes no sirven con oxígeno insuficiente. El autorrescatador facilita el escape y no sustituye una ruta viable. Retirar herramientas defectuosas y definir acceso, anclajes, comunicación y rescate antes de trabajos complejos.\n\nAplicación práctica\n\nUn respirador filtrante se entrega para una atmósfera con oxígeno insuficiente; el equipo no aporta oxígeno y no controla ese escenario.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nConocer las limitaciones","key_points":["El filtro y ajuste deben corresponder al contaminante; los equipos filtrantes no sirven con oxígeno insuficiente. El autorrescatador facilita el escape y no sustituye una ruta viable. Retirar herramientas defectuosas y definir acceso, anclajes, comunicación y rescate antes de trabajos complejos.","Conocer las limitaciones"],"stop_criterion":"Conocer las limitaciones","source_pages":"Bloque 3 · diapositiva 52","question":"Respecto a «Protección respiratoria, autorrescatadores, herramientas, plataformas y rescate», ¿qué criterio operativo es correcto?","correct_option":"Conocer las limitaciones: El filtro y ajuste deben corresponder al contaminante; los equipos filtrantes no sirven con oxígeno insuficiente. El autorrescatador facilita el escape y no sustituye una ruta viable. Retirar herramientas defectuosas y definir acceso, anclajes, comunicación y rescate antes de trabajos complejos.","question_explanation":"El filtro y ajuste deben corresponder al contaminante; los equipos filtrantes no sirven con oxígeno insuficiente. El autorrescatador facilita el escape y no sustituye una ruta viable. Retirar herramientas defectuosas y definir acceso, anclajes, comunicación y rescate antes de trabajos complejos."},{"slide_number":53,"block_number":4,"lesson_ordinal":7,"segment_position":1,"segment_id":"883e9033-f917-5a6a-8b79-ea6a7bb5f4c0","slide_id":"66306e9f-eb82-5b8f-80c5-0c211b8113f4","note_id":"d980f0bc-5fad-5899-93e2-07d662d21ffe","title":"Finalidad de una inspección preventiva","narration_text":"Una tarea habitual también necesita límites claros y una comprobación proporcionada al riesgo.\n\nPara empezar, se sitúa el criterio: Detectar desviaciones antes de que produzcan daño. Verificar que las barreras existen, funcionan y se adaptan a los cambios. Asignar acciones, responsables, plazos y criterios de cierre; marcar una lista no basta.\n\nLa vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas.\n\nPensemos en una situación de campo. Una contrata aplica su procedimiento, pero desconoce un cambio reciente de la explotación. La coordinación debe llevar el cambio hasta el punto de trabajo antes de autorizar la actividad.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: inspeccionar para decidir.","duration_seconds":174,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-053.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-053.png","explanation":"Objetivo\n\nDetectar desviaciones antes de que produzcan daño. Verificar que las barreras existen, funcionan y se adaptan a los cambios. Asignar acciones, responsables, plazos y criterios de cierre; marcar una lista no basta.\n\nExplicación detallada\n\nLa vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas.\n\nLectura guiada de la diapositiva\n\n• Detectar desviaciones antes de que produzcan daño. Verificar que las barreras existen, funcionan y se adaptan a los cambios. Asignar acciones, responsables, plazos y criterios de cierre; marcar una lista no basta.\n\nAplicación práctica\n\nUna contrata aplica su procedimiento, pero desconoce un cambio reciente de la explotación. La coordinación debe llevar el cambio hasta el punto de trabajo antes de autorizar la actividad.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nInspeccionar para decidir","key_points":["Detectar desviaciones antes de que produzcan daño. Verificar que las barreras existen, funcionan y se adaptan a los cambios. Asignar acciones, responsables, plazos y criterios de cierre; marcar una lista no basta.","Inspeccionar para decidir"],"stop_criterion":"Inspeccionar para decidir","source_pages":"Bloque 4 · diapositiva 53","question":"Respecto a «Finalidad de una inspección preventiva», ¿qué criterio operativo es correcto?","correct_option":"Inspeccionar para decidir: Detectar desviaciones antes de que produzcan daño. Verificar que las barreras existen, funcionan y se adaptan a los cambios. Asignar acciones, responsables, plazos y criterios de cierre; marcar una lista no basta.","question_explanation":"Detectar desviaciones antes de que produzcan daño. Verificar que las barreras existen, funcionan y se adaptan a los cambios. Asignar acciones, responsables, plazos y criterios de cierre; marcar una lista no basta."},{"slide_number":54,"block_number":4,"lesson_ordinal":7,"segment_position":2,"segment_id":"19ef3d24-045a-5c36-9ddc-93ff33815caa","slide_id":"3e18fe08-1ad5-5c16-b38b-96acc88ec6e8","note_id":"3fd71481-3bb1-516e-b8b9-122bf1dbedbd","title":"Orden recomendado de inspección","narration_text":"La decisión técnica debe precisar qué se acepta, qué obliga a parar y qué permite reanudar.\n\nLa primera referencia es: Primero presencia, accesos y evacuación; después atmósfera y ventilación. Continuar con terreno, sostenimiento, agua, transporte y equipos. Revisar tareas, energías, permisos e interferencias sin entrar en zonas no verificadas.\n\nSituación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre.\n\nPensemos en una situación de campo. Una ronda empieza por el frente sin haber confirmado presencia, evacuación ni atmósfera, exponiendo al inspector antes de verificar las primeras barreras.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: orden de exposición.","duration_seconds":152,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-054.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-054.png","explanation":"Objetivo\n\nPrimero presencia, accesos y evacuación; después atmósfera y ventilación. Continuar con terreno, sostenimiento, agua, transporte y equipos. Revisar tareas, energías, permisos e interferencias sin entrar en zonas no verificadas.\n\nExplicación detallada\n\nSituación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre.\n\nLectura guiada de la diapositiva\n\n• Primero presencia, accesos y evacuación; después atmósfera y ventilación. Continuar con terreno, sostenimiento, agua, transporte y equipos. Revisar tareas, energías, permisos e interferencias sin entrar en zonas no verificadas.\n\nAplicación práctica\n\nUna ronda empieza por el frente sin haber confirmado presencia, evacuación ni atmósfera, exponiendo al inspector antes de verificar las primeras barreras.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nOrden de exposición","key_points":["Primero presencia, accesos y evacuación; después atmósfera y ventilación. Continuar con terreno, sostenimiento, agua, transporte y equipos. Revisar tareas, energías, permisos e interferencias sin entrar en zonas no verificadas.","Orden de exposición"],"stop_criterion":"Orden de exposición","source_pages":"Bloque 4 · diapositiva 54","question":"Respecto a «Orden recomendado de inspección», ¿qué criterio operativo es correcto?","correct_option":"Orden de exposición: Primero presencia, accesos y evacuación; después atmósfera y ventilación. Continuar con terreno, sostenimiento, agua, transporte y equipos. Revisar tareas, energías, permisos e interferencias sin entrar en zonas no verificadas.","question_explanation":"Primero presencia, accesos y evacuación; después atmósfera y ventilación. Continuar con terreno, sostenimiento, agua, transporte y equipos. Revisar tareas, energías, permisos e interferencias sin entrar en zonas no verificadas."},{"slide_number":55,"block_number":4,"lesson_ordinal":7,"segment_position":3,"segment_id":"d53cceb4-7dc4-52c4-ba41-3d7589db3adc","slide_id":"f0bd1b58-f83f-56e8-b465-a1c29b2c8ab6","note_id":"1d010575-e94f-5fd6-82c3-660805121ccd","title":"Frecuencia basada en el riesgo","narration_text":"Una barrera preventiva solo es útil cuando puede observarse, medirse o probarse.\n\nConviene comprobar lo siguiente: Antes de turno o entrada y durante operaciones críticas. Después de voladura, parada, incidente, lluvia, sismo, incendio, alarma o cambio. A mayor posibilidad de cambio, gravedad o pérdida de barrera, mayor frecuencia.\n\nLa vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector.\n\nPensemos en una situación de campo. El trabajo empieza dentro de criterio, pero una labor conectada cambia el aire, el agua o la circulación. El equipo debe reconocer el cambio antes de que la condición inicial deje de ser válida.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: criticidad y cambio.","duration_seconds":168,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-055.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-055.png","explanation":"Objetivo\n\nAntes de turno o entrada y durante operaciones críticas. Después de voladura, parada, incidente, lluvia, sismo, incendio, alarma o cambio. A mayor posibilidad de cambio, gravedad o pérdida de barrera, mayor frecuencia.\n\nExplicación detallada\n\nLa vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector.\n\nLectura guiada de la diapositiva\n\n• Antes de turno o entrada y durante operaciones críticas. Después de voladura, parada, incidente, lluvia, sismo, incendio, alarma o cambio. A mayor posibilidad de cambio, gravedad o pérdida de barrera, mayor frecuencia.\n\nAplicación práctica\n\nEl trabajo empieza dentro de criterio, pero una labor conectada cambia el aire, el agua o la circulación. El equipo debe reconocer el cambio antes de que la condición inicial deje de ser válida.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nCriticidad y cambio","key_points":["Antes de turno o entrada y durante operaciones críticas. Después de voladura, parada, incidente, lluvia, sismo, incendio, alarma o cambio. A mayor posibilidad de cambio, gravedad o pérdida de barrera, mayor frecuencia.","Criticidad y cambio"],"stop_criterion":"Criticidad y cambio","source_pages":"Bloque 4 · diapositiva 55","question":"Respecto a «Frecuencia basada en el riesgo», ¿qué criterio operativo es correcto?","correct_option":"Criticidad y cambio: Antes de turno o entrada y durante operaciones críticas. Después de voladura, parada, incidente, lluvia, sismo, incendio, alarma o cambio. A mayor posibilidad de cambio, gravedad o pérdida de barrera, mayor frecuencia.","question_explanation":"Antes de turno o entrada y durante operaciones críticas. Después de voladura, parada, incidente, lluvia, sismo, incendio, alarma o cambio. A mayor posibilidad de cambio, gravedad o pérdida de barrera, mayor frecuencia."},{"slide_number":56,"block_number":4,"lesson_ordinal":7,"segment_position":4,"segment_id":"1cf40089-6999-52ee-8f5e-defb0c2d5726","slide_id":"20095a7e-c5a3-5e67-9c6a-a8df9c56ebae","note_id":"a2c22a5c-332f-5480-9edd-4911fbc3c517","title":"Inspecciones antes de entrar y después de una parada","narration_text":"Antes de autorizar hay que entender qué puede cambiar y hasta dónde llegarían sus efectos.\n\nEl punto de partida es: Confirmar autorización, presencia e información del turno anterior. Restablecer servicios desde zona segura y medir atmósfera antes de avanzar. Inspeccionar terreno, agua, rutas, equipos y comunicaciones; corregir y verificar de nuevo.\n\nCriterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector.\n\nPensemos en una situación de campo. Una corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: nunca usar una persona como detector.","duration_seconds":163,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-056.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-056.png","explanation":"Objetivo\n\nConfirmar autorización, presencia e información del turno anterior. Restablecer servicios desde zona segura y medir atmósfera antes de avanzar. Inspeccionar terreno, agua, rutas, equipos y comunicaciones; corregir y verificar de nuevo.\n\nExplicación detallada\n\nCriterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector.\n\nLectura guiada de la diapositiva\n\n• Confirmar autorización, presencia e información del turno anterior. Restablecer servicios desde zona segura y medir atmósfera antes de avanzar. Inspeccionar terreno, agua, rutas, equipos y comunicaciones; corregir y verificar de nuevo.\n\nAplicación práctica\n\nUna corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nNunca usar una persona como detector","key_points":["Confirmar autorización, presencia e información del turno anterior. Restablecer servicios desde zona segura y medir atmósfera antes de avanzar. Inspeccionar terreno, agua, rutas, equipos y comunicaciones; corregir y verificar de nuevo.","Nunca usar una persona como detector"],"stop_criterion":"Nunca usar una persona como detector","source_pages":"Bloque 4 · diapositiva 56","question":"Respecto a «Inspecciones antes de entrar y después de una parada», ¿qué criterio operativo es correcto?","correct_option":"Nunca usar una persona como detector: Confirmar autorización, presencia e información del turno anterior. Restablecer servicios desde zona segura y medir atmósfera antes de avanzar. Inspeccionar terreno, agua, rutas, equipos y comunicaciones; corregir y verificar de nuevo.","question_explanation":"Confirmar autorización, presencia e información del turno anterior. Restablecer servicios desde zona segura y medir atmósfera antes de avanzar. Inspeccionar terreno, agua, rutas, equipos y comunicaciones; corregir y verificar de nuevo."},{"slide_number":57,"block_number":4,"lesson_ordinal":7,"segment_position":5,"segment_id":"03994e5d-01c2-5008-be08-2cef1d6463ae","slide_id":"8ad71406-2f66-5359-87d7-06c951aed984","note_id":"9bb9f825-fe27-58c9-aad1-6ed103d60056","title":"Inspecciones posteriores a una voladura","narration_text":"La primera pregunta no es cómo producir más rápido, sino qué condición debe conservarse segura.\n\nPara empezar, se sitúa el criterio: Respetar la exclusión, ventilar y comprobar la atmósfera. Revisar barrenos fallidos, terreno, sostenimiento, servicios, polvo, humos y accesos. La persona competente verifica, registra y entrega la zona antes de la reentrada.\n\nCriterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre.\n\nPensemos en una situación de campo. Tras el disparo se cumple el tiempo de espera, pero la ventilación secundaria ha quedado dañada y el frente todavía no puede entregarse.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: reentrada controlada.","duration_seconds":167,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-057.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-057.png","explanation":"Objetivo\n\nRespetar la exclusión, ventilar y comprobar la atmósfera. Revisar barrenos fallidos, terreno, sostenimiento, servicios, polvo, humos y accesos. La persona competente verifica, registra y entrega la zona antes de la reentrada.\n\nExplicación detallada\n\nCriterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre.\n\nLectura guiada de la diapositiva\n\n• Respetar la exclusión, ventilar y comprobar la atmósfera. Revisar barrenos fallidos, terreno, sostenimiento, servicios, polvo, humos y accesos. La persona competente verifica, registra y entrega la zona antes de la reentrada.\n\nAplicación práctica\n\nTras el disparo se cumple el tiempo de espera, pero la ventilación secundaria ha quedado dañada y el frente todavía no puede entregarse.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nReentrada controlada","key_points":["Respetar la exclusión, ventilar y comprobar la atmósfera. Revisar barrenos fallidos, terreno, sostenimiento, servicios, polvo, humos y accesos. La persona competente verifica, registra y entrega la zona antes de la reentrada.","Reentrada controlada"],"stop_criterion":"Reentrada controlada","source_pages":"Bloque 4 · diapositiva 57","question":"Respecto a «Inspecciones posteriores a una voladura», ¿qué criterio operativo es correcto?","correct_option":"Reentrada controlada: Respetar la exclusión, ventilar y comprobar la atmósfera. Revisar barrenos fallidos, terreno, sostenimiento, servicios, polvo, humos y accesos. La persona competente verifica, registra y entrega la zona antes de la reentrada.","question_explanation":"Respetar la exclusión, ventilar y comprobar la atmósfera. Revisar barrenos fallidos, terreno, sostenimiento, servicios, polvo, humos y accesos. La persona competente verifica, registra y entrega la zona antes de la reentrada."},{"slide_number":58,"block_number":4,"lesson_ordinal":7,"segment_position":6,"segment_id":"15b12b40-7009-5c8f-869d-db67385a212f","slide_id":"aad8ba7c-bfd1-55dd-b0d6-7fc7e824922f","note_id":"24267778-5a48-5026-9bd4-3ab563a9391b","title":"Mediciones y evidencias objetivas","narration_text":"En una labor conectada con otras, una decisión local nunca se analiza de forma aislada.\n\nLa primera referencia es: Indicar punto, método, instrumento, fecha, hora y condiciones de operación. Registrar resultado, criterio de aceptación, persona y decisión. La fotografía ayuda, pero no sustituye mediciones o pruebas necesarias.\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas.\n\nPensemos en una situación de campo. La medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: trazabilidad técnica.","duration_seconds":165,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-058.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-058.png","explanation":"Objetivo\n\nIndicar punto, método, instrumento, fecha, hora y condiciones de operación. Registrar resultado, criterio de aceptación, persona y decisión. La fotografía ayuda, pero no sustituye mediciones o pruebas necesarias.\n\nExplicación detallada\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas.\n\nLectura guiada de la diapositiva\n\n• Indicar punto, método, instrumento, fecha, hora y condiciones de operación. Registrar resultado, criterio de aceptación, persona y decisión. La fotografía ayuda, pero no sustituye mediciones o pruebas necesarias.\n\nAplicación práctica\n\nLa medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nTrazabilidad técnica","key_points":["Indicar punto, método, instrumento, fecha, hora y condiciones de operación. Registrar resultado, criterio de aceptación, persona y decisión. La fotografía ayuda, pero no sustituye mediciones o pruebas necesarias.","Trazabilidad técnica"],"stop_criterion":"Trazabilidad técnica","source_pages":"Bloque 4 · diapositiva 58","question":"Respecto a «Mediciones y evidencias objetivas», ¿qué criterio operativo es correcto?","correct_option":"Trazabilidad técnica: Indicar punto, método, instrumento, fecha, hora y condiciones de operación. Registrar resultado, criterio de aceptación, persona y decisión. La fotografía ayuda, pero no sustituye mediciones o pruebas necesarias.","question_explanation":"Indicar punto, método, instrumento, fecha, hora y condiciones de operación. Registrar resultado, criterio de aceptación, persona y decisión. La fotografía ayuda, pero no sustituye mediciones o pruebas necesarias."},{"slide_number":59,"block_number":4,"lesson_ordinal":7,"segment_position":7,"segment_id":"896a6218-e68e-5d91-954c-e21dde3a0a11","slide_id":"28e6b04c-e474-5615-9d03-9ccd346b9b4f","note_id":"2ec4a483-5b06-5dce-87a9-105a6a6cbe73","title":"Cómo redactar un hallazgo útil","narration_text":"El control empieza por reconocer la señal temprana, antes de que el peligro alcance a alguien.\n\nConviene comprobar lo siguiente: Ubicación exacta, condición observada, medida o fotografía y personas expuestas. Acción inmediata, responsable, plazo y criterio de cierre. Redactar hechos, distinguir corrección inmediata y acción contra la recurrencia.\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas.\n\nPensemos en una situación de campo. Dos tareas autorizadas coinciden en una instalación común. La incompatibilidad aparece en la interacción, no en la revisión aislada de cada permiso.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: otra persona debe entenderlo.","duration_seconds":165,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-059.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-059.png","explanation":"Objetivo\n\nUbicación exacta, condición observada, medida o fotografía y personas expuestas. Acción inmediata, responsable, plazo y criterio de cierre. Redactar hechos, distinguir corrección inmediata y acción contra la recurrencia.\n\nExplicación detallada\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas.\n\nLectura guiada de la diapositiva\n\n• Ubicación exacta, condición observada, medida o fotografía y personas expuestas. Acción inmediata, responsable, plazo y criterio de cierre. Redactar hechos, distinguir corrección inmediata y acción contra la recurrencia.\n\nAplicación práctica\n\nDos tareas autorizadas coinciden en una instalación común. La incompatibilidad aparece en la interacción, no en la revisión aislada de cada permiso.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nOtra persona debe entenderlo","key_points":["Ubicación exacta, condición observada, medida o fotografía y personas expuestas. Acción inmediata, responsable, plazo y criterio de cierre. Redactar hechos, distinguir corrección inmediata y acción contra la recurrencia.","Otra persona debe entenderlo"],"stop_criterion":"Otra persona debe entenderlo","source_pages":"Bloque 4 · diapositiva 59","question":"Respecto a «Cómo redactar un hallazgo útil», ¿qué criterio operativo es correcto?","correct_option":"Otra persona debe entenderlo: Ubicación exacta, condición observada, medida o fotografía y personas expuestas. Acción inmediata, responsable, plazo y criterio de cierre. Redactar hechos, distinguir corrección inmediata y acción contra la recurrencia.","question_explanation":"Ubicación exacta, condición observada, medida o fotografía y personas expuestas. Acción inmediata, responsable, plazo y criterio de cierre. Redactar hechos, distinguir corrección inmediata y acción contra la recurrencia."},{"slide_number":60,"block_number":4,"lesson_ordinal":7,"segment_position":8,"segment_id":"384a2ff6-394b-51a8-a134-bfef2838dc48","slide_id":"42e59cce-f138-546a-9fab-015bb1f5658c","note_id":"afb908cf-65be-5522-96e6-0fca3b509aac","title":"Hallazgos deficientes y hallazgos trazables","narration_text":"Una comprobación útil termina en una decisión concreta: continuar, corregir o detener.\n\nEl punto de partida es: Evitar descripciones vagas como «Techo mal», «Ventilación baja» o «Arreglar frenos». Precisar labor, evidencia, valor medido, exposición y medida adoptada. Ejemplo: equipo identificado, prueba no conforme, fuera de servicio y llave controlada.\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas.\n\nPensemos en una situación de campo. Un registro que dice solo ventilación baja no permite localizar el punto, conocer el método, comparar el criterio ni comprobar el cierre.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: hechos verificables.","duration_seconds":167,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-060.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-060.png","explanation":"Objetivo\n\nEvitar descripciones vagas como «Techo mal», «Ventilación baja» o «Arreglar frenos». Precisar labor, evidencia, valor medido, exposición y medida adoptada. Ejemplo: equipo identificado, prueba no conforme, fuera de servicio y llave controlada.\n\nExplicación detallada\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas.\n\nLectura guiada de la diapositiva\n\n• Evitar descripciones vagas como «Techo mal», «Ventilación baja» o «Arreglar frenos». Precisar labor, evidencia, valor medido, exposición y medida adoptada. Ejemplo: equipo identificado, prueba no conforme, fuera de servicio y llave controlada.\n\nAplicación práctica\n\nUn registro que dice solo ventilación baja no permite localizar el punto, conocer el método, comparar el criterio ni comprobar el cierre.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nHechos verificables","key_points":["Evitar descripciones vagas como «Techo mal», «Ventilación baja» o «Arreglar frenos». Precisar labor, evidencia, valor medido, exposición y medida adoptada. Ejemplo: equipo identificado, prueba no conforme, fuera de servicio y llave controlada.","Hechos verificables"],"stop_criterion":"Hechos verificables","source_pages":"Bloque 4 · diapositiva 60","question":"Respecto a «Hallazgos deficientes y hallazgos trazables», ¿qué criterio operativo es correcto?","correct_option":"Hechos verificables: Evitar descripciones vagas como «Techo mal», «Ventilación baja» o «Arreglar frenos». Precisar labor, evidencia, valor medido, exposición y medida adoptada. Ejemplo: equipo identificado, prueba no conforme, fuera de servicio y llave controlada.","question_explanation":"Evitar descripciones vagas como «Techo mal», «Ventilación baja» o «Arreglar frenos». Precisar labor, evidencia, valor medido, exposición y medida adoptada. Ejemplo: equipo identificado, prueba no conforme, fuera de servicio y llave controlada."},{"slide_number":61,"block_number":4,"lesson_ordinal":7,"segment_position":9,"segment_id":"dc5c5522-241b-532e-a91c-d94de2eb591a","slide_id":"815b14f3-f632-5534-89bd-d0aea4747f98","note_id":"be5b8a69-43e8-5b64-92fb-6b6864d420ae","title":"Información necesaria en una entrega entre turnos","narration_text":"La ausencia de un incidente no demuestra que las barreras sigan disponibles.\n\nPara empezar, se sitúa el criterio: Personas y equipos dentro; cierres, barreras y accesos restringidos. Estado de ventilación, bombeo, energía, comunicaciones, salidas, voladuras y permisos. Cambios y acciones pendientes con responsable, plazo y autoridad de cierre.\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector.\n\nPensemos en una situación de campo. Imagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: continuidad sin lagunas.","duration_seconds":168,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-061.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-061.png","explanation":"Objetivo\n\nPersonas y equipos dentro; cierres, barreras y accesos restringidos. Estado de ventilación, bombeo, energía, comunicaciones, salidas, voladuras y permisos. Cambios y acciones pendientes con responsable, plazo y autoridad de cierre.\n\nExplicación detallada\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector.\n\nLectura guiada de la diapositiva\n\n• Personas y equipos dentro; cierres, barreras y accesos restringidos. Estado de ventilación, bombeo, energía, comunicaciones, salidas, voladuras y permisos. Cambios y acciones pendientes con responsable, plazo y autoridad de cierre.\n\nAplicación práctica\n\nImagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nContinuidad sin lagunas","key_points":["Personas y equipos dentro; cierres, barreras y accesos restringidos. Estado de ventilación, bombeo, energía, comunicaciones, salidas, voladuras y permisos. Cambios y acciones pendientes con responsable, plazo y autoridad de cierre.","Continuidad sin lagunas"],"stop_criterion":"Continuidad sin lagunas","source_pages":"Bloque 4 · diapositiva 61","question":"Respecto a «Información necesaria en una entrega entre turnos», ¿qué criterio operativo es correcto?","correct_option":"Continuidad sin lagunas: Personas y equipos dentro; cierres, barreras y accesos restringidos. Estado de ventilación, bombeo, energía, comunicaciones, salidas, voladuras y permisos. Cambios y acciones pendientes con responsable, plazo y autoridad de cierre.","question_explanation":"Personas y equipos dentro; cierres, barreras y accesos restringidos. Estado de ventilación, bombeo, energía, comunicaciones, salidas, voladuras y permisos. Cambios y acciones pendientes con responsable, plazo y autoridad de cierre."},{"slide_number":62,"block_number":4,"lesson_ordinal":7,"segment_position":10,"segment_id":"6802db16-87a5-5723-a4fc-86a235d9ff3b","slide_id":"fbd529db-b151-5209-bf3b-90c41bed95f7","note_id":"5d83da0f-5116-53a9-99ee-2eceea75bbc0","title":"Desencadenantes de la gestión del cambio","narration_text":"Cuando falta un dato crítico, conservar el estado seguro es también una decisión técnica.\n\nLa primera referencia es: Geología, deformación, ventilación, agua, equipos, método o secuencia. Organización, contratistas, horarios, rutas, energía o emergencia. Describir, evaluar, actualizar documentos, controlar, formar, verificar y revisar.\n\nSituación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre.\n\nPensemos en una situación de campo. Durante el relevo, el turno entrante recibe solo la frase todo correcto. Sin ubicación, medición, prueba ni responsable, esa comunicación no permite saber si la condición sigue controlada.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: un cambio temporal también cuenta.","duration_seconds":148,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-062.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-062.png","explanation":"Objetivo\n\nGeología, deformación, ventilación, agua, equipos, método o secuencia. Organización, contratistas, horarios, rutas, energía o emergencia. Describir, evaluar, actualizar documentos, controlar, formar, verificar y revisar.\n\nExplicación detallada\n\nSituación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector. Un hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre.\n\nLectura guiada de la diapositiva\n\n• Geología, deformación, ventilación, agua, equipos, método o secuencia. Organización, contratistas, horarios, rutas, energía o emergencia. Describir, evaluar, actualizar documentos, controlar, formar, verificar y revisar.\n\nAplicación práctica\n\nDurante el relevo, el turno entrante recibe solo la frase todo correcto. Sin ubicación, medición, prueba ni responsable, esa comunicación no permite saber si la condición sigue controlada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nUn cambio temporal también cuenta","key_points":["Geología, deformación, ventilación, agua, equipos, método o secuencia. Organización, contratistas, horarios, rutas, energía o emergencia. Describir, evaluar, actualizar documentos, controlar, formar, verificar y revisar.","Un cambio temporal también cuenta"],"stop_criterion":"Un cambio temporal también cuenta","source_pages":"Bloque 4 · diapositiva 62","question":"Respecto a «Desencadenantes de la gestión del cambio», ¿qué criterio operativo es correcto?","correct_option":"Un cambio temporal también cuenta: Geología, deformación, ventilación, agua, equipos, método o secuencia. Organización, contratistas, horarios, rutas, energía o emergencia. Describir, evaluar, actualizar documentos, controlar, formar, verificar y revisar.","question_explanation":"Geología, deformación, ventilación, agua, equipos, método o secuencia. Organización, contratistas, horarios, rutas, energía o emergencia. Describir, evaluar, actualizar documentos, controlar, formar, verificar y revisar."},{"slide_number":63,"block_number":4,"lesson_ordinal":8,"segment_position":1,"segment_id":"a5f198d6-4a54-5dda-a288-85d6c8b91f84","slide_id":"6b8b5365-a087-5d2c-97bc-86f2a2f2f038","note_id":"a090d163-eac1-5df8-8d6d-d736d6ee2a3f","title":"Cierre temporal de una labor","narration_text":"El criterio debe ser comprensible para quien ejecuta, para quien supervisa y para el turno siguiente.\n\nConviene comprobar lo siguiente: Definir alcance y responsable; retirar o asegurar personas, explosivos, combustibles y equipos. Aislar energías, decidir ventilación y bombeo e instalar barreras y señalización. Conservar drenaje, estabilidad y vigilancia; registrar requisitos de reapertura.\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector.\n\nPensemos en una situación de campo. Producción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: cerrar no es abandonar.","duration_seconds":170,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-063.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-063.png","explanation":"Objetivo\n\nDefinir alcance y responsable; retirar o asegurar personas, explosivos, combustibles y equipos. Aislar energías, decidir ventilación y bombeo e instalar barreras y señalización. Conservar drenaje, estabilidad y vigilancia; registrar requisitos de reapertura.\n\nExplicación detallada\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas. Situación Una bomba se desconectó por mantenimiento y la ventilación auxiliar permaneció parada. El lunes no se observa agua en el acceso y se propone enviar primero a un operario con detector.\n\nLectura guiada de la diapositiva\n\n• Definir alcance y responsable; retirar o asegurar personas, explosivos, combustibles y equipos. Aislar energías, decidir ventilación y bombeo e instalar barreras y señalización. Conservar drenaje, estabilidad y vigilancia; registrar requisitos de reapertura.\n\nAplicación práctica\n\nProducción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nCerrar no es abandonar","key_points":["Definir alcance y responsable; retirar o asegurar personas, explosivos, combustibles y equipos. Aislar energías, decidir ventilación y bombeo e instalar barreras y señalización. Conservar drenaje, estabilidad y vigilancia; registrar requisitos de reapertura.","Cerrar no es abandonar"],"stop_criterion":"Cerrar no es abandonar","source_pages":"Bloque 4 · diapositiva 63","question":"Respecto a «Cierre temporal de una labor», ¿qué criterio operativo es correcto?","correct_option":"Cerrar no es abandonar: Definir alcance y responsable; retirar o asegurar personas, explosivos, combustibles y equipos. Aislar energías, decidir ventilación y bombeo e instalar barreras y señalización. Conservar drenaje, estabilidad y vigilancia; registrar requisitos de reapertura.","question_explanation":"Definir alcance y responsable; retirar o asegurar personas, explosivos, combustibles y equipos. Aislar energías, decidir ventilación y bombeo e instalar barreras y señalización. Conservar drenaje, estabilidad y vigilancia; registrar requisitos de reapertura."},{"slide_number":64,"block_number":4,"lesson_ordinal":8,"segment_position":2,"segment_id":"07ca5bca-5224-5921-b32e-c038511961a5","slide_id":"fe07ef2b-18c4-51f9-975a-fa0e4d6174a3","note_id":"c648d12d-4515-5d62-8682-5785156ada43","title":"Secuencia de reapertura y caso de una labor parada","narration_text":"Cada autorización necesita una condición de partida y una señal inequívoca de pérdida de control.\n\nEl punto de partida es: Revisar cierre, planos, Documento sobre Seguridad y Salud, disposición interna de seguridad, permisos, incidentes y cambios. Restablecer servicios desde zona segura, medir atmósfera e inspeccionar progresivamente. Corregir, repetir pruebas y autorizar con restricciones documentadas; no usar personas como prueba.\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas.\n\nPensemos en una situación de campo. Una labor cerrada durante el fin de semana tiene la ventilación y el bombeo parados; enviar primero a un operario con detector convertiría a la persona en prueba.\n\nUna inspección útil produce decisiones. Debe indicar el punto exacto, la condición observada, el criterio de aceptación, la medida inmediata, la persona responsable y la evidencia que permitirá cerrar la desviación. La frecuencia aumenta cuando el entorno puede cambiar o la consecuencia es grave.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: reapertura progresiva.","duration_seconds":142,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-064.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-064.png","explanation":"Objetivo\n\nRevisar cierre, planos, DSS, DIS, permisos, incidentes y cambios. Restablecer servicios desde zona segura, medir atmósfera e inspeccionar progresivamente. Corregir, repetir pruebas y autorizar con restricciones documentadas; no usar personas como prueba.\n\nExplicación detallada\n\nUn hallazgo debe permitir que otra persona localice la condición, entienda el riesgo y sepa qué se ha hecho. Expresiones como revisar zona o todo correcto no aportan trazabilidad. Deben constar labor y referencia, condición observada, medida o fotografía cuando proceda, personas expuestas, acción inmediata, responsable, plazo y criterio de cierre. Criterio de resolución No se usa a una persona como prueba. Se revisa el cierre, se restablecen servicios desde zona segura, se mide a distancia cuando sea posible y se inspecciona por personal competente con ruta y comunicación controladas. La vigilancia combina inspecciones planificadas, mediciones, planos actualizados, entrega entre turnos y criterios de reapertura. El objetivo no es producir partes, sino detectar desviaciones antes de exponer personas.\n\nLectura guiada de la diapositiva\n\n• Revisar cierre, planos, DSS, DIS, permisos, incidentes y cambios. Restablecer servicios desde zona segura, medir atmósfera e inspeccionar progresivamente. Corregir, repetir pruebas y autorizar con restricciones documentadas; no usar personas como prueba.\n\nAplicación práctica\n\nUna labor cerrada durante el fin de semana tiene la ventilación y el bombeo parados; enviar primero a un operario con detector convertiría a la persona en prueba.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nReapertura progresiva","key_points":["Revisar cierre, planos, DSS, DIS, permisos, incidentes y cambios. Restablecer servicios desde zona segura, medir atmósfera e inspeccionar progresivamente. Corregir, repetir pruebas y autorizar con restricciones documentadas; no usar personas como prueba.","Reapertura progresiva"],"stop_criterion":"Reapertura progresiva","source_pages":"Bloque 4 · diapositiva 64","question":"Respecto a «Secuencia de reapertura y caso de una labor parada», ¿qué criterio operativo es correcto?","correct_option":"Reapertura progresiva: Revisar cierre, planos, DSS, DIS, permisos, incidentes y cambios. Restablecer servicios desde zona segura, medir atmósfera e inspeccionar progresivamente. Corregir, repetir pruebas y autorizar con restricciones documentadas; no usar personas como prueba.","question_explanation":"Revisar cierre, planos, DSS, DIS, permisos, incidentes y cambios. Restablecer servicios desde zona segura, medir atmósfera e inspeccionar progresivamente. Corregir, repetir pruebas y autorizar con restricciones documentadas; no usar personas como prueba."},{"slide_number":65,"block_number":5,"lesson_ordinal":9,"segment_position":1,"segment_id":"84f4ed37-c00f-583e-a781-d2f60b34282f","slide_id":"0453c6a2-69bd-561a-96d6-705500f22db3","note_id":"bfde3478-05fc-5e71-b776-f2747c09877d","title":"Interferencias visibles y remotas","narration_text":"En interior, una condición segura debe demostrarse antes de exponer a una persona.\n\nPara empezar, se sitúa el criterio: Dos equipos pueden interferir en un cruce, pero también a distancia mediante aire, energía, agua o material. Una actividad puede afectar la circulación o eliminar una salida. Evaluar simultaneidad en espacio, tiempo y sistemas conectados.\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nPensemos en una situación de campo. Una contrata aplica su procedimiento, pero desconoce un cambio reciente de la explotación. La coordinación debe llevar el cambio hasta el punto de trabajo antes de autorizar la actividad.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: ver lo que no está al lado.","duration_seconds":145,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-065.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-065.png","explanation":"Objetivo\n\nDos equipos pueden interferir en un cruce, pero también a distancia mediante aire, energía, agua o material. Una actividad puede afectar la circulación o eliminar una salida. Evaluar simultaneidad en espacio, tiempo y sistemas conectados.\n\nExplicación detallada\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nLectura guiada de la diapositiva\n\n• Dos equipos pueden interferir en un cruce, pero también a distancia mediante aire, energía, agua o material. Una actividad puede afectar la circulación o eliminar una salida. Evaluar simultaneidad en espacio, tiempo y sistemas conectados.\n\nAplicación práctica\n\nUna contrata aplica su procedimiento, pero desconoce un cambio reciente de la explotación. La coordinación debe llevar el cambio hasta el punto de trabajo antes de autorizar la actividad.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nVer lo que no está al lado","key_points":["Dos equipos pueden interferir en un cruce, pero también a distancia mediante aire, energía, agua o material. Una actividad puede afectar la circulación o eliminar una salida. Evaluar simultaneidad en espacio, tiempo y sistemas conectados.","Ver lo que no está al lado"],"stop_criterion":"Ver lo que no está al lado","source_pages":"Bloque 5 · diapositiva 65","question":"Respecto a «Interferencias visibles y remotas», ¿qué criterio operativo es correcto?","correct_option":"Ver lo que no está al lado: Dos equipos pueden interferir en un cruce, pero también a distancia mediante aire, energía, agua o material. Una actividad puede afectar la circulación o eliminar una salida. Evaluar simultaneidad en espacio, tiempo y sistemas conectados.","question_explanation":"Dos equipos pueden interferir en un cruce, pero también a distancia mediante aire, energía, agua o material. Una actividad puede afectar la circulación o eliminar una salida. Evaluar simultaneidad en espacio, tiempo y sistemas conectados."},{"slide_number":66,"block_number":5,"lesson_ordinal":9,"segment_position":2,"segment_id":"6e9e8018-315f-51a2-b3b5-017b5f6d4bf0","slide_id":"1e2ca18d-a570-590b-a344-f64234716c2b","note_id":"6a8ea2e3-43c1-5de6-af54-e0613753f4f6","title":"Matriz de actividades simultáneas","narration_text":"La prevención empieza describiendo el trabajo real, no suponiendo que hoy será igual que ayer.\n\nLa primera referencia es: Cruzar actividades y revisar acceso, atmósfera, energía, estructura, comunicación y emergencia. Ejemplos: voladura-mantenimiento, diésel-peatón, nivel superior-tránsito inferior. Incluir ventilación-frentes conectados, bombeo-electricidad e izado-trabajo bajo carga.\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nPensemos en una situación de campo. La observación parece tranquilizadora, aunque falta una comprobación instrumental o funcional. Si la decisión depende de ese dato, la actividad permanece detenida hasta obtenerlo.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: interacciones críticas.","duration_seconds":151,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-066.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-066.png","explanation":"Objetivo\n\nCruzar actividades y revisar acceso, atmósfera, energía, estructura, comunicación y emergencia. Ejemplos: voladura-mantenimiento, diésel-peatón, nivel superior-tránsito inferior. Incluir ventilación-frentes conectados, bombeo-electricidad e izado-trabajo bajo carga.\n\nExplicación detallada\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nLectura guiada de la diapositiva\n\n• Cruzar actividades y revisar acceso, atmósfera, energía, estructura, comunicación y emergencia. Ejemplos: voladura-mantenimiento, diésel-peatón, nivel superior-tránsito inferior. Incluir ventilación-frentes conectados, bombeo-electricidad e izado-trabajo bajo carga.\n\nAplicación práctica\n\nLa observación parece tranquilizadora, aunque falta una comprobación instrumental o funcional. Si la decisión depende de ese dato, la actividad permanece detenida hasta obtenerlo.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nInteracciones críticas","key_points":["Cruzar actividades y revisar acceso, atmósfera, energía, estructura, comunicación y emergencia. Ejemplos: voladura-mantenimiento, diésel-peatón, nivel superior-tránsito inferior. Incluir ventilación-frentes conectados, bombeo-electricidad e izado-trabajo bajo carga.","Interacciones críticas"],"stop_criterion":"Interacciones críticas","source_pages":"Bloque 5 · diapositiva 66","question":"Respecto a «Matriz de actividades simultáneas», ¿qué criterio operativo es correcto?","correct_option":"Interacciones críticas: Cruzar actividades y revisar acceso, atmósfera, energía, estructura, comunicación y emergencia. Ejemplos: voladura-mantenimiento, diésel-peatón, nivel superior-tránsito inferior. Incluir ventilación-frentes conectados, bombeo-electricidad e izado-trabajo bajo carga.","question_explanation":"Cruzar actividades y revisar acceso, atmósfera, energía, estructura, comunicación y emergencia. Ejemplos: voladura-mantenimiento, diésel-peatón, nivel superior-tránsito inferior. Incluir ventilación-frentes conectados, bombeo-electricidad e izado-trabajo bajo carga."},{"slide_number":67,"block_number":5,"lesson_ordinal":9,"segment_position":3,"segment_id":"6ca244f0-9e97-5b87-a5d9-38a97fd68154","slide_id":"ab453f80-9257-5986-aa7e-bccf36d9c007","note_id":"3c37b2c8-612f-5505-a68f-61920ce94795","title":"Interferencias entre voladura, mantenimiento y producción","narration_text":"Bajo tierra, terreno, aire, agua, equipos y secuencia pueden cambiar durante el mismo turno.\n\nConviene comprobar lo siguiente: Cada permiso puede ser correcto y, sin embargo, la secuencia global ser incompatible. Impedir energizar, disparar, circular o reabrir mientras otra actividad mantenga personas expuestas. Definir ventanas, exclusiones, responsables, comunicaciones y entrega de la instalación.\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nPensemos en una situación de campo. Mantenimiento ocupa una instalación mientras producción prepara una prueba aguas arriba; dos permisos válidos pueden introducir energía en la misma cadena.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: una secuencia única.","duration_seconds":154,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-067.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-067.png","explanation":"Objetivo\n\nCada permiso puede ser correcto y, sin embargo, la secuencia global ser incompatible. Impedir energizar, disparar, circular o reabrir mientras otra actividad mantenga personas expuestas. Definir ventanas, exclusiones, responsables, comunicaciones y entrega de la instalación.\n\nExplicación detallada\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nLectura guiada de la diapositiva\n\n• Cada permiso puede ser correcto y, sin embargo, la secuencia global ser incompatible. Impedir energizar, disparar, circular o reabrir mientras otra actividad mantenga personas expuestas. Definir ventanas, exclusiones, responsables, comunicaciones y entrega de la instalación.\n\nAplicación práctica\n\nMantenimiento ocupa una instalación mientras producción prepara una prueba aguas arriba; dos permisos válidos pueden introducir energía en la misma cadena.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nUna secuencia única","key_points":["Cada permiso puede ser correcto y, sin embargo, la secuencia global ser incompatible. Impedir energizar, disparar, circular o reabrir mientras otra actividad mantenga personas expuestas. Definir ventanas, exclusiones, responsables, comunicaciones y entrega de la instalación.","Una secuencia única"],"stop_criterion":"Una secuencia única","source_pages":"Bloque 5 · diapositiva 67","question":"Respecto a «Interferencias entre voladura, mantenimiento y producción», ¿qué criterio operativo es correcto?","correct_option":"Una secuencia única: Cada permiso puede ser correcto y, sin embargo, la secuencia global ser incompatible. Impedir energizar, disparar, circular o reabrir mientras otra actividad mantenga personas expuestas. Definir ventanas, exclusiones, responsables, comunicaciones y entrega de la instalación.","question_explanation":"Cada permiso puede ser correcto y, sin embargo, la secuencia global ser incompatible. Impedir energizar, disparar, circular o reabrir mientras otra actividad mantenga personas expuestas. Definir ventanas, exclusiones, responsables, comunicaciones y entrega de la instalación."},{"slide_number":68,"block_number":5,"lesson_ordinal":9,"segment_position":4,"segment_id":"6c393d3a-3d37-5a78-b6a9-b785c0d1ea98","slide_id":"dedc8650-000b-5ef7-9785-3df87064cfe7","note_id":"d369abe2-def1-5126-8b26-1212bd0be72a","title":"Tráfico, ventilación, bombeo e izado","narration_text":"Supervisar consiste en comparar lo que ocurre en campo con un criterio definido de antemano.\n\nEl punto de partida es: Una obstrucción puede eliminar una salida y un vehículo puede dañar conductos. El bombeo puede inundar aguas abajo o afectar a otras energías. El izado crea zonas de caída: coordinar rutas, servicios y criterios de parada.\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nPensemos en una situación de campo. Una corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: servicios interdependientes.","duration_seconds":157,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-068.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-068.png","explanation":"Objetivo\n\nUna obstrucción puede eliminar una salida y un vehículo puede dañar conductos. El bombeo puede inundar aguas abajo o afectar a otras energías. El izado crea zonas de caída: coordinar rutas, servicios y criterios de parada.\n\nExplicación detallada\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nLectura guiada de la diapositiva\n\n• Una obstrucción puede eliminar una salida y un vehículo puede dañar conductos. El bombeo puede inundar aguas abajo o afectar a otras energías. El izado crea zonas de caída: coordinar rutas, servicios y criterios de parada.\n\nAplicación práctica\n\nUna corrección elimina el síntoma visible, aunque no se ha comprobado la causa. Reabrir en ese momento dejaría la misma desviación preparada para repetirse.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nServicios interdependientes","key_points":["Una obstrucción puede eliminar una salida y un vehículo puede dañar conductos. El bombeo puede inundar aguas abajo o afectar a otras energías. El izado crea zonas de caída: coordinar rutas, servicios y criterios de parada.","Servicios interdependientes"],"stop_criterion":"Servicios interdependientes","source_pages":"Bloque 5 · diapositiva 68","question":"Respecto a «Tráfico, ventilación, bombeo e izado», ¿qué criterio operativo es correcto?","correct_option":"Servicios interdependientes: Una obstrucción puede eliminar una salida y un vehículo puede dañar conductos. El bombeo puede inundar aguas abajo o afectar a otras energías. El izado crea zonas de caída: coordinar rutas, servicios y criterios de parada.","question_explanation":"Una obstrucción puede eliminar una salida y un vehículo puede dañar conductos. El bombeo puede inundar aguas abajo o afectar a otras energías. El izado crea zonas de caída: coordinar rutas, servicios y criterios de parada."},{"slide_number":69,"block_number":5,"lesson_ordinal":9,"segment_position":5,"segment_id":"88f340cc-f7f8-52d0-a143-1bac1bb0c9d6","slide_id":"38d59ab2-a91c-544e-b17f-1050f4d49d01","note_id":"9eff6dce-8003-5a13-b1ce-68c0b0bc0055","title":"Coordinación de actividades empresariales","narration_text":"Una tarea habitual también necesita límites claros y una comprobación proporcionada al riesgo.\n\nPara empezar, se sitúa el criterio: Intercambiar riesgos específicos y cambios; comprobar competencia, autorizaciones, equipos y disposición interna de seguridad. Nombrar interlocutores y unificar tráfico, alarma, presencia y permisos. Coordinar secuencia y entrega, supervisar y corregir; los documentos no sustituyen el campo.\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nPensemos en una situación de campo. Dos contratas comparten rampa, pero usan canales de radio y criterios de prioridad diferentes; la documentación no ha producido una regla común de campo.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: un sistema común.","duration_seconds":160,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-069.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-069.png","explanation":"Objetivo\n\nIntercambiar riesgos específicos y cambios; comprobar competencia, autorizaciones, equipos y DIS. Nombrar interlocutores y unificar tráfico, alarma, presencia y permisos. Coordinar secuencia y entrega, supervisar y corregir; los documentos no sustituyen el campo.\n\nExplicación detallada\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nLectura guiada de la diapositiva\n\n• Intercambiar riesgos específicos y cambios; comprobar competencia, autorizaciones, equipos y DIS. Nombrar interlocutores y unificar tráfico, alarma, presencia y permisos. Coordinar secuencia y entrega, supervisar y corregir; los documentos no sustituyen el campo.\n\nAplicación práctica\n\nDos contratas comparten rampa, pero usan canales de radio y criterios de prioridad diferentes; la documentación no ha producido una regla común de campo.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nUn sistema común","key_points":["Intercambiar riesgos específicos y cambios; comprobar competencia, autorizaciones, equipos y DIS. Nombrar interlocutores y unificar tráfico, alarma, presencia y permisos. Coordinar secuencia y entrega, supervisar y corregir; los documentos no sustituyen el campo.","Un sistema común"],"stop_criterion":"Un sistema común","source_pages":"Bloque 5 · diapositiva 69","question":"Respecto a «Coordinación de actividades empresariales», ¿qué criterio operativo es correcto?","correct_option":"Un sistema común: Intercambiar riesgos específicos y cambios; comprobar competencia, autorizaciones, equipos y DIS. Nombrar interlocutores y unificar tráfico, alarma, presencia y permisos. Coordinar secuencia y entrega, supervisar y corregir; los documentos no sustituyen el campo.","question_explanation":"Intercambiar riesgos específicos y cambios; comprobar competencia, autorizaciones, equipos y DIS. Nombrar interlocutores y unificar tráfico, alarma, presencia y permisos. Coordinar secuencia y entrega, supervisar y corregir; los documentos no sustituyen el campo."},{"slide_number":70,"block_number":5,"lesson_ordinal":9,"segment_position":6,"segment_id":"c6b1a7d5-509f-5f0f-acde-49f7ae652af3","slide_id":"d7985de8-251d-5770-8b83-ce660e93b6e4","note_id":"951daf72-bae0-55de-8729-8b8dd1951d87","title":"Permisos de trabajo y condiciones mínimas","narration_text":"La decisión técnica debe precisar qué se acepta, qué obliga a parar y qué permite reanudar.\n\nLa primera referencia es: Aplicables a trabajos en caliente, eléctricos, izado, altura, accesos complejos y reentrada. Identificar alcance, lugar, vigencia, personas, aislamientos, mediciones e interferencias. Incluir vigilancia, emergencia y cierre; el permiso deja de valer cuando cambian las condiciones.\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nPensemos en una situación de campo. La medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: el permiso depende de la condición.","duration_seconds":161,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-070.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-070.png","explanation":"Objetivo\n\nAplicables a trabajos en caliente, eléctricos, izado, altura, accesos complejos y reentrada. Identificar alcance, lugar, vigencia, personas, aislamientos, mediciones e interferencias. Incluir vigilancia, emergencia y cierre; el permiso deja de valer cuando cambian las condiciones.\n\nExplicación detallada\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nLectura guiada de la diapositiva\n\n• Aplicables a trabajos en caliente, eléctricos, izado, altura, accesos complejos y reentrada. Identificar alcance, lugar, vigencia, personas, aislamientos, mediciones e interferencias. Incluir vigilancia, emergencia y cierre; el permiso deja de valer cuando cambian las condiciones.\n\nAplicación práctica\n\nLa medida prevista funciona en condiciones normales, pero no durante una parada o una emergencia. El análisis debe incluir también ese estado menos frecuente.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nEl permiso depende de la condición","key_points":["Aplicables a trabajos en caliente, eléctricos, izado, altura, accesos complejos y reentrada. Identificar alcance, lugar, vigencia, personas, aislamientos, mediciones e interferencias. Incluir vigilancia, emergencia y cierre; el permiso deja de valer cuando cambian las condiciones.","El permiso depende de la condición"],"stop_criterion":"El permiso depende de la condición","source_pages":"Bloque 5 · diapositiva 70","question":"Respecto a «Permisos de trabajo y condiciones mínimas», ¿qué criterio operativo es correcto?","correct_option":"El permiso depende de la condición: Aplicables a trabajos en caliente, eléctricos, izado, altura, accesos complejos y reentrada. Identificar alcance, lugar, vigencia, personas, aislamientos, mediciones e interferencias. Incluir vigilancia, emergencia y cierre; el permiso deja de valer cuando cambian las condiciones.","question_explanation":"Aplicables a trabajos en caliente, eléctricos, izado, altura, accesos complejos y reentrada. Identificar alcance, lugar, vigencia, personas, aislamientos, mediciones e interferencias. Incluir vigilancia, emergencia y cierre; el permiso deja de valer cuando cambian las condiciones."},{"slide_number":71,"block_number":5,"lesson_ordinal":9,"segment_position":7,"segment_id":"2bc0f0b5-3e49-5751-9b43-110826587f63","slide_id":"8616ce78-e221-5076-8ef4-e35a6ba713c5","note_id":"3736747c-ae9a-5cc5-8f45-f121cbae1da0","title":"Entrega y devolución de áreas e instalaciones","narration_text":"Una barrera preventiva solo es útil cuando puede observarse, medirse o probarse.\n\nConviene comprobar lo siguiente: Definir límites, energías, personas, equipos, barreras, permisos y defectos pendientes. Comprobar la entrega por ambas partes y dejar registro. La devolución confirma limpieza, montaje, protecciones y preparación para prueba o producción autorizada.\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nPensemos en una situación de campo. Dos tareas autorizadas coinciden en una instalación común. La incompatibilidad aparece en la interacción, no en la revisión aislada de cada permiso.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: entrega formal.","duration_seconds":151,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-071.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-071.png","explanation":"Objetivo\n\nDefinir límites, energías, personas, equipos, barreras, permisos y defectos pendientes. Comprobar la entrega por ambas partes y dejar registro. La devolución confirma limpieza, montaje, protecciones y preparación para prueba o producción autorizada.\n\nExplicación detallada\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nLectura guiada de la diapositiva\n\n• Definir límites, energías, personas, equipos, barreras, permisos y defectos pendientes. Comprobar la entrega por ambas partes y dejar registro. La devolución confirma limpieza, montaje, protecciones y preparación para prueba o producción autorizada.\n\nAplicación práctica\n\nDos tareas autorizadas coinciden en una instalación común. La incompatibilidad aparece en la interacción, no en la revisión aislada de cada permiso.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nEntrega formal","key_points":["Definir límites, energías, personas, equipos, barreras, permisos y defectos pendientes. Comprobar la entrega por ambas partes y dejar registro. La devolución confirma limpieza, montaje, protecciones y preparación para prueba o producción autorizada.","Entrega formal"],"stop_criterion":"Entrega formal","source_pages":"Bloque 5 · diapositiva 71","question":"Respecto a «Entrega y devolución de áreas e instalaciones», ¿qué criterio operativo es correcto?","correct_option":"Entrega formal: Definir límites, energías, personas, equipos, barreras, permisos y defectos pendientes. Comprobar la entrega por ambas partes y dejar registro. La devolución confirma limpieza, montaje, protecciones y preparación para prueba o producción autorizada.","question_explanation":"Definir límites, energías, personas, equipos, barreras, permisos y defectos pendientes. Comprobar la entrega por ambas partes y dejar registro. La devolución confirma limpieza, montaje, protecciones y preparación para prueba o producción autorizada."},{"slide_number":72,"block_number":5,"lesson_ordinal":9,"segment_position":8,"segment_id":"6887da69-5013-5e70-8e15-b1add249c50c","slide_id":"2cb48a70-e781-5f69-a11b-882b202ffecd","note_id":"0b2f3db4-0688-5f49-99e0-4e31d9373471","title":"Caso de permisos incompatibles y control conjunto de energías","narration_text":"Antes de autorizar hay que entender qué puede cambiar y hasta dónde llegarían sus efectos.\n\nEl punto de partida es: Mantenimiento bloquea una cinta mientras producción pretende probar el sistema aguas arriba. La interacción puede mover material o reenergizar aunque ambos permisos parezcan correctos. Exigir entrega única, responsable común y cierre de todos los bloqueos antes de probar.\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nPensemos en una situación de campo. Producción quiere probar una cinta mientras siguen activos bloqueos personales de mantenimiento; ninguna parte puede modificar por sí sola el aislamiento compartido.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: control conjunto.","duration_seconds":157,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-072.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-072.png","explanation":"Objetivo\n\nMantenimiento bloquea una cinta mientras producción pretende probar el sistema aguas arriba. La interacción puede mover material o reenergizar aunque ambos permisos parezcan correctos. Exigir entrega única, responsable común y cierre de todos los bloqueos antes de probar.\n\nExplicación detallada\n\nCriterio de resolución Existe una interferencia de energía y prueba. Los permisos deben vincularse a una entrega única de instalación con responsable común y prohibición de energizar hasta cierre de todos los bloqueos y comprobación de personas.\n\nLectura guiada de la diapositiva\n\n• Mantenimiento bloquea una cinta mientras producción pretende probar el sistema aguas arriba. La interacción puede mover material o reenergizar aunque ambos permisos parezcan correctos. Exigir entrega única, responsable común y cierre de todos los bloqueos antes de probar.\n\nAplicación práctica\n\nProducción quiere probar una cinta mientras siguen activos bloqueos personales de mantenimiento; ninguna parte puede modificar por sí sola el aislamiento compartido.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nControl conjunto","key_points":["Mantenimiento bloquea una cinta mientras producción pretende probar el sistema aguas arriba. La interacción puede mover material o reenergizar aunque ambos permisos parezcan correctos. Exigir entrega única, responsable común y cierre de todos los bloqueos antes de probar.","Control conjunto"],"stop_criterion":"Control conjunto","source_pages":"Bloque 5 · diapositiva 72","question":"Respecto a «Caso de permisos incompatibles y control conjunto de energías», ¿qué criterio operativo es correcto?","correct_option":"Control conjunto: Mantenimiento bloquea una cinta mientras producción pretende probar el sistema aguas arriba. La interacción puede mover material o reenergizar aunque ambos permisos parezcan correctos. Exigir entrega única, responsable común y cierre de todos los bloqueos antes de probar.","question_explanation":"Mantenimiento bloquea una cinta mientras producción pretende probar el sistema aguas arriba. La interacción puede mover material o reenergizar aunque ambos permisos parezcan correctos. Exigir entrega única, responsable común y cierre de todos los bloqueos antes de probar."},{"slide_number":73,"block_number":6,"lesson_ordinal":10,"segment_position":1,"segment_id":"bfe8af05-d72c-55b5-bd14-161af986d5bb","slide_id":"04796f7e-56b3-5e56-a99a-bf9e2433a546","note_id":"b4c99714-4ad3-5957-a0be-1c13a2a84fb9","title":"Jerarquía normativa práctica","narration_text":"La primera pregunta no es cómo producir más rápido, sino qué condición debe conservarse segura.\n\nPara empezar, se sitúa el criterio: Ley 31/1995, Real Decreto 39/1997 y Real Decreto 1389/1997. RGNBSM, ITC, proyecto, autorizaciones, Documento sobre Seguridad y Salud y disposición interna de seguridad. Procedimientos, permisos e instrucciones: saber qué documento gobierna y cuándo elevar una duda.\n\nPensemos en una situación de campo. Imagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: aplicar la norma adecuada.","duration_seconds":144,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-073.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-073.png","explanation":"Objetivo\n\nLey 31/1995, Real Decreto 39/1997 y Real Decreto 1389/1997. RGNBSM, ITC, proyecto, autorizaciones, DSS y DIS. Procedimientos, permisos e instrucciones: saber qué documento gobierna y cuándo elevar una duda.\n\nExplicación detallada\n\n\n\nLectura guiada de la diapositiva\n\n• Ley 31/1995, Real Decreto 39/1997 y Real Decreto 1389/1997. RGNBSM, ITC, proyecto, autorizaciones, DSS y DIS. Procedimientos, permisos e instrucciones: saber qué documento gobierna y cuándo elevar una duda.\n\nAplicación práctica\n\nImagine que la condición descrita era aceptable al inicio, pero cambia después de una avería o de una modificación de la secuencia. Continuar sin revisar convertiría una barrera válida en una suposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nAplicar la norma adecuada","key_points":["Ley 31/1995, Real Decreto 39/1997 y Real Decreto 1389/1997. RGNBSM, ITC, proyecto, autorizaciones, DSS y DIS. Procedimientos, permisos e instrucciones: saber qué documento gobierna y cuándo elevar una duda.","Aplicar la norma adecuada"],"stop_criterion":"Aplicar la norma adecuada","source_pages":"Bloque 6 · diapositiva 73","question":"Respecto a «Jerarquía normativa práctica», ¿qué criterio operativo es correcto?","correct_option":"Aplicar la norma adecuada: Ley 31/1995, Real Decreto 39/1997 y Real Decreto 1389/1997. RGNBSM, ITC, proyecto, autorizaciones, DSS y DIS. Procedimientos, permisos e instrucciones: saber qué documento gobierna y cuándo elevar una duda.","question_explanation":"Ley 31/1995, Real Decreto 39/1997 y Real Decreto 1389/1997. RGNBSM, ITC, proyecto, autorizaciones, DSS y DIS. Procedimientos, permisos e instrucciones: saber qué documento gobierna y cuándo elevar una duda."},{"slide_number":74,"block_number":6,"lesson_ordinal":10,"segment_position":2,"segment_id":"389daa08-2c8c-54bd-aec5-d3ade0a095b3","slide_id":"5e78c394-e3ee-52a5-b190-ebeea9992585","note_id":"13d12a03-dfd8-5520-ab87-1b5f8cdef3c3","title":"Ley de Prevención de Riesgos Laborales","narration_text":"En una labor conectada con otras, una decisión local nunca se analiza de forma aislada.\n\nLa primera referencia es: La Ley 31/1995 establece principios, obligaciones, consulta, formación y protección. La formación debe ser suficiente, adecuada y centrada en el puesto. Debe actualizarse cuando cambien funciones, tecnología o riesgos y no trasladar su coste al trabajador.\n\nPensemos en una situación de campo. Durante el relevo, el turno entrante recibe solo la frase todo correcto. Sin ubicación, medición, prueba ni responsable, esa comunicación no permite saber si la condición sigue controlada.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: prevención integrada.","duration_seconds":139,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-074.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-074.png","explanation":"Objetivo\n\nLa Ley 31/1995 establece principios, obligaciones, consulta, formación y protección. La formación debe ser suficiente, adecuada y centrada en el puesto. Debe actualizarse cuando cambien funciones, tecnología o riesgos y no trasladar su coste al trabajador.\n\nExplicación detallada\n\n\n\nLectura guiada de la diapositiva\n\n• La Ley 31/1995 establece principios, obligaciones, consulta, formación y protección. La formación debe ser suficiente, adecuada y centrada en el puesto. Debe actualizarse cuando cambien funciones, tecnología o riesgos y no trasladar su coste al trabajador.\n\nAplicación práctica\n\nDurante el relevo, el turno entrante recibe solo la frase todo correcto. Sin ubicación, medición, prueba ni responsable, esa comunicación no permite saber si la condición sigue controlada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nPrevención integrada","key_points":["La Ley 31/1995 establece principios, obligaciones, consulta, formación y protección. La formación debe ser suficiente, adecuada y centrada en el puesto. Debe actualizarse cuando cambien funciones, tecnología o riesgos y no trasladar su coste al trabajador.","Prevención integrada"],"stop_criterion":"Prevención integrada","source_pages":"Bloque 6 · diapositiva 74","question":"Respecto a «Ley de Prevención de Riesgos Laborales», ¿qué criterio operativo es correcto?","correct_option":"Prevención integrada: La Ley 31/1995 establece principios, obligaciones, consulta, formación y protección. La formación debe ser suficiente, adecuada y centrada en el puesto. Debe actualizarse cuando cambien funciones, tecnología o riesgos y no trasladar su coste al trabajador.","question_explanation":"La Ley 31/1995 establece principios, obligaciones, consulta, formación y protección. La formación debe ser suficiente, adecuada y centrada en el puesto. Debe actualizarse cuando cambien funciones, tecnología o riesgos y no trasladar su coste al trabajador."},{"slide_number":75,"block_number":6,"lesson_ordinal":10,"segment_position":3,"segment_id":"b634f3b7-00dd-5c07-ae97-1707ca4a493a","slide_id":"fd663026-9c35-5c57-b4ab-613ea26f45a4","note_id":"028a5576-5264-52cd-9558-a318fb257517","title":"Real Decreto 1389/1997","narration_text":"El control empieza por reconocer la señal temprana, antes de que el peligro alcance a alguien.\n\nConviene comprobar lo siguiente: Fija disposiciones mínimas de seguridad y salud en actividades mineras. Exige organización, supervisión, equipos, mantenimiento, instrucciones y control de riesgos especiales. Incluye incendio, explosión, atmósferas nocivas, evacuación, salvamento, comunicación y Documento sobre Seguridad y Salud.\n\nPensemos en una situación de campo. Producción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: mínimos mineros.","duration_seconds":137,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-075.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-075.png","explanation":"Objetivo\n\nFija disposiciones mínimas de seguridad y salud en actividades mineras. Exige organización, supervisión, equipos, mantenimiento, instrucciones y control de riesgos especiales. Incluye incendio, explosión, atmósferas nocivas, evacuación, salvamento, comunicación y DSS.\n\nExplicación detallada\n\n\n\nLectura guiada de la diapositiva\n\n• Fija disposiciones mínimas de seguridad y salud en actividades mineras. Exige organización, supervisión, equipos, mantenimiento, instrucciones y control de riesgos especiales. Incluye incendio, explosión, atmósferas nocivas, evacuación, salvamento, comunicación y DSS.\n\nAplicación práctica\n\nProducción propone resolver la situación con una advertencia verbal. Esa medida depende de la memoria y no sustituye un control físico, una exclusión o una verificación adecuada.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nMínimos mineros","key_points":["Fija disposiciones mínimas de seguridad y salud en actividades mineras. Exige organización, supervisión, equipos, mantenimiento, instrucciones y control de riesgos especiales. Incluye incendio, explosión, atmósferas nocivas, evacuación, salvamento, comunicación y DSS.","Mínimos mineros"],"stop_criterion":"Mínimos mineros","source_pages":"Bloque 6 · diapositiva 75","question":"Respecto a «Real Decreto 1389/1997», ¿qué criterio operativo es correcto?","correct_option":"Mínimos mineros: Fija disposiciones mínimas de seguridad y salud en actividades mineras. Exige organización, supervisión, equipos, mantenimiento, instrucciones y control de riesgos especiales. Incluye incendio, explosión, atmósferas nocivas, evacuación, salvamento, comunicación y DSS.","question_explanation":"Fija disposiciones mínimas de seguridad y salud en actividades mineras. Exige organización, supervisión, equipos, mantenimiento, instrucciones y control de riesgos especiales. Incluye incendio, explosión, atmósferas nocivas, evacuación, salvamento, comunicación y DSS."},{"slide_number":76,"block_number":6,"lesson_ordinal":10,"segment_position":4,"segment_id":"30f8d7c1-4329-546a-8b0e-88104cd7d2d0","slide_id":"c698bb22-66d3-5c0d-a90e-98ee91840b64","note_id":"60e5fd32-6e2b-539d-b16c-267a6a7068ad","title":"Reglamento General de Normas Básicas de Seguridad Minera","narration_text":"Una comprobación útil termina en una decisión concreta: continuar, corregir o detener.\n\nEl punto de partida es: El Real Decreto 863/1985 establece el marco técnico minero desarrollado por ITC. Las decisiones se integran con proyecto, dirección facultativa, autorizaciones y reglas de la instalación. El marco minero y la prevención general se aplican coordinadamente.\n\nPensemos en una situación de campo. La tarea se ha realizado muchas veces sin incidente. Ese historial no demuestra que el peligro haya desaparecido; puede significar únicamente que todavía no coincidieron fallo y exposición.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: marco técnico.","duration_seconds":139,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-076.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-076.png","explanation":"Objetivo\n\nEl Real Decreto 863/1985 establece el marco técnico minero desarrollado por ITC. Las decisiones se integran con proyecto, dirección facultativa, autorizaciones y reglas de la instalación. El marco minero y la prevención general se aplican coordinadamente.\n\nExplicación detallada\n\n\n\nLectura guiada de la diapositiva\n\n• El Real Decreto 863/1985 establece el marco técnico minero desarrollado por ITC. Las decisiones se integran con proyecto, dirección facultativa, autorizaciones y reglas de la instalación. El marco minero y la prevención general se aplican coordinadamente.\n\nAplicación práctica\n\nLa tarea se ha realizado muchas veces sin incidente. Ese historial no demuestra que el peligro haya desaparecido; puede significar únicamente que todavía no coincidieron fallo y exposición.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nMarco técnico","key_points":["El Real Decreto 863/1985 establece el marco técnico minero desarrollado por ITC. Las decisiones se integran con proyecto, dirección facultativa, autorizaciones y reglas de la instalación. El marco minero y la prevención general se aplican coordinadamente.","Marco técnico"],"stop_criterion":"Marco técnico","source_pages":"Bloque 6 · diapositiva 76","question":"Respecto a «Reglamento General de Normas Básicas de Seguridad Minera», ¿qué criterio operativo es correcto?","correct_option":"Marco técnico: El Real Decreto 863/1985 establece el marco técnico minero desarrollado por ITC. Las decisiones se integran con proyecto, dirección facultativa, autorizaciones y reglas de la instalación. El marco minero y la prevención general se aplican coordinadamente.","question_explanation":"El Real Decreto 863/1985 establece el marco técnico minero desarrollado por ITC. Las decisiones se integran con proyecto, dirección facultativa, autorizaciones y reglas de la instalación. El marco minero y la prevención general se aplican coordinadamente."},{"slide_number":77,"block_number":6,"lesson_ordinal":10,"segment_position":5,"segment_id":"490ebc88-c135-5cba-a638-cc448da3096f","slide_id":"e3a98d00-dab8-5d57-9d70-cb00cf39d093","note_id":"fe8333ca-63eb-5f0e-86e0-256cc2c55ead","title":"ITC aplicables a los trabajos de interior","narration_text":"La ausencia de un incidente no demuestra que las barreras sigan disponibles.\n\nPara empezar, se sitúa el criterio: ITC 02.1.02: formación preventiva. ITC 02.0.02: polvo y sílice. ITC 04.7.06: ambiente y gases. ITC 05.0.02: metano en carbón o labores con riesgo. Orden de 22 de marzo de 1988 y normativa de explosivos, incluido el RD 130/2017.\n\nPensemos en una situación de campo. Una obligación sobre gases, polvo o formación se aplica sin comprobar el texto vigente ni su ámbito; una referencia correcta fuera de contexto puede conducir a una decisión incorrecta.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPara verificar el aprendizaje, aplíquelo a tres momentos: antes, durante y después. Antes se confirman autorización, medios y criterios; durante se vigilan cambios y pérdida de barreras; después se comprueba el estado de entrega. Esta estructura evita que la prevención quede reducida a una firma inicial. También facilita que otro turno o empresa entienda qué controles siguen activos y cuáles no pueden retirarse.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: versión vigente y dss.","duration_seconds":142,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-077.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-077.png","explanation":"Objetivo\n\nITC 02.1.02: formación preventiva. ITC 02.0.02: polvo y sílice. ITC 04.7.06: ambiente y gases. ITC 05.0.02: metano en carbón o labores con riesgo. Orden de 22 de marzo de 1988 y normativa de explosivos, incluido el RD 130/2017.\n\nExplicación detallada\n\n\n\nLectura guiada de la diapositiva\n\n• ITC 02.1.02: formación preventiva. ITC 02.0.02: polvo y sílice. ITC 04.7.06: ambiente y gases. ITC 05.0.02: metano en carbón o labores con riesgo. Orden de 22 de marzo de 1988 y normativa de explosivos, incluido el RD 130/2017.\n\nAplicación práctica\n\nUna obligación sobre gases, polvo o formación se aplica sin comprobar el texto vigente ni su ámbito; una referencia correcta fuera de contexto puede conducir a una decisión incorrecta.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nVersión vigente y DSS","key_points":["ITC 02.1.02: formación preventiva. ITC 02.0.02: polvo y sílice. ITC 04.7.06: ambiente y gases. ITC 05.0.02: metano en carbón o labores con riesgo. Orden de 22 de marzo de 1988 y normativa de explosivos, incluido el RD 130/2017.","Versión vigente y DSS"],"stop_criterion":"Versión vigente y DSS","source_pages":"Bloque 6 · diapositiva 77","question":"Respecto a «ITC aplicables a los trabajos de interior», ¿qué criterio operativo es correcto?","correct_option":"Versión vigente y DSS: ITC 02.1.02: formación preventiva. ITC 02.0.02: polvo y sílice. ITC 04.7.06: ambiente y gases. ITC 05.0.02: metano en carbón o labores con riesgo. Orden de 22 de marzo de 1988 y normativa de explosivos, incluido el RD 130/2017.","question_explanation":"ITC 02.1.02: formación preventiva. ITC 02.0.02: polvo y sílice. ITC 04.7.06: ambiente y gases. ITC 05.0.02: metano en carbón o labores con riesgo. Orden de 22 de marzo de 1988 y normativa de explosivos, incluido el RD 130/2017."},{"slide_number":78,"block_number":6,"lesson_ordinal":10,"segment_position":6,"segment_id":"4a2499a8-98f7-5a5a-a62e-f1c8777c861b","slide_id":"3cfc698d-ab96-527c-b660-03ab3a31e062","note_id":"a64a8703-2294-5dca-a77e-80aa7e49c366","title":"Documento sobre Seguridad y Salud y Disposiciones Internas de Seguridad","narration_text":"Cuando falta un dato crítico, conservar el estado seguro es también una decisión técnica.\n\nLa primera referencia es: El Documento sobre Seguridad y Salud identifica peligros, evaluación, organización, planificación, mantenimiento y emergencia. Debe mantenerse actualizado y revisarse al menos anualmente o ante cambios importantes. Las disposición interna de seguridad convierten requisitos en reglas operativas específicas de la explotación.\n\nPensemos en una situación de campo. La observación parece tranquilizadora, aunque falta una comprobación instrumental o funcional. Si la decisión depende de ese dato, la actividad permanece detenida hasta obtenerlo.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nUn error frecuente consiste en confundir actividad con resultado. Inspeccionar, comunicar o señalizar son acciones, pero solo son eficaces si generan una condición controlada. La evidencia debe mostrar el resultado: una medición, una prueba funcional, una observación comparada con el estándar o una entrega documentada. Si el resultado no puede verificarse, la tarea se mantiene detenida o se rediseña.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: regla de aplicación.","duration_seconds":138,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-078.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-078.png","explanation":"Objetivo\n\nEl DSS identifica peligros, evaluación, organización, planificación, mantenimiento y emergencia. Debe mantenerse actualizado y revisarse al menos anualmente o ante cambios importantes. Las DIS convierten requisitos en reglas operativas específicas de la explotación.\n\nExplicación detallada\n\n\n\nLectura guiada de la diapositiva\n\n• El DSS identifica peligros, evaluación, organización, planificación, mantenimiento y emergencia. Debe mantenerse actualizado y revisarse al menos anualmente o ante cambios importantes. Las DIS convierten requisitos en reglas operativas específicas de la explotación.\n\nAplicación práctica\n\nLa observación parece tranquilizadora, aunque falta una comprobación instrumental o funcional. Si la decisión depende de ese dato, la actividad permanece detenida hasta obtenerlo.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nRegla de aplicación","key_points":["El DSS identifica peligros, evaluación, organización, planificación, mantenimiento y emergencia. Debe mantenerse actualizado y revisarse al menos anualmente o ante cambios importantes. Las DIS convierten requisitos en reglas operativas específicas de la explotación.","Regla de aplicación"],"stop_criterion":"Regla de aplicación","source_pages":"Bloque 6 · diapositiva 78","question":"Respecto a «Documento sobre Seguridad y Salud y Disposiciones Internas de Seguridad», ¿qué criterio operativo es correcto?","correct_option":"Regla de aplicación: El DSS identifica peligros, evaluación, organización, planificación, mantenimiento y emergencia. Debe mantenerse actualizado y revisarse al menos anualmente o ante cambios importantes. Las DIS convierten requisitos en reglas operativas específicas de la explotación.","question_explanation":"El DSS identifica peligros, evaluación, organización, planificación, mantenimiento y emergencia. Debe mantenerse actualizado y revisarse al menos anualmente o ante cambios importantes. Las DIS convierten requisitos en reglas operativas específicas de la explotación."},{"slide_number":79,"block_number":6,"lesson_ordinal":10,"segment_position":7,"segment_id":"6a8ae087-a744-5845-8eaa-72161e335e94","slide_id":"a0eec77c-e60f-5b80-b44b-55bef4e5c8c6","note_id":"9463d6d1-300a-591d-9f4b-a9fb00be0d03","title":"Alcance de la formación del grupo 5.3.a y evidencias documentales","narration_text":"El criterio debe ser comprensible para quien ejecuta, para quien supervisa y para el turno siguiente.\n\nConviene comprobar lo siguiente: Grupo 5.3.a: técnicos titulados que trabajan en actividades extractivas de interior. Las 20 horas son una propuesta curricular de InmínerCampus; no se presenta como ET 2003-1-10 ni como homologación no acreditada. Reciclaje general de 5 horas, máximo 4 años, y evidencias completas de la formación.\n\nPensemos en una situación de campo. El trabajo empieza dentro de criterio, pero una labor conectada cambia el aire, el agua o la circulación. El equipo debe reconocer el cambio antes de que la condición inicial deje de ser válida.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nPiense también en la persona que no participa directamente, pero puede quedar afectada por aire, agua, tráfico, energía o pérdida de una salida. La evaluación debe incluirla y comprobar que la medida no traslada el riesgo a otra labor. Cuando existe incertidumbre, se amplía la zona de influencia, se conserva el estado seguro y se consulta a la competencia técnica correspondiente.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: formación trazable.","duration_seconds":147,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-079.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-079.png","explanation":"Objetivo\n\nGrupo 5.3.a: técnicos titulados que trabajan en actividades extractivas de interior. Las 20 horas son una propuesta curricular de InmínerCampus; no se presenta como ET 2003-1-10 ni como homologación no acreditada. Reciclaje general de 5 horas, máximo 4 años, y evidencias completas de la formación.\n\nExplicación detallada\n\n\n\nLectura guiada de la diapositiva\n\n• Grupo 5.3.a: técnicos titulados que trabajan en actividades extractivas de interior. Las 20 horas son una propuesta curricular de InmínerCampus; no se presenta como ET 2003-1-10 ni como homologación no acreditada. Reciclaje general de 5 horas, máximo 4 años, y evidencias completas de la formación.\n\nAplicación práctica\n\nEl trabajo empieza dentro de criterio, pero una labor conectada cambia el aire, el agua o la circulación. El equipo debe reconocer el cambio antes de que la condición inicial deje de ser válida.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nFormación trazable","key_points":["Grupo 5.3.a: técnicos titulados que trabajan en actividades extractivas de interior. Las 20 horas son una propuesta curricular de InmínerCampus; no se presenta como ET 2003-1-10 ni como homologación no acreditada. Reciclaje general de 5 horas, máximo 4 años, y evidencias completas de la formación.","Formación trazable"],"stop_criterion":"Formación trazable","source_pages":"Bloque 6 · diapositiva 79","question":"Respecto a «Alcance de la formación del grupo 5.3.a y evidencias documentales», ¿qué criterio operativo es correcto?","correct_option":"Formación trazable: Grupo 5.3.a: técnicos titulados que trabajan en actividades extractivas de interior. Las 20 horas son una propuesta curricular de InmínerCampus; no se presenta como ET 2003-1-10 ni como homologación no acreditada. Reciclaje general de 5 horas, máximo 4 años, y evidencias completas de la formación.","question_explanation":"Grupo 5.3.a: técnicos titulados que trabajan en actividades extractivas de interior. Las 20 horas son una propuesta curricular de InmínerCampus; no se presenta como ET 2003-1-10 ni como homologación no acreditada. Reciclaje general de 5 horas, máximo 4 años, y evidencias completas de la formación."},{"slide_number":80,"block_number":6,"lesson_ordinal":10,"segment_position":8,"segment_id":"a99b4997-c71d-5669-9c89-8b80529579b7","slide_id":"e12ff519-afc9-5bb1-8217-f77f6fcb0b87","note_id":"9f034115-cd4d-5550-ba90-7c09dd25dcda","title":"Lista final de comprobación antes de autorizar, continuar o reabrir un trabajo","narration_text":"Cada autorización necesita una condición de partida y una señal inequívoca de pérdida de control.\n\nEl punto de partida es: Tarea, zona, responsables, presencia, rutas y salidas autorizados. Ventilación, atmósfera, terreno, agua, bombeo, comunicaciones, equipos y energías verificados. Permisos, interferencias, emergencia y criterio de parada conocidos; si falta una condición crítica, detener y corregir.\n\nPensemos en una situación de campo. Antes de reabrir, todo parece preparado, pero falta una vía de comunicación fiable; una sola condición crítica ausente mantiene el trabajo detenido.\n\nLa coordinación debe comprobar simultaneidad en espacio, tiempo y sistemas conectados. Cada permiso puede ser correcto por separado y, aun así, resultar incompatible con otro. Por eso se definen límites, energías, exclusiones, comunicaciones, responsable común y entrega formal. Si cambian las condiciones que sustentaban la autorización, el permiso deja de ser válido hasta que la situación se reevalúe y quede nuevamente controlada.\n\nSi esta condición cambiara durante el turno, la pregunta útil no sería si todavía puede terminarse la tarea, sino qué barrera ha perdido validez. Conviene pedir a la persona ejecutante que señale el peligro, la trayectoria, el control crítico y la señal de fallo. Si no puede hacerlo con claridad, falta información o preparación. La comunicación debe incluir lugar, hora, zona afectada, medida adoptada y requisito de reapertura.\n\nPara llevarlo al puesto, identifique la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para reabrir. Si cualquiera de estos elementos falta, la autorización todavía no está completa.\n\nLa decisión se cierra indicando quién verifica el resultado y qué evidencia permite continuar sin ambigüedad. La idea que debe conservarse es sencilla: autorizar solo con evidencias.","duration_seconds":140,"audio_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/audio/slide-080.mp3","image_storage_path":"99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de/tecnicos-titulados-actividades-extractivas-interior/v1-2026-11/slides/slide-080.png","explanation":"Objetivo\n\nTarea, zona, responsables, presencia, rutas y salidas autorizados. Ventilación, atmósfera, terreno, agua, bombeo, comunicaciones, equipos y energías verificados. Permisos, interferencias, emergencia y criterio de parada conocidos; si falta una condición crítica, detener y corregir.\n\nExplicación detallada\n\n\n\nLectura guiada de la diapositiva\n\n• Tarea, zona, responsables, presencia, rutas y salidas autorizados. Ventilación, atmósfera, terreno, agua, bombeo, comunicaciones, equipos y energías verificados. Permisos, interferencias, emergencia y criterio de parada conocidos; si falta una condición crítica, detener y corregir.\n\nAplicación práctica\n\nAntes de reabrir, todo parece preparado, pero falta una vía de comunicación fiable; una sola condición crítica ausente mantiene el trabajo detenido.\n\nComprobación antes de continuar\n\nIdentifica la condición de partida, la señal de pérdida de control, la persona responsable y la evidencia necesaria para autorizar o reabrir. Si falta un dato crítico, conserva el estado seguro y eleva la decisión.\n\nIdea clave\n\nAutorizar solo con evidencias","key_points":["Tarea, zona, responsables, presencia, rutas y salidas autorizados. Ventilación, atmósfera, terreno, agua, bombeo, comunicaciones, equipos y energías verificados. Permisos, interferencias, emergencia y criterio de parada conocidos; si falta una condición crítica, detener y corregir.","Autorizar solo con evidencias"],"stop_criterion":"Autorizar solo con evidencias","source_pages":"Bloque 6 · diapositiva 80","question":"Respecto a «Lista final de comprobación antes de autorizar, continuar o reabrir un trabajo», ¿qué criterio operativo es correcto?","correct_option":"Autorizar solo con evidencias: Tarea, zona, responsables, presencia, rutas y salidas autorizados. Ventilación, atmósfera, terreno, agua, bombeo, comunicaciones, equipos y energías verificados. Permisos, interferencias, emergencia y criterio de parada conocidos; si falta una condición crítica, detener y corregir.","question_explanation":"Tarea, zona, responsables, presencia, rutas y salidas autorizados. Ventilación, atmósfera, terreno, agua, bombeo, comunicaciones, equipos y energías verificados. Permisos, interferencias, emergencia y criterio de parada conocidos; si falta una condición crítica, detener y corregir."}]$interior_units$::jsonb) as unit(
  slide_number integer,
  block_number integer,
  lesson_ordinal integer,
  segment_position integer,
  segment_id uuid,
  slide_id uuid,
  note_id uuid,
  title text,
  narration_text text,
  duration_seconds integer,
