insert into public.questions (
  id, question_bank_id, prompt, type, explanation, points, active,
  lesson_audio_segment_id
)
values
  ('c4a4668d-cf48-5dab-95ae-e36ed63d1bc1'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «Identificación, destinatarios y alcance del curso», ¿qué criterio operativo es correcto?', 'single_choice', 'Formación preventiva para técnicos titulados que trabajan en explotaciones subterráneas. Programa de InmínerCampus, edición 1.0, adaptado al proyecto, al Documento sobre Seguridad y Salud y a las DIS de cada centro. El material sirve de apoyo y debe contextualizarse en la explotación concreta.', 1, true, null),
  ('55a808e2-42aa-53ab-9929-fddfd8cf5a4c'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «Grupo 5.3.a, duración y límites de la formación», ¿qué criterio operativo es correcto?', 'single_choice', 'Itinerario correspondiente al grupo 5.3.a de la ITC 02.1.02. Duración curricular propuesta por InmínerCampus: 20 horas. Modalidad reglamentaria presencial; el soporte digital es complementario. No concede nombramientos ni habilitaciones de director facultativo, vigilante, artillero o rescatista.', 1, true, null),
  ('faa89bf0-6081-5062-9d76-b55236c254d3'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «Resultados de aprendizaje», ¿qué criterio operativo es correcto?', 'single_choice', 'Describir una labor subterránea y explicar cómo el método y la secuencia modifican el riesgo. Supervisar terreno, ventilación, atmósfera, agua, transporte, energías y emergencias. Definir parada, aislamiento, evacuación, reapertura y coordinación con trazabilidad.', 1, true, null),
  ('f2665c80-867d-5f68-b012-e86709ba9e1a'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «La explotación subterránea como sistema conectado», ¿qué criterio operativo es correcto?', 'single_choice', 'Desarrollo, preparación, producción, transporte, servicios y emergencia comparten infraestructuras. Una decisión local puede alterar ventilación, evacuación, estabilidad o circulación lejos del punto de trabajo. La evaluación debe abarcar toda la zona de influencia.', 1, true, null),
  ('093a7c8b-d4af-5b62-8239-4e2e0c7c4c82'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «Fases del ciclo minero subterráneo», ¿qué criterio operativo es correcto?', 'single_choice', 'Desarrollo y arranque: cambios de ventilación, gases, proyecciones y barrenos fallidos. Saneo y sostenimiento: evitar exposición bajo techo no verificado. Carga, transporte, relleno y servicios: interacción vehículo-peatón, agua, aire y energía.', 1, true, null),
  ('41642c33-67e7-5c1d-a89c-21e409de129f'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «Estados no productivos que también generan riesgo», ¿qué criterio operativo es correcto?', 'single_choice', 'Espera, limpieza, desatasco, inspección, prueba y mantenimiento tienen peligros propios. El cambio de turno o una parada de ventilación puede degradar barreras. Tras una incidencia, hay que verificar nuevamente las condiciones antes de recuperar la actividad.', 1, true, null),
  ('e4e149bb-bd65-5a82-895b-ad03be4fed89'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «Métodos de explotación y geometrías principales», ¿qué criterio operativo es correcto?', 'single_choice', 'Cámaras y pilares, corte y relleno, subniveles, hundimiento y tajo largo presentan geometrías distintas. Importan luces, alturas, pilares, relleno, secuencia y excavaciones próximas. Cambiar el orden de extracción puede sobrecargar pilares o cerrar una ruta prevista.', 1, true, null),
  ('569f1f46-61f5-5adf-89f3-a2aa5731e133'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «Propagación de riesgos entre labores», ¿qué criterio operativo es correcto?', 'single_choice', 'Terreno, aire, agua y tráfico conectan labores diferentes. Un retorno restringido altera varios frentes; una labor antigua cambia agua, terreno y atmósfera. Evaluar siempre los efectos aguas abajo y en las rutas de evacuación.', 1, true, null),
  ('38651d3c-ce41-59e3-aea9-85994248cc6e'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «Funciones técnicas, responsabilidades y límites de autoridad», ¿qué criterio operativo es correcto?', 'single_choice', 'Empresario, dirección facultativa, equipo facultativo, vigilante, técnico, operador y artillero tienen funciones distintas. El título y este curso no conceden por sí solos todos los roles. Actuar dentro del nombramiento, competencia y autoridad asignados.', 1, true, null),
  ('3c678e05-4ffc-5c4a-be49-a7fc8fd75bc5'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Respecto a «Ficha para definir un trabajo y caso del avance aparentemente rutinario», ¿qué criterio operativo es correcto?', 'single_choice', 'Definir objeto, ubicación, terreno, secuencia, personas, equipos, ventilación, evacuación, interferencias y reapertura. Caso: avance repetido, labor antigua próxima y retorno reducido. Detener la preparación hasta verificar planos, sondeos, ventilación y secuencia.', 1, true, null),
  ('493adeee-83b4-507f-bd8c-f254e706e766'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Riesgo dinámico en minería subterránea», ¿qué criterio operativo es correcto?', 'single_choice', 'La supervisión confirma que las barreras previstas siguen presentes y funcionan. El riesgo combina probabilidad, exposición y consecuencia. Terreno, atmósfera, agua o equipos pueden cambiar dentro del mismo turno.', 1, true, null),
  ('659bc976-7388-5a08-b971-a08280899195'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Peligro, exposición, consecuencia y barrera», ¿qué criterio operativo es correcto?', 'single_choice', 'Peligro: fuente con capacidad de causar daño. Exposición: quién entra, dónde y durante cuánto tiempo. Consecuencia: daño posible. Barrera: control que evita el suceso o limita el resultado.', 1, true, null),
  ('2ab2bdaa-a805-5d6a-ae65-d51b585fb33d'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Evidencias de que una barrera funciona», ¿qué criterio operativo es correcto?', 'single_choice', 'Inspección del contorno, lectura del detector o prueba de comunicación. Registro con hora, ubicación, condiciones y autorización de reentrada. Una firma sin observación, medición o prueba no demuestra eficacia.', 1, true, null),
  ('ecafcbf1-aa2f-5d56-b199-57d2ba9e3a5b'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Jerarquía de medidas preventivas», ¿qué criterio operativo es correcto?', 'single_choice', 'Priorizar diseño e ingeniería: método húmedo, captación, ventilación y separación. Después, organización: limitar presencia, secuenciar y prohibir prácticas inseguras. El EPI completa las medidas y nunca compensa ventilación o sostenimiento deficientes.', 1, true, null),
  ('3347d0b0-b4bf-53f7-a2f7-271bae8bb408'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Autoridad de parada», ¿qué criterio operativo es correcto?', 'single_choice', 'Parar ante deformación no prevista del terreno o del sostenimiento. Parar por pérdida, inversión o reducción no autorizada de ventilación. Parar ante alarma de gas, humo, agua anómala, fallo crítico, pérdida de salida o trabajo fuera de autorización.', 1, true, null),
  ('95fc3f8d-93c9-57fc-8965-f358913cd8dc'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Secuencia de parada, aislamiento, comunicación y verificación», ¿qué criterio operativo es correcto?', 'single_choice', 'Detener la tarea y retirar a las personas. Aislar energía o área; comunicar hechos, ubicación, hora y medidas. Evaluar, corregir, verificar y autorizar la reapertura dejando registro.', 1, true, null),
  ('2af4e42e-3364-5e29-8dd4-409e3b1056b3'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «El macizo rocoso y sus discontinuidades», ¿qué criterio operativo es correcto?', 'single_choice', 'La excavación elimina confinamiento y redistribuye tensiones. Litología, fallas, juntas, estratificación, agua y labores cercanas condicionan el comportamiento. Una sección estable puede volverse inestable al cruzar una discontinuidad.', 1, true, null),
  ('44d808f3-ee60-53b8-9a93-d60300e45dc7'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Señales precursoras de inestabilidad», ¿qué criterio operativo es correcto?', 'single_choice', 'Roca fresca en el piso, chasquidos, lajas, fisuras nuevas o pernos rotos. Malla abombada, convergencia, levantamiento y agua nueva o turbia. Respuesta: excluir, marcar, medir y solicitar evaluación competente.', 1, true, null),
  ('68c2c16f-773f-5e30-aa38-f4067bb55ce1'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Factores que modifican la estabilidad», ¿qué criterio operativo es correcto?', 'single_choice', 'Orientación de discontinuidades, alteración, esfuerzos y agua. Método, secuencia, dimensiones y excavaciones próximas. Comparar continuamente la realidad observada con el modelo y el diseño.', 1, true, null),
  ('c03fe65e-2b9c-5721-b2b0-cef7145fc97e'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Diseño y función del sostenimiento», ¿qué criterio operativo es correcto?', 'single_choice', 'Bulones, cables, malla, hormigón proyectado, cerchas, relleno o soporte hidráulico. Se selecciona según mecanismo de fallo, vida de la labor, deformación admisible y secuencia. Debe definir patrón, capacidad, ensayos y tratamiento de desviaciones.', 1, true, null),
  ('11a8b1c9-7b34-5fd8-85e8-6271149dc27a'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Instalación y comprobación del sostenimiento», ¿qué criterio operativo es correcto?', 'single_choice', 'Bulón o cable: taladro, longitud, orientación, resina o lechada, placa y tensión. Malla y hormigón: solape, fijación, espesor, adherencia, drenaje y curado. Cerchas: apoyo, alineación y arriostramiento; revisar deterioro y carga en servicio.', 1, true, null),
  ('1298dd6f-19a1-5b9f-983a-d16cce870af7'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Saneo e inspección del terreno», ¿qué criterio operativo es correcto?', 'single_choice', 'Delimitar y evitar exposición bajo roca suelta. Inspeccionar desde terreno confirmado seguro y sanear fuera de la trayectoria con retirada disponible. Sostener en la secuencia definida, comprobar calidad y registrar anomalías.', 1, true, null),
  ('c3be420a-0b04-5e46-b6b4-2d7cc2421f2f'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Caso práctico de control geotécnico», ¿qué criterio operativo es correcto?', 'single_choice', 'Una malla abombada indica que ha retenido carga, aunque no haya roca en el suelo. Su capacidad residual no está demostrada. Excluir la zona, evaluar la extensión y descargar o reforzar mediante un método aprobado antes de reabrir.', 1, true, null),
  ('515c4c2c-2796-59a2-9c99-f99f2225e0d6'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Objetivos de la ventilación subterránea», ¿qué criterio operativo es correcto?', 'single_choice', 'Aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal total no demuestra que el frente reciba aire limpio. También debe comprobarse que el retorno sea seguro y no recircule contaminantes.', 1, true, null),
  ('61762290-4b5a-58eb-b715-899dc0d0ce69'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Circuito principal de ventilación», ¿qué criterio operativo es correcto?', 'single_choice', 'Entradas, retornos, ventiladores, puertas, esclusas, tabiques, reguladores, cruces y sellados. Abrir, cerrar u obstruir un elemento redistribuye el aire. Los planos deben reflejar el circuito real y todo cambio temporal debe diseñarse, comunicarse y comprobarse.', 1, true, null),
  ('d1fbe220-c0fa-5b42-a1f3-96df3deef89a'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Ventilación secundaria y conductos», ¿qué criterio operativo es correcto?', 'single_choice', 'El ventilador auxiliar lleva aire hasta el frente ciego. Fallos: parada, giro incorrecto, recirculación, mala ubicación o distancia excesiva. El conducto puede romperse, separarse, aplastarse, fugar o terminar lejos del frente.', 1, true, null),
  ('fb72f1a3-3ce4-51c9-b261-0c663943665a'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Caudal, velocidad y distribución del aire», ¿qué criterio operativo es correcto?', 'single_choice', 'Medir con método y sección adecuados y registrar ubicación, hora y estado productivo. Comparar con el criterio definido en el DSS o la DIS. Caudal en la galería no equivale a aire limpio en la zona respiratoria.', 1, true, null),
  ('4ee4bc46-46f3-57f7-b727-abe77e43b257'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Recirculación, fugas y cortocircuitos», ¿qué criterio operativo es correcto?', 'single_choice', 'Un cortocircuito lleva aire de entrada a retorno sin barrer la zona prevista. Puertas, tabiques, sellados y conductos dañados provocan fugas. La recirculación devuelve contaminantes: corregir la causa y repetir la medición.', 1, true, null),
  ('34417e5f-f97c-5953-858f-fd9bce15b8e3'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Comprobación de la ventilación en un frente», ¿qué criterio operativo es correcto?', 'single_choice', 'Confirmar el sistema en servicio y sin recirculación. Medir caudal o velocidad, revisar conducto y medir oxígeno y contaminantes en puntos representativos. Aplicar el criterio de parada y reentrada cuando el resultado esté fuera de rango.', 1, true, null),
  ('99ac5118-0433-56e7-b7fe-b03433291819'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Fallos de ventilación y condiciones de parada», ¿qué criterio operativo es correcto?', 'single_choice', 'Parar ante pérdida, inversión, reducción no autorizada, recirculación, alarma o imposibilidad de medir. Retirar exposición, aislar y corregir. Verificar condiciones representativas antes de autorizar la reentrada.', 1, true, null),
  ('6752ebbc-bed5-5c5e-8815-f64300a10e9c'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Atmósferas peligrosas y deficiencia de oxígeno», ¿qué criterio operativo es correcto?', 'single_choice', 'Los gases no se detectan de forma fiable por olor ni por síntomas. Con carácter general, el oxígeno no debe ser inferior al 19 % en volumen. El déficit puede reducir juicio y consciencia; deben prevalecer los criterios más restrictivos.', 1, true, null),
  ('22a106b3-485b-50d9-8d34-65f807931cbf'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Gases tóxicos y valores de referencia», ¿qué criterio operativo es correcto?', 'single_choice', 'CO: 25 ppm VLA-ED y 100 ppm VLA-EC. CO2: 5.000 y 12.500 ppm. SO2: 0,5 y 1 ppm. H2S: 5 y 10 ppm. NO: 25 y 30 ppm. NO2: 3 y 5 ppm. Considerar mezclas, picos, duración, lugar y condiciones; alcanzar el límite no es un objetivo.', 1, true, null),
  ('b6759d34-f7f2-5ab9-9b34-4b30d020efab'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Instrumentos, calibración y prueba funcional», ¿qué criterio operativo es correcto?', 'single_choice', 'Comprobar identificación, rango, sensores, calibración, batería y respuesta funcional. Configurar el equipo para los gases previsibles y medir a distancia si existe sospecha. Retirar instrumentos fuera de calibración, saturados, incoherentes o que fallen la prueba.', 1, true, null),
  ('e9124753-12e4-5f8a-81bc-2811ecc61912'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Estrategia de medición y registro», ¿qué criterio operativo es correcto?', 'single_choice', 'Barrer alturas, huecos y zonas respiratorias según geometría y comportamiento del gas. Una lectura puntual no equivale a exposición diaria ni demuestra ausencia permanente. Registrar equipo, lugar, hora, condiciones, lectura, persona y decisión.', 1, true, null),
  ('173b6714-9637-594d-a234-b6b010680347'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Metano y atmósferas explosivas», ¿qué criterio operativo es correcto?', 'single_choice', 'Aplicable a minas de carbón y labores con riesgo de explosión. ITC 05.0.02: 0,80 % en retornos generales; 1,50 % en restantes labores; 1,00 % en retornos de talleres electrificados. Aplicar alarmas, desconexiones y criterios más restrictivos del DSS o la DIS.', 1, true, null),
  ('11c55645-2e30-5644-a636-bcf7329787e6'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Polvo respirable y sílice cristalina», ¿qué criterio operativo es correcto?', 'single_choice', 'Perforación, voladura, carga, trituración, transferencia y tráfico generan fracción respirable. VLA-ED: 3 mg/m3 de polvo respirable y 0,05 mg/m3 de sílice cristalina respirable. Controlar por diseño, captación, supresión, ventilación, organización y finalmente EPI.', 1, true, null),
  ('2ba6c7a2-6441-5003-997d-778e44d007c3'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Emisiones diésel, ruido, vibraciones, calor e iluminación», ¿qué criterio operativo es correcto?', 'single_choice', 'Diésel: bajas emisiones, mantenimiento, ventilación y reducción de ralentí. Ruido y vibración: selección, encapsulado, mantenimiento, distancia y tiempo. Calor e iluminación: ventilación, hidratación, aclimatación, pausas y luz suficiente sin deslumbrar.', 1, true, null),
  ('bf8a0447-9f83-55c4-ba5c-fb0b56185bda'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Incendio, humo y trabajos en caliente», ¿qué criterio operativo es correcto?', 'single_choice', 'Cintas, neumáticos, aceites, combustible, madera, cables y baterías aportan carga de fuego. La ventilación transporta humo y calor; las decisiones siguen el plan de emergencia. Trabajo en caliente: permiso, atmósfera controlada, combustibles retirados, extinción, vigilancia e inspección posterior.', 1, true, null),
  ('9b8d7927-b31e-5fb0-9102-ba07191dccf9'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Agua, inundación, labores antiguas, accesos y transporte», ¿qué criterio operativo es correcto?', 'single_choice', 'El agua erosiona, oculta huecos, vence barreras, afecta la electricidad y corta rutas. Ante sospecha: sondeos, solapes, control de presión, bombeo redundante, alarmas y ruta de descarga. Mantener salidas, control de presencia y un plan de tráfico con segregación.', 1, true, null),
  ('8b74258f-0f87-5eb2-8f0f-0565ed27a046'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Respecto a «Perforación, voladura, reentrada, evacuación y emergencias», ¿qué criterio operativo es correcto?', 'single_choice', 'Explosivos solo por personal autorizado y con exclusiones e interferencias controladas. Tras el disparo: espera, ventilación, medición, terreno, sostenimiento, servicios y fallidos. Evacuar, contar personas y no improvisar rescates en atmósfera desconocida o terreno inestable.', 1, true, null),
  ('a16d8005-9dfb-5893-b655-aaa4f8765b34'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Equipos móviles y riesgos críticos», ¿qué criterio operativo es correcto?', 'single_choice', 'Comprobar frenos, dirección, neumáticos, luces, alarmas, cámara, extinción, cinturón y fugas. Controlar puntos ciegos, pendientes, radios de giro, prioridad y segregación. Un fallo crítico retira el equipo de servicio.', 1, true, null),
  ('e98d5be3-f776-5e19-8d35-3bd0e96407dc'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Perforadoras y equipos de avance», ¿qué criterio operativo es correcto?', 'single_choice', 'Comprobar estabilidad, apoyos, mangueras, barras, protecciones y captación de polvo. Mantener al operador fuera de trayectorias de proyección, atrapamiento y latigazo. No acceder a la zona peligrosa mientras exista energía disponible.', 1, true, null),
  ('48a9f836-aad9-5647-a3e9-626b115a33b4'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Cintas, trituradores y puntos de atrapamiento», ¿qué criterio operativo es correcto?', 'single_choice', 'Revisar resguardos, enclavamientos, paradas, accesos, derrames, atascos y caída de material. Un atasco no se libera mientras exista energía. Rozamiento, humo, protección anulada o parada inaccesible exigen detener y consignar.', 1, true, null),
  ('729ee46a-0c98-55f9-bf3d-1b96b913314f'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Bombas, ventiladores y equipos de izado», ¿qué criterio operativo es correcto?', 'single_choice', 'Bomba: base, acoplamientos, tuberías, válvulas, presión, cebado y alimentación. Ventilador: anclaje, resguardo, sentido, vibración, conducto, protección y alarma. Izado: capacidad, identificación, accesorios, pestillos, apoyos, recorrido y exclusión.', 1, true, null),
  ('ef2a31f4-edf8-5758-962d-84a30d68e497'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Inspección previa de los equipos», ¿qué criterio operativo es correcto?', 'single_choice', 'Identificar el equipo, revisar estado físico, protecciones, fugas y documentación. Probar funciones críticas desde una posición segura. Comunicar defectos, inmovilizar y etiquetar cuando afecten a la seguridad.', 1, true, null),
  ('857d88d6-671c-5238-9f71-69ec3afeb05d'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Identificación de energías peligrosas», ¿qué criterio operativo es correcto?', 'single_choice', 'Eléctrica, hidráulica, neumática, mecánica, térmica, química, gravedad y presión almacenada. Incluir alimentaciones remotas, energías cruzadas y equipos aguas arriba o abajo. Un mando apagado no demuestra ausencia de energía.', 1, true, null),
  ('ef064ed2-6147-5241-b27a-a4d921348a6c'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Preparación, parada y aislamiento», ¿qué criterio operativo es correcto?', 'single_choice', 'Definir alcance, comunicar a afectados e identificar todas las energías. Detener mediante el mando normal y separar físicamente con seccionadores o válvulas. Evitar realimentaciones; una parada de emergencia no equivale a aislamiento.', 1, true, null),
  ('913481ba-4ccb-5da6-95f0-0f36784a1b83'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Bloqueo, etiquetado y control de llaves», ¿qué criterio operativo es correcto?', 'single_choice', 'Cada persona expuesta mantiene control de su bloqueo. El bloqueo grupal requiere caja o sistema trazable; la etiqueta informa pero no sustituye el bloqueo. Los cambios de turno deben transferirse sin huecos de protección.', 1, true, null),
  ('b085ec3e-53cf-59be-ac90-8ac25f53c340'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Eliminación de energía residual», ¿qué criterio operativo es correcto?', 'single_choice', 'Descargar acumuladores, purgar líneas, comprobar presión cero y descargar condensadores. Bloquear partes elevadas, inmovilizar articulaciones, calzar ruedas y asegurar muelles o cargas. Verificar la estabilidad después de eliminar o contener la energía.', 1, true, null),
  ('a315fe38-7d76-5d47-9f07-c7a1903f3adb'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Verificación de ausencia de energía y restitución», ¿qué criterio operativo es correcto?', 'single_choice', 'Intentar arranque controlado y medir cero tensión o presión con instrumento comprobado. Antes de restituir, revisar montaje, resguardos, herramientas, personas y zona. Reenergizar solo con autorización, comunicación y prueba funcional segura.', 1, true, null),
  ('934d0522-95cc-55e2-81db-247fa64f5c50'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Selección, ajuste y compatibilidad de los EPI», ¿qué criterio operativo es correcto?', 'single_choice', 'Seleccionar según riesgo, tarea, ambiente, usuario y tiempo de uso. Verificar talla, ajuste, estado, vida útil, limpieza, almacenamiento y mantenimiento. Comprobar compatibilidad entre casco, lámpara, gafas, protección respiratoria, auditiva, arnés y comunicación.', 1, true, null),
  ('abbf3da4-8f0e-59a4-9600-99327969724e'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Respecto a «Protección respiratoria, autorrescatadores, herramientas, plataformas y rescate», ¿qué criterio operativo es correcto?', 'single_choice', 'El filtro y ajuste deben corresponder al contaminante; los equipos filtrantes no sirven con oxígeno insuficiente. El autorrescatador facilita el escape y no sustituye una ruta viable. Retirar herramientas defectuosas y definir acceso, anclajes, comunicación y rescate antes de trabajos complejos.', 1, true, null),
  ('98b79df2-83bd-583f-86eb-454b6128f74b'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Finalidad de una inspección preventiva», ¿qué criterio operativo es correcto?', 'single_choice', 'Detectar desviaciones antes de que produzcan daño. Verificar que las barreras existen, funcionan y se adaptan a los cambios. Asignar acciones, responsables, plazos y criterios de cierre; marcar una lista no basta.', 1, true, null),
  ('18c569d7-53ac-5ae5-b721-4dfd03fca63a'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Orden recomendado de inspección», ¿qué criterio operativo es correcto?', 'single_choice', 'Primero presencia, accesos y evacuación; después atmósfera y ventilación. Continuar con terreno, sostenimiento, agua, transporte y equipos. Revisar tareas, energías, permisos e interferencias sin entrar en zonas no verificadas.', 1, true, null),
  ('000be05f-c91f-557b-b93c-5edb240dae3a'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Frecuencia basada en el riesgo», ¿qué criterio operativo es correcto?', 'single_choice', 'Antes de turno o entrada y durante operaciones críticas. Después de voladura, parada, incidente, lluvia, sismo, incendio, alarma o cambio. A mayor posibilidad de cambio, gravedad o pérdida de barrera, mayor frecuencia.', 1, true, null),
  ('d544940b-b759-5758-b923-eac2f5ab519b'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Inspecciones antes de entrar y después de una parada», ¿qué criterio operativo es correcto?', 'single_choice', 'Confirmar autorización, presencia e información del turno anterior. Restablecer servicios desde zona segura y medir atmósfera antes de avanzar. Inspeccionar terreno, agua, rutas, equipos y comunicaciones; corregir y verificar de nuevo.', 1, true, null),
  ('c468fc6c-e716-5b4f-a95f-a73228edd0ce'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Inspecciones posteriores a una voladura», ¿qué criterio operativo es correcto?', 'single_choice', 'Respetar la exclusión, ventilar y comprobar la atmósfera. Revisar barrenos fallidos, terreno, sostenimiento, servicios, polvo, humos y accesos. La persona competente verifica, registra y entrega la zona antes de la reentrada.', 1, true, null),
  ('4830aa5a-aceb-5650-9245-3aa9876390bd'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Mediciones y evidencias objetivas», ¿qué criterio operativo es correcto?', 'single_choice', 'Indicar punto, método, instrumento, fecha, hora y condiciones de operación. Registrar resultado, criterio de aceptación, persona y decisión. La fotografía ayuda, pero no sustituye mediciones o pruebas necesarias.', 1, true, null),
  ('69229c86-e826-5d66-9b15-42c1bee185b0'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Cómo redactar un hallazgo útil», ¿qué criterio operativo es correcto?', 'single_choice', 'Ubicación exacta, condición observada, medida o fotografía y personas expuestas. Acción inmediata, responsable, plazo y criterio de cierre. Redactar hechos, distinguir corrección inmediata y acción contra la recurrencia.', 1, true, null),
  ('03404694-d204-5750-b6bf-835ab7ae2f21'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Hallazgos deficientes y hallazgos trazables», ¿qué criterio operativo es correcto?', 'single_choice', 'Evitar descripciones vagas como «Techo mal», «Ventilación baja» o «Arreglar frenos». Precisar labor, evidencia, valor medido, exposición y medida adoptada. Ejemplo: equipo identificado, prueba no conforme, fuera de servicio y llave controlada.', 1, true, null),
  ('003644e5-d484-5bdc-9ce7-b869c4a2e324'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Información necesaria en una entrega entre turnos», ¿qué criterio operativo es correcto?', 'single_choice', 'Personas y equipos dentro; cierres, barreras y accesos restringidos. Estado de ventilación, bombeo, energía, comunicaciones, salidas, voladuras y permisos. Cambios y acciones pendientes con responsable, plazo y autoridad de cierre.', 1, true, null),
  ('896e3b16-bc35-57c5-9815-968da8165516'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Desencadenantes de la gestión del cambio», ¿qué criterio operativo es correcto?', 'single_choice', 'Geología, deformación, ventilación, agua, equipos, método o secuencia. Organización, contratistas, horarios, rutas, energía o emergencia. Describir, evaluar, actualizar documentos, controlar, formar, verificar y revisar.', 1, true, null),
  ('ac62f26c-ffeb-5295-829d-3bb314b90100'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Cierre temporal de una labor», ¿qué criterio operativo es correcto?', 'single_choice', 'Definir alcance y responsable; retirar o asegurar personas, explosivos, combustibles y equipos. Aislar energías, decidir ventilación y bombeo e instalar barreras y señalización. Conservar drenaje, estabilidad y vigilancia; registrar requisitos de reapertura.', 1, true, null),
  ('4cef9faf-12e5-53f7-abda-ca2b39e2ef42'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Respecto a «Secuencia de reapertura y caso de una labor parada», ¿qué criterio operativo es correcto?', 'single_choice', 'Revisar cierre, planos, DSS, DIS, permisos, incidentes y cambios. Restablecer servicios desde zona segura, medir atmósfera e inspeccionar progresivamente. Corregir, repetir pruebas y autorizar con restricciones documentadas; no usar personas como prueba.', 1, true, null),
  ('250b9790-3404-5e60-a040-c5a5c6931d69'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, 'Respecto a «Interferencias visibles y remotas», ¿qué criterio operativo es correcto?', 'single_choice', 'Dos equipos pueden interferir en un cruce, pero también a distancia mediante aire, energía, agua o material. Una actividad puede afectar la circulación o eliminar una salida. Evaluar simultaneidad en espacio, tiempo y sistemas conectados.', 1, true, null),
  ('ae94d166-cb3d-5c2a-947b-a4f6060c7c28'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, 'Respecto a «Matriz de actividades simultáneas», ¿qué criterio operativo es correcto?', 'single_choice', 'Cruzar actividades y revisar acceso, atmósfera, energía, estructura, comunicación y emergencia. Ejemplos: voladura-mantenimiento, diésel-peatón, nivel superior-tránsito inferior. Incluir ventilación-frentes conectados, bombeo-electricidad e izado-trabajo bajo carga.', 1, true, null),
  ('99b5bd4b-b6c2-5454-9b8c-874c2b1fbef3'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, 'Respecto a «Interferencias entre voladura, mantenimiento y producción», ¿qué criterio operativo es correcto?', 'single_choice', 'Cada permiso puede ser correcto y, sin embargo, la secuencia global ser incompatible. Impedir energizar, disparar, circular o reabrir mientras otra actividad mantenga personas expuestas. Definir ventanas, exclusiones, responsables, comunicaciones y entrega de la instalación.', 1, true, null),
  ('d4ea2d9f-4959-5b54-87f0-05f18f6f4b22'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, 'Respecto a «Tráfico, ventilación, bombeo e izado», ¿qué criterio operativo es correcto?', 'single_choice', 'Una obstrucción puede eliminar una salida y un vehículo puede dañar conductos. El bombeo puede inundar aguas abajo o afectar a otras energías. El izado crea zonas de caída: coordinar rutas, servicios y criterios de parada.', 1, true, null),
  ('3363f4d5-edfa-5c4d-ae15-64595968ffb4'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, 'Respecto a «Coordinación de actividades empresariales», ¿qué criterio operativo es correcto?', 'single_choice', 'Intercambiar riesgos específicos y cambios; comprobar competencia, autorizaciones, equipos y DIS. Nombrar interlocutores y unificar tráfico, alarma, presencia y permisos. Coordinar secuencia y entrega, supervisar y corregir; los documentos no sustituyen el campo.', 1, true, null),
  ('7460b15e-4656-5a4a-a662-e9bb9d476ac7'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, 'Respecto a «Permisos de trabajo y condiciones mínimas», ¿qué criterio operativo es correcto?', 'single_choice', 'Aplicables a trabajos en caliente, eléctricos, izado, altura, accesos complejos y reentrada. Identificar alcance, lugar, vigencia, personas, aislamientos, mediciones e interferencias. Incluir vigilancia, emergencia y cierre; el permiso deja de valer cuando cambian las condiciones.', 1, true, null),
  ('5bc4d9c7-eabd-596f-bbf3-1ca1eec82c04'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, 'Respecto a «Entrega y devolución de áreas e instalaciones», ¿qué criterio operativo es correcto?', 'single_choice', 'Definir límites, energías, personas, equipos, barreras, permisos y defectos pendientes. Comprobar la entrega por ambas partes y dejar registro. La devolución confirma limpieza, montaje, protecciones y preparación para prueba o producción autorizada.', 1, true, null),
  ('63f6c93f-e867-5f20-9ca7-fcaff30eea38'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, 'Respecto a «Caso de permisos incompatibles y control conjunto de energías», ¿qué criterio operativo es correcto?', 'single_choice', 'Mantenimiento bloquea una cinta mientras producción pretende probar el sistema aguas arriba. La interacción puede mover material o reenergizar aunque ambos permisos parezcan correctos. Exigir entrega única, responsable común y cierre de todos los bloqueos antes de probar.', 1, true, null),
  ('1ea0320a-2137-53f7-a978-d43eb5282f1e'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid, 'Respecto a «Jerarquía normativa práctica», ¿qué criterio operativo es correcto?', 'single_choice', 'Ley 31/1995, Real Decreto 39/1997 y Real Decreto 1389/1997. RGNBSM, ITC, proyecto, autorizaciones, DSS y DIS. Procedimientos, permisos e instrucciones: saber qué documento gobierna y cuándo elevar una duda.', 1, true, null),
  ('2c24cecc-f3f0-5e1a-a8fd-f4d13fa0f7cb'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid, 'Respecto a «Ley de Prevención de Riesgos Laborales», ¿qué criterio operativo es correcto?', 'single_choice', 'La Ley 31/1995 establece principios, obligaciones, consulta, formación y protección. La formación debe ser suficiente, adecuada y centrada en el puesto. Debe actualizarse cuando cambien funciones, tecnología o riesgos y no trasladar su coste al trabajador.', 1, true, null),
  ('142fb452-0dce-59b5-af6a-6857ec2d85fe'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid, 'Respecto a «Real Decreto 1389/1997», ¿qué criterio operativo es correcto?', 'single_choice', 'Fija disposiciones mínimas de seguridad y salud en actividades mineras. Exige organización, supervisión, equipos, mantenimiento, instrucciones y control de riesgos especiales. Incluye incendio, explosión, atmósferas nocivas, evacuación, salvamento, comunicación y DSS.', 1, true, null),
  ('3b2da5ee-2a04-5bd6-bb76-0f7b867ea79c'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid, 'Respecto a «Reglamento General de Normas Básicas de Seguridad Minera», ¿qué criterio operativo es correcto?', 'single_choice', 'El Real Decreto 863/1985 establece el marco técnico minero desarrollado por ITC. Las decisiones se integran con proyecto, dirección facultativa, autorizaciones y reglas de la instalación. El marco minero y la prevención general se aplican coordinadamente.', 1, true, null),
  ('63494837-76d3-5e84-a028-96c05b79fbf7'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid, 'Respecto a «ITC aplicables a los trabajos de interior», ¿qué criterio operativo es correcto?', 'single_choice', 'ITC 02.1.02: formación preventiva. ITC 02.0.02: polvo y sílice. ITC 04.7.06: ambiente y gases. ITC 05.0.02: metano en carbón o labores con riesgo. Orden de 22 de marzo de 1988 y normativa de explosivos, incluido el RD 130/2017.', 1, true, null),
  ('1dae9076-0064-5656-a42e-d9405f61426d'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid, 'Respecto a «Documento sobre Seguridad y Salud y Disposiciones Internas de Seguridad», ¿qué criterio operativo es correcto?', 'single_choice', 'El DSS identifica peligros, evaluación, organización, planificación, mantenimiento y emergencia. Debe mantenerse actualizado y revisarse al menos anualmente o ante cambios importantes. Las DIS convierten requisitos en reglas operativas específicas de la explotación.', 1, true, null),
  ('90a08272-14f3-57bb-bce8-98f8525889e1'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid, 'Respecto a «Alcance de la formación del grupo 5.3.a y evidencias documentales», ¿qué criterio operativo es correcto?', 'single_choice', 'Grupo 5.3.a: técnicos titulados que trabajan en actividades extractivas de interior. Las 20 horas son una propuesta curricular de InmínerCampus; no se presenta como ET 2003-1-10 ni como homologación no acreditada. Reciclaje general de 5 horas, máximo 4 años, y evidencias completas de la formación.', 1, true, null),
  ('0b50c2ea-1b71-5704-a2b9-57cf9d5304d2'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid, 'Respecto a «Lista final de comprobación antes de autorizar, continuar o reabrir un trabajo», ¿qué criterio operativo es correcto?', 'single_choice', 'Tarea, zona, responsables, presencia, rutas y salidas autorizados. Ventilación, atmósfera, terreno, agua, bombeo, comunicaciones, equipos y energías verificados. Permisos, interferencias, emergencia y criterio de parada conocidos; si falta una condición crítica, detener y corregir.', 1, true, null)
