insert into public.question_options (id, question_id, position, option_text, is_correct)
values
  ('9619d2d6-485b-577f-a0e6-73a55235881c'::uuid, 'c4a4668d-cf48-5dab-95ae-e36ed63d1bc1'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('a4255557-4249-5d89-9a38-f0820a0c6153'::uuid, 'c4a4668d-cf48-5dab-95ae-e36ed63d1bc1'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('ec01c451-bfe4-58ac-8377-e49ec246db30'::uuid, 'c4a4668d-cf48-5dab-95ae-e36ed63d1bc1'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('286ffa47-a738-557a-a69d-37765b913be3'::uuid, 'c4a4668d-cf48-5dab-95ae-e36ed63d1bc1'::uuid, 4, 'Marco y destinatarios: Formación preventiva para técnicos titulados que trabajan en explotaciones subterráneas. Programa de InmínerCampus, edición 1.0, adaptado al proyecto, al Documento sobre Seguridad y Salud y a las DIS de cada centro. El material sirve de apoyo y debe contextualizarse en la explotación concreta.', true),
  ('e4c09d70-9560-594d-88e3-3ddc3acf0307'::uuid, '55a808e2-42aa-53ab-9929-fddfd8cf5a4c'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('5e4588f1-8ec2-58df-bf11-8323b34ef1ba'::uuid, '55a808e2-42aa-53ab-9929-fddfd8cf5a4c'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('58b18993-e2b6-5507-825b-468160d68fe8'::uuid, '55a808e2-42aa-53ab-9929-fddfd8cf5a4c'::uuid, 3, 'Alcance bien delimitado: Itinerario correspondiente al grupo 5.3.a de la ITC 02.1.02. Duración curricular propuesta por InmínerCampus: 20 horas. Modalidad reglamentaria presencial; el soporte digital es complementario. No concede nombramientos ni habilitaciones de director facultativo, vigilante, artillero o rescatista.', true),
  ('f9bdb83b-489f-5abd-a70f-5faec029f0a8'::uuid, '55a808e2-42aa-53ab-9929-fddfd8cf5a4c'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('576bd907-a227-5783-9561-69c902ead53d'::uuid, 'faa89bf0-6081-5062-9d76-b55236c254d3'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('94a8ebfe-0e09-53fa-9191-e5d6d5325c22'::uuid, 'faa89bf0-6081-5062-9d76-b55236c254d3'::uuid, 2, 'Competencia aplicada: Describir una labor subterránea y explicar cómo el método y la secuencia modifican el riesgo. Supervisar terreno, ventilación, atmósfera, agua, transporte, energías y emergencias. Definir parada, aislamiento, evacuación, reapertura y coordinación con trazabilidad.', true),
  ('37187361-798b-58df-bde6-808503c30e06'::uuid, 'faa89bf0-6081-5062-9d76-b55236c254d3'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('5c647ae4-0394-5fe6-b291-5bdba9fa2d20'::uuid, 'faa89bf0-6081-5062-9d76-b55236c254d3'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('e5dd2a67-25e9-5313-aa89-89f64f0815f7'::uuid, 'f2665c80-867d-5f68-b012-e86709ba9e1a'::uuid, 1, 'Pensar en el sistema: Desarrollo, preparación, producción, transporte, servicios y emergencia comparten infraestructuras. Una decisión local puede alterar ventilación, evacuación, estabilidad o circulación lejos del punto de trabajo. La evaluación debe abarcar toda la zona de influencia.', true),
  ('bacdd7fd-35db-51ec-8624-14eee1c81671'::uuid, 'f2665c80-867d-5f68-b012-e86709ba9e1a'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('e39f9eec-1c4e-55c0-a546-0d372d0de7fb'::uuid, 'f2665c80-867d-5f68-b012-e86709ba9e1a'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('d8ccf575-80ba-59ee-9ee2-5a98bd0b94c3'::uuid, 'f2665c80-867d-5f68-b012-e86709ba9e1a'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
