  ('7f687ce5-8e4e-552b-9866-e010c5bd2c37'::uuid, '093a7c8b-d4af-5b62-8239-4e2e0c7c4c82'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('3a710d63-3d2f-5331-8efc-d303980518be'::uuid, '093a7c8b-d4af-5b62-8239-4e2e0c7c4c82'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('0bee4c4a-67fa-55e3-8328-a0a9305a0a1d'::uuid, '093a7c8b-d4af-5b62-8239-4e2e0c7c4c82'::uuid, 4, 'Cada fase cambia el riesgo: Desarrollo y arranque: cambios de ventilación, gases, proyecciones y barrenos fallidos. Saneo y sostenimiento: evitar exposición bajo techo no verificado. Carga, transporte, relleno y servicios: interacción vehículo-peatón, agua, aire y energía.', true),
  ('6ad7cea6-ec56-5510-accd-0cdfe3a20738'::uuid, '41642c33-67e7-5c1d-a89c-21e409de129f'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('d1372267-4b3e-577c-af8e-0f33be243b9a'::uuid, '41642c33-67e7-5c1d-a89c-21e409de129f'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('c5f49b26-6260-5b83-b251-312b59704115'::uuid, '41642c33-67e7-5c1d-a89c-21e409de129f'::uuid, 3, 'Parar no elimina el peligro: Espera, limpieza, desatasco, inspección, prueba y mantenimiento tienen peligros propios. El cambio de turno o una parada de ventilación puede degradar barreras. Tras una incidencia, hay que verificar nuevamente las condiciones antes de recuperar la actividad.', true),
  ('487d584f-caed-5442-9af7-7ac095d9a2e8'::uuid, '41642c33-67e7-5c1d-a89c-21e409de129f'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('581e6c25-8774-5903-af31-38002f6ed626'::uuid, 'e4e149bb-bd65-5a82-895b-ad03be4fed89'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('3c2aaee2-694a-593c-a61a-a55fed2c44b7'::uuid, 'e4e149bb-bd65-5a82-895b-ad03be4fed89'::uuid, 2, 'La geometría gobierna: Cámaras y pilares, corte y relleno, subniveles, hundimiento y tajo largo presentan geometrías distintas. Importan luces, alturas, pilares, relleno, secuencia y excavaciones próximas. Cambiar el orden de extracción puede sobrecargar pilares o cerrar una ruta prevista.', true),
  ('9f007ff9-23f9-52cc-8976-7fd6df226842'::uuid, 'e4e149bb-bd65-5a82-895b-ad03be4fed89'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('f84d2de2-90ab-513e-a2df-7a6f2c2bf2b3'::uuid, 'e4e149bb-bd65-5a82-895b-ad03be4fed89'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('1b6982d8-0c3b-58d5-9795-08a7abe72583'::uuid, '569f1f46-61f5-5adf-89f3-a2aa5731e133'::uuid, 1, 'Riesgo remoto: Terreno, aire, agua y tráfico conectan labores diferentes. Un retorno restringido altera varios frentes; una labor antigua cambia agua, terreno y atmósfera. Evaluar siempre los efectos aguas abajo y en las rutas de evacuación.', true),
  ('c36bb92c-db54-5efa-b433-03a36ecd7424'::uuid, '569f1f46-61f5-5adf-89f3-a2aa5731e133'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
