  ('ad9b290b-fc8b-5d62-ae01-35cecc44845c'::uuid, '95fc3f8d-93c9-57fc-8965-f358913cd8dc'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('0b5bc41d-7ae2-5ce2-b719-e4519c9f6843'::uuid, '2af4e42e-3364-5e29-8dd4-409e3b1056b3'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('f9699660-d679-5d00-a397-bbf9eba68598'::uuid, '2af4e42e-3364-5e29-8dd4-409e3b1056b3'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('26e63c27-6348-57fd-92b4-6cabd4904ce9'::uuid, '2af4e42e-3364-5e29-8dd4-409e3b1056b3'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('d6b97153-2222-5404-b120-78e1f8230f5c'::uuid, '2af4e42e-3364-5e29-8dd4-409e3b1056b3'::uuid, 4, 'El terreno evoluciona: La excavación elimina confinamiento y redistribuye tensiones. Litología, fallas, juntas, estratificación, agua y labores cercanas condicionan el comportamiento. Una sección estable puede volverse inestable al cruzar una discontinuidad.', true),
  ('6b5cb38a-4b93-5e1b-80f0-834f285fbfb3'::uuid, '44d808f3-ee60-53b8-9a93-d60300e45dc7'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('4db69176-aee5-5399-94d9-4b6e245c8ae3'::uuid, '44d808f3-ee60-53b8-9a93-d60300e45dc7'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('9c927656-71dd-5853-8a71-605674d51ca6'::uuid, '44d808f3-ee60-53b8-9a93-d60300e45dc7'::uuid, 3, 'Detectar antes del fallo: Roca fresca en el piso, chasquidos, lajas, fisuras nuevas o pernos rotos. Malla abombada, convergencia, levantamiento y agua nueva o turbia. Respuesta: excluir, marcar, medir y solicitar evaluación competente.', true),
  ('1d354794-de8b-5321-a249-9093f5a61f46'::uuid, '44d808f3-ee60-53b8-9a93-d60300e45dc7'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('8bc68b38-80be-59f3-8940-b6f54c1d2134'::uuid, '68c2c16f-773f-5e30-aa38-f4067bb55ce1'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('22d61d4c-9967-5259-8d31-2052d97c3057'::uuid, '68c2c16f-773f-5e30-aa38-f4067bb55ce1'::uuid, 2, 'Buscar cambios: Orientación de discontinuidades, alteración, esfuerzos y agua. Método, secuencia, dimensiones y excavaciones próximas. Comparar continuamente la realidad observada con el modelo y el diseño.', true),
  ('976302e6-17b4-59c6-adae-6ef57608a9dc'::uuid, '68c2c16f-773f-5e30-aa38-f4067bb55ce1'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('c12beadd-f366-57a1-a59c-7de415364b81'::uuid, '68c2c16f-773f-5e30-aa38-f4067bb55ce1'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('8473d3dc-dbe2-5082-9d70-431e5674339d'::uuid, 'c03fe65e-2b9c-5721-b2b0-cef7145fc97e'::uuid, 1, 'Sostener el mecanismo correcto: Bulones, cables, malla, hormigón proyectado, cerchas, relleno o soporte hidráulico. Se selecciona según mecanismo de fallo, vida de la labor, deformación admisible y secuencia. Debe definir patrón, capacidad, ensayos y tratamiento de desviaciones.', true),
  ('3e3d5257-66d5-59da-ac98-cb704044055a'::uuid, 'c03fe65e-2b9c-5721-b2b0-cef7145fc97e'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('b54fffb5-3df3-5ee8-8743-644e9588ae10'::uuid, 'c03fe65e-2b9c-5721-b2b0-cef7145fc97e'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('45dd3572-20a3-5757-9b02-1f8cf9dc0b2e'::uuid, 'c03fe65e-2b9c-5721-b2b0-cef7145fc97e'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('2e01111e-2520-5177-a91a-7834125b5c57'::uuid, '11a8b1c9-7b34-5fd8-85e8-6271149dc27a'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('ce47f89d-9f62-5809-9fec-644511f1716a'::uuid, '11a8b1c9-7b34-5fd8-85e8-6271149dc27a'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('a52d5eae-4d8b-5294-b445-1bb825acdd96'::uuid, '11a8b1c9-7b34-5fd8-85e8-6271149dc27a'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('fb198c7b-2f86-5c22-a358-dd2855983bfd'::uuid, '11a8b1c9-7b34-5fd8-85e8-6271149dc27a'::uuid, 4, 'Calidad de instalación: Bulón o cable: taladro, longitud, orientación, resina o lechada, placa y tensión. Malla y hormigón: solape, fijación, espesor, adherencia, drenaje y curado. Cerchas: apoyo, alineación y arriostramiento; revisar deterioro y carga en servicio.', true),
  ('88cf8259-bfaa-5182-a2b7-bbf692a38904'::uuid, '1298dd6f-19a1-5b9f-983a-d16cce870af7'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('bec91c6f-7264-5186-8c67-ecd35978f564'::uuid, '1298dd6f-19a1-5b9f-983a-d16cce870af7'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('af66945d-c9f9-5229-8b98-6e677191033e'::uuid, '1298dd6f-19a1-5b9f-983a-d16cce870af7'::uuid, 3, 'Nunca trabajar bajo lo no verificado: Delimitar y evitar exposición bajo roca suelta. Inspeccionar desde terreno confirmado seguro y sanear fuera de la trayectoria con retirada disponible. Sostener en la secuencia definida, comprobar calidad y registrar anomalías.', true),
  ('b1ff2187-6efc-50f1-bfcc-58544d1d6092'::uuid, '1298dd6f-19a1-5b9f-983a-d16cce870af7'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('99db6a45-54ac-5742-b227-74e26858cb6d'::uuid, 'c3be420a-0b04-5e46-b6b4-2d7cc2421f2f'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('ae140117-6b8f-59dd-bf3a-d7edfad90c91'::uuid, 'c3be420a-0b04-5e46-b6b4-2d7cc2421f2f'::uuid, 2, 'La ausencia de caída no prueba seguridad: Una malla abombada indica que ha retenido carga, aunque no haya roca en el suelo. Su capacidad residual no está demostrada. Excluir la zona, evaluar la extensión y descargar o reforzar mediante un método aprobado antes de reabrir.', true),
  ('2fe71af0-959f-5921-b291-45ce378810d3'::uuid, 'c3be420a-0b04-5e46-b6b4-2d7cc2421f2f'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('94fab27c-de9c-5ccd-aea0-8eb2e485879d'::uuid, 'c3be420a-0b04-5e46-b6b4-2d7cc2421f2f'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('17137fd3-04cb-52d3-a984-8cf11cd51c60'::uuid, '515c4c2c-2796-59a2-9c99-f99f2225e0d6'::uuid, 1, 'Aire útil en el puesto: Aportar aire respirable, diluir contaminantes y conducirlos por rutas controladas. El caudal total no demuestra que el frente reciba aire limpio. También debe comprobarse que el retorno sea seguro y no recircule contaminantes.', true),
  ('3fc9931a-c7ed-5036-bb7a-8e6d25f3f6f0'::uuid, '515c4c2c-2796-59a2-9c99-f99f2225e0d6'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('f9f18709-7655-50cf-80a3-ef79994e0337'::uuid, '515c4c2c-2796-59a2-9c99-f99f2225e0d6'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('7a2b7ee3-732d-528c-8599-03825d4cfac4'::uuid, '515c4c2c-2796-59a2-9c99-f99f2225e0d6'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('fcd22391-f822-56c3-aef3-9256f4724ad5'::uuid, '61762290-4b5a-58eb-b715-899dc0d0ce69'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('6b1dff13-43b1-525f-9977-d697932316c1'::uuid, '61762290-4b5a-58eb-b715-899dc0d0ce69'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('b477d29b-af5e-5770-a8b3-b46858660bdb'::uuid, '61762290-4b5a-58eb-b715-899dc0d0ce69'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('64655b31-d8f7-523d-9a55-96c59a411703'::uuid, '61762290-4b5a-58eb-b715-899dc0d0ce69'::uuid, 4, 'Circuito real y actualizado: Entradas, retornos, ventiladores, puertas, esclusas, tabiques, reguladores, cruces y sellados. Abrir, cerrar u obstruir un elemento redistribuye el aire. Los planos deben reflejar el circuito real y todo cambio temporal debe diseñarse, comunicarse y comprobarse.', true),
  ('05bafccb-4e76-5800-ba1b-749c961e3348'::uuid, 'd1fbe220-c0fa-5b42-a1f3-96df3deef89a'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('020a7f77-48da-5cb1-a76f-5fb4e1f0dff6'::uuid, 'd1fbe220-c0fa-5b42-a1f3-96df3deef89a'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('ec2dafcf-8ff6-5e4e-8182-b65f2d0065f9'::uuid, 'd1fbe220-c0fa-5b42-a1f3-96df3deef89a'::uuid, 3, 'El extremo importa: El ventilador auxiliar lleva aire hasta el frente ciego. Fallos: parada, giro incorrecto, recirculación, mala ubicación o distancia excesiva. El conducto puede romperse, separarse, aplastarse, fugar o terminar lejos del frente.', true),
  ('676dc016-0335-5e32-abd4-4be6b648df65'::uuid, 'd1fbe220-c0fa-5b42-a1f3-96df3deef89a'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('6df4a3bb-0bc8-5f33-a896-a8337dab9cc5'::uuid, 'fb72f1a3-3ce4-51c9-b261-0c663943665a'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('05e5d63c-1537-5f95-8648-bd2652ee5106'::uuid, 'fb72f1a3-3ce4-51c9-b261-0c663943665a'::uuid, 2, 'Medir donde importa: Medir con método y sección adecuados y registrar ubicación, hora y estado productivo. Comparar con el criterio definido en el DSS o la DIS. Caudal en la galería no equivale a aire limpio en la zona respiratoria.', true),
  ('a8b3c09b-5f5f-51fc-9f4c-674a1938ed4f'::uuid, 'fb72f1a3-3ce4-51c9-b261-0c663943665a'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('5e778ff6-8b87-5150-8ee0-8749c2592e22'::uuid, 'fb72f1a3-3ce4-51c9-b261-0c663943665a'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('31fa9cf2-f3f5-5ada-bc0c-779817873152'::uuid, '4ee4bc46-46f3-57f7-b727-abe77e43b257'::uuid, 1, 'Corregir y volver a medir: Un cortocircuito lleva aire de entrada a retorno sin barrer la zona prevista. Puertas, tabiques, sellados y conductos dañados provocan fugas. La recirculación devuelve contaminantes: corregir la causa y repetir la medición.', true),
  ('1f91af18-0783-5059-89a7-ebcffa855d01'::uuid, '4ee4bc46-46f3-57f7-b727-abe77e43b257'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('a853829d-824d-5e32-a974-d69ee28b24fa'::uuid, '4ee4bc46-46f3-57f7-b727-abe77e43b257'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('ea90731e-b0d9-5b60-8a66-b04b3e1d603a'::uuid, '4ee4bc46-46f3-57f7-b727-abe77e43b257'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('4dd50bef-7e52-588a-a081-f5b63838ae5b'::uuid, '34417e5f-f97c-5953-858f-fd9bce15b8e3'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('4d04fdfb-64dc-5396-b0ac-b8d5db770bf5'::uuid, '34417e5f-f97c-5953-858f-fd9bce15b8e3'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('0720458e-649b-5b10-a070-1eaabba1f64c'::uuid, '34417e5f-f97c-5953-858f-fd9bce15b8e3'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('2a8e4a09-abd7-5ce6-9535-6cd7c828bf79'::uuid, '34417e5f-f97c-5953-858f-fd9bce15b8e3'::uuid, 4, 'Verificación completa: Confirmar el sistema en servicio y sin recirculación. Medir caudal o velocidad, revisar conducto y medir oxígeno y contaminantes en puntos representativos. Aplicar el criterio de parada y reentrada cuando el resultado esté fuera de rango.', true),
  ('092faed5-5017-52cd-aefe-33a7c6107ba8'::uuid, '99ac5118-0433-56e7-b7fe-b03433291819'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('be3624e0-0d69-564a-ae59-b2d4a7d1d925'::uuid, '99ac5118-0433-56e7-b7fe-b03433291819'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('279eb061-e945-5f76-9b56-429c75679ae6'::uuid, '99ac5118-0433-56e7-b7fe-b03433291819'::uuid, 3, 'Sin verificación no hay reapertura: Parar ante pérdida, inversión, reducción no autorizada, recirculación, alarma o imposibilidad de medir. Retirar exposición, aislar y corregir. Verificar condiciones representativas antes de autorizar la reentrada.', true),
  ('b4970683-3d1f-5fff-9598-329f46b3878f'::uuid, '99ac5118-0433-56e7-b7fe-b03433291819'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('74c0924a-7f94-50c1-8ae7-9f2c5676b45c'::uuid, '6752ebbc-bed5-5c5e-8815-f64300a10e9c'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('a09f6e87-c2a1-55cf-8594-8bd89fb1ab12'::uuid, '6752ebbc-bed5-5c5e-8815-f64300a10e9c'::uuid, 2, 'Medir antes de entrar: Los gases no se detectan de forma fiable por olor ni por síntomas. Con carácter general, el oxígeno no debe ser inferior al 19 % en volumen. El déficit puede reducir juicio y consciencia; deben prevalecer los criterios más restrictivos.', true),
  ('48dac8de-cfae-5255-b571-f4cf5abb3fab'::uuid, '6752ebbc-bed5-5c5e-8815-f64300a10e9c'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('060c38bc-eb87-5b8f-a53f-fbca0535b9c6'::uuid, '6752ebbc-bed5-5c5e-8815-f64300a10e9c'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('bd5cce3e-a2ec-52dd-8099-4e0538f33df2'::uuid, '22a106b3-485b-50d9-8d34-65f807931cbf'::uuid, 1, 'Valores del manual: CO: 25 ppm VLA-ED y 100 ppm VLA-EC. CO2: 5.000 y 12.500 ppm. SO2: 0,5 y 1 ppm. H2S: 5 y 10 ppm. NO: 25 y 30 ppm. NO2: 3 y 5 ppm. Considerar mezclas, picos, duración, lugar y condiciones; alcanzar el límite no es un objetivo.', true),
  ('5becd373-dddc-50cf-9f3b-a890044e4131'::uuid, '22a106b3-485b-50d9-8d34-65f807931cbf'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('2f2c6ca5-bda0-5abe-8dec-47531565bf2f'::uuid, '22a106b3-485b-50d9-8d34-65f807931cbf'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('9a5cbe6b-6402-55d2-bf0d-51fa017e3018'::uuid, '22a106b3-485b-50d9-8d34-65f807931cbf'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('643a9e1f-d9db-5ee3-bad5-04a1c114f14d'::uuid, 'b6759d34-f7f2-5ab9-9b34-4b30d020efab'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('79d6cb02-d167-5f0f-96d7-fe311d309631'::uuid, 'b6759d34-f7f2-5ab9-9b34-4b30d020efab'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('c104f9e5-b60b-587e-8f0c-3ac96a6978b2'::uuid, 'b6759d34-f7f2-5ab9-9b34-4b30d020efab'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('bc05ee63-b23e-52ea-adcb-5055c1f30399'::uuid, 'b6759d34-f7f2-5ab9-9b34-4b30d020efab'::uuid, 4, 'Instrumento apto y probado: Comprobar identificación, rango, sensores, calibración, batería y respuesta funcional. Configurar el equipo para los gases previsibles y medir a distancia si existe sospecha. Retirar instrumentos fuera de calibración, saturados, incoherentes o que fallen la prueba.', true),
  ('05e48972-3c0e-5c7d-905d-f3c40089268a'::uuid, 'e9124753-12e4-5f8a-81bc-2811ecc61912'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('99ffc283-6ab3-5930-8fa7-615da8868cf2'::uuid, 'e9124753-12e4-5f8a-81bc-2811ecc61912'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('4fc80e4a-b863-5866-90aa-e8bb780ae503'::uuid, 'e9124753-12e4-5f8a-81bc-2811ecc61912'::uuid, 3, 'Medir para decidir: Barrer alturas, huecos y zonas respiratorias según geometría y comportamiento del gas. Una lectura puntual no equivale a exposición diaria ni demuestra ausencia permanente. Registrar equipo, lugar, hora, condiciones, lectura, persona y decisión.', true),
  ('d8439445-4c8a-5eed-ba31-e902d7cf9171'::uuid, 'e9124753-12e4-5f8a-81bc-2811ecc61912'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('5aeaf5c8-d88b-55da-9bcc-8a8f1093ba24'::uuid, '173b6714-9637-594d-a234-b6b010680347'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('b8ca85d6-4f81-5cd7-9414-3fdfbce70e43'::uuid, '173b6714-9637-594d-a234-b6b010680347'::uuid, 2, 'Contexto específico: Aplicable a minas de carbón y labores con riesgo de explosión. ITC 05.0.02: 0,80 % en retornos generales; 1,50 % en restantes labores; 1,00 % en retornos de talleres electrificados. Aplicar alarmas, desconexiones y criterios más restrictivos del DSS o la DIS.', true),
  ('9429b533-639f-5e19-b159-fa2fb78ebcfd'::uuid, '173b6714-9637-594d-a234-b6b010680347'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('2dac2eec-26f4-593d-bafa-14890b5b3219'::uuid, '173b6714-9637-594d-a234-b6b010680347'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('784b472a-c941-53f4-8304-417ff474803f'::uuid, '11c55645-2e30-5644-a636-bcf7329787e6'::uuid, 1, 'Control en la fuente: Perforación, voladura, carga, trituración, transferencia y tráfico generan fracción respirable. VLA-ED: 3 mg/m3 de polvo respirable y 0,05 mg/m3 de sílice cristalina respirable. Controlar por diseño, captación, supresión, ventilación, organización y finalmente EPI.', true),
  ('e5328467-89de-5910-ab70-a727c814c517'::uuid, '11c55645-2e30-5644-a636-bcf7329787e6'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('fc8ef66f-4ec6-5b8c-87b9-db740faa16c7'::uuid, '11c55645-2e30-5644-a636-bcf7329787e6'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('982bd07f-d549-5bae-9527-d0a2278098d6'::uuid, '11c55645-2e30-5644-a636-bcf7329787e6'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('cf7920bb-625e-586f-b8e7-e99712b1ba01'::uuid, '2ba6c7a2-6441-5003-997d-778e44d007c3'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('11d07c81-9d37-5f6b-bba5-9b592828436d'::uuid, '2ba6c7a2-6441-5003-997d-778e44d007c3'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('05a51625-c0bc-599f-bf0c-d969b31c9c35'::uuid, '2ba6c7a2-6441-5003-997d-778e44d007c3'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('6c32666d-d6f8-5cbe-8e03-01e7cd410c04'::uuid, '2ba6c7a2-6441-5003-997d-778e44d007c3'::uuid, 4, 'Riesgos combinados: Diésel: bajas emisiones, mantenimiento, ventilación y reducción de ralentí. Ruido y vibración: selección, encapsulado, mantenimiento, distancia y tiempo. Calor e iluminación: ventilación, hidratación, aclimatación, pausas y luz suficiente sin deslumbrar.', true),
  ('496313b9-8d44-5ebc-8ea2-6a20ba17e235'::uuid, 'bf8a0447-9f83-55c4-ba5c-fb0b56185bda'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('794e7a38-c3a8-52d0-9756-876e272c0414'::uuid, 'bf8a0447-9f83-55c4-ba5c-fb0b56185bda'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('05bbcc4e-5b43-5795-b2ee-16a1e4f4d329'::uuid, 'bf8a0447-9f83-55c4-ba5c-fb0b56185bda'::uuid, 3, 'Humo y evacuación: Cintas, neumáticos, aceites, combustible, madera, cables y baterías aportan carga de fuego. La ventilación transporta humo y calor; las decisiones siguen el plan de emergencia. Trabajo en caliente: permiso, atmósfera controlada, combustibles retirados, extinción, vigilancia e inspección posterior.', true),
  ('8a1f4d05-ff46-5440-842e-1575c6a1014b'::uuid, 'bf8a0447-9f83-55c4-ba5c-fb0b56185bda'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('198549b9-3c9b-501c-b572-c8c37e065cbc'::uuid, '9b8d7927-b31e-5fb0-9102-ba07191dccf9'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('01b69634-83c7-592c-b9f9-2c01815eca18'::uuid, '9b8d7927-b31e-5fb0-9102-ba07191dccf9'::uuid, 2, 'Agua y movilidad: El agua erosiona, oculta huecos, vence barreras, afecta la electricidad y corta rutas. Ante sospecha: sondeos, solapes, control de presión, bombeo redundante, alarmas y ruta de descarga. Mantener salidas, control de presencia y un plan de tráfico con segregación.', true),
  ('79812138-22bd-526e-8db6-0699932bc680'::uuid, '9b8d7927-b31e-5fb0-9102-ba07191dccf9'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('896c2cda-e2af-55e3-8b0f-87f263f42f74'::uuid, '9b8d7927-b31e-5fb0-9102-ba07191dccf9'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('4bf6fad5-2d54-5f78-81e1-1347f62df79c'::uuid, '8b74258f-0f87-5eb2-8f0f-0565ed27a046'::uuid, 1, 'Reentrada autorizada: Explosivos solo por personal autorizado y con exclusiones e interferencias controladas. Tras el disparo: espera, ventilación, medición, terreno, sostenimiento, servicios y fallidos. Evacuar, contar personas y no improvisar rescates en atmósfera desconocida o terreno inestable.', true),
  ('55fea361-9270-5800-9e8c-5dfc20043c1c'::uuid, '8b74258f-0f87-5eb2-8f0f-0565ed27a046'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('98cfc312-8072-54a0-b407-b14bb6b4af2c'::uuid, '8b74258f-0f87-5eb2-8f0f-0565ed27a046'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('f832c62c-ea3c-5b62-b238-37ef10de8b4c'::uuid, '8b74258f-0f87-5eb2-8f0f-0565ed27a046'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('57adbf47-18d3-5c5d-881b-b56a680d59f6'::uuid, 'a16d8005-9dfb-5893-b655-aaa4f8765b34'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('ab638ede-819c-5931-a0a2-84602652b80d'::uuid, 'a16d8005-9dfb-5893-b655-aaa4f8765b34'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('45fcf92f-0b2d-5da1-9b00-e3197a128a9e'::uuid, 'a16d8005-9dfb-5893-b655-aaa4f8765b34'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('1550aa7c-0616-5247-9957-553f57547a91'::uuid, 'a16d8005-9dfb-5893-b655-aaa4f8765b34'::uuid, 4, 'Probar funciones críticas: Comprobar frenos, dirección, neumáticos, luces, alarmas, cámara, extinción, cinturón y fugas. Controlar puntos ciegos, pendientes, radios de giro, prioridad y segregación. Un fallo crítico retira el equipo de servicio.', true),
  ('8924bb59-2bdd-58ec-8595-fe25ae5be075'::uuid, 'e98d5be3-f776-5e19-8d35-3bd0e96407dc'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('e4f19128-191a-59f8-8b15-7582ed1a769c'::uuid, 'e98d5be3-f776-5e19-8d35-3bd0e96407dc'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('87d0e606-8718-51e4-9ac6-d66da90b0918'::uuid, 'e98d5be3-f776-5e19-8d35-3bd0e96407dc'::uuid, 3, 'Estabilidad y exclusión: Comprobar estabilidad, apoyos, mangueras, barras, protecciones y captación de polvo. Mantener al operador fuera de trayectorias de proyección, atrapamiento y latigazo. No acceder a la zona peligrosa mientras exista energía disponible.', true),
  ('9dc46a89-7276-55e3-9dfa-232c33b61e2c'::uuid, 'e98d5be3-f776-5e19-8d35-3bd0e96407dc'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('63e072e9-af46-5628-924b-a0f94a30071a'::uuid, '48a9f836-aad9-5647-a3e9-626b115a33b4'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('a950113a-f7d9-5b25-af6c-eab42f170d52'::uuid, '48a9f836-aad9-5647-a3e9-626b115a33b4'::uuid, 2, 'Consignar antes de intervenir: Revisar resguardos, enclavamientos, paradas, accesos, derrames, atascos y caída de material. Un atasco no se libera mientras exista energía. Rozamiento, humo, protección anulada o parada inaccesible exigen detener y consignar.', true),
  ('a42d60f4-6670-59c9-a1f4-93c554f3e6a4'::uuid, '48a9f836-aad9-5647-a3e9-626b115a33b4'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('3048a6fa-11d0-5813-93b4-c1cb36c66753'::uuid, '48a9f836-aad9-5647-a3e9-626b115a33b4'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('d4f73a32-4bd7-5bbd-9e59-7b78235066d6'::uuid, '729ee46a-0c98-55f9-bf3d-1b96b913314f'::uuid, 1, 'Equipo y entorno: Bomba: base, acoplamientos, tuberías, válvulas, presión, cebado y alimentación. Ventilador: anclaje, resguardo, sentido, vibración, conducto, protección y alarma. Izado: capacidad, identificación, accesorios, pestillos, apoyos, recorrido y exclusión.', true),
  ('7d7be15f-719a-544c-b7e2-841509114ae6'::uuid, '729ee46a-0c98-55f9-bf3d-1b96b913314f'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('fbdbaf65-37e3-5b13-ba9b-04c5677356de'::uuid, '729ee46a-0c98-55f9-bf3d-1b96b913314f'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('d0ea5f66-f71e-523d-9683-7fdb31100fe1'::uuid, '729ee46a-0c98-55f9-bf3d-1b96b913314f'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('1d7ab480-507a-5410-8c20-c8d15fa46aa8'::uuid, 'ef2a31f4-edf8-5758-962d-84a30d68e497'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('f6d4ff8e-8d61-5771-9538-9712831c69bf'::uuid, 'ef2a31f4-edf8-5758-962d-84a30d68e497'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('bab8a83e-41fd-5314-b7bb-1c1b82a53952'::uuid, 'ef2a31f4-edf8-5758-962d-84a30d68e497'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('089f26d9-4c41-558e-8657-4a74e69ea4c0'::uuid, 'ef2a31f4-edf8-5758-962d-84a30d68e497'::uuid, 4, 'Mirar, probar y decidir: Identificar el equipo, revisar estado físico, protecciones, fugas y documentación. Probar funciones críticas desde una posición segura. Comunicar defectos, inmovilizar y etiquetar cuando afecten a la seguridad.', true),
  ('e8d4b839-f8cd-522d-9b9e-f3acffa81c71'::uuid, '857d88d6-671c-5238-9f71-69ec3afeb05d'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('8c923984-2a6b-5d28-93c7-522218973495'::uuid, '857d88d6-671c-5238-9f71-69ec3afeb05d'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('fda7dbcc-b64b-58df-aca9-5018c1a3081c'::uuid, '857d88d6-671c-5238-9f71-69ec3afeb05d'::uuid, 3, 'Todas las fuentes: Eléctrica, hidráulica, neumática, mecánica, térmica, química, gravedad y presión almacenada. Incluir alimentaciones remotas, energías cruzadas y equipos aguas arriba o abajo. Un mando apagado no demuestra ausencia de energía.', true),
  ('9d0f48b3-4142-53f5-8ade-817e54ba8c05'::uuid, '857d88d6-671c-5238-9f71-69ec3afeb05d'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('391f24fe-3d0d-5cdc-9afa-e20853b9d586'::uuid, 'ef064ed2-6147-5241-b27a-a4d921348a6c'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('88fb0a31-4aa9-5b6e-a6de-edd97a84bdc0'::uuid, 'ef064ed2-6147-5241-b27a-a4d921348a6c'::uuid, 2, 'Aislamiento físico: Definir alcance, comunicar a afectados e identificar todas las energías. Detener mediante el mando normal y separar físicamente con seccionadores o válvulas. Evitar realimentaciones; una parada de emergencia no equivale a aislamiento.', true),
  ('86844470-c564-528f-9b34-19ca06bc7184'::uuid, 'ef064ed2-6147-5241-b27a-a4d921348a6c'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('025a0935-beff-5abe-bbf9-eb154f02871a'::uuid, 'ef064ed2-6147-5241-b27a-a4d921348a6c'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('fbd41c61-42f6-5da6-8a05-526b3040ce54'::uuid, '913481ba-4ccb-5da6-95f0-0f36784a1b83'::uuid, 1, 'Control personal: Cada persona expuesta mantiene control de su bloqueo. El bloqueo grupal requiere caja o sistema trazable; la etiqueta informa pero no sustituye el bloqueo. Los cambios de turno deben transferirse sin huecos de protección.', true),
  ('8c9b5672-e953-53f2-9650-c3239be581e0'::uuid, '913481ba-4ccb-5da6-95f0-0f36784a1b83'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('0f2c3ee3-84d3-5b87-8c15-c2d91b1cf959'::uuid, '913481ba-4ccb-5da6-95f0-0f36784a1b83'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('bc1f5512-4bea-5b33-86f3-7f94556a7c7a'::uuid, '913481ba-4ccb-5da6-95f0-0f36784a1b83'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('eed85315-24e2-56f3-b3bf-5c8e6dc899fb'::uuid, 'b085ec3e-53cf-59be-ac90-8ac25f53c340'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('759fb7ad-ac48-57ac-8fa0-974c9142d3ad'::uuid, 'b085ec3e-53cf-59be-ac90-8ac25f53c340'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('5228b2e8-b5d2-5baa-b38a-3356bdf02fb2'::uuid, 'b085ec3e-53cf-59be-ac90-8ac25f53c340'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('b07f329f-0bd9-5221-a6dc-3af9d3c09b49'::uuid, 'b085ec3e-53cf-59be-ac90-8ac25f53c340'::uuid, 4, 'Residual no significa inocua: Descargar acumuladores, purgar líneas, comprobar presión cero y descargar condensadores. Bloquear partes elevadas, inmovilizar articulaciones, calzar ruedas y asegurar muelles o cargas. Verificar la estabilidad después de eliminar o contener la energía.', true),
  ('f41d39bf-3fdb-57b8-8449-2f7172180586'::uuid, 'a315fe38-7d76-5d47-9f07-c7a1903f3adb'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('4f54929e-5383-5396-ac56-0e602bb5a523'::uuid, 'a315fe38-7d76-5d47-9f07-c7a1903f3adb'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('8b76c1a3-d94a-57c8-8bb4-0586c7b5ea1f'::uuid, 'a315fe38-7d76-5d47-9f07-c7a1903f3adb'::uuid, 3, 'Verificar antes de tocar: Intentar arranque controlado y medir cero tensión o presión con instrumento comprobado. Antes de restituir, revisar montaje, resguardos, herramientas, personas y zona. Reenergizar solo con autorización, comunicación y prueba funcional segura.', true),
  ('3ee7fc85-45c9-53dd-a417-20b0543c5de7'::uuid, 'a315fe38-7d76-5d47-9f07-c7a1903f3adb'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('499a0862-64f8-54d4-bbb5-c06e78e7bac4'::uuid, '934d0522-95cc-55e2-81db-247fa64f5c50'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('7c42c989-75fc-5fd1-97e0-679fd407510c'::uuid, '934d0522-95cc-55e2-81db-247fa64f5c50'::uuid, 2, 'La última barrera: Seleccionar según riesgo, tarea, ambiente, usuario y tiempo de uso. Verificar talla, ajuste, estado, vida útil, limpieza, almacenamiento y mantenimiento. Comprobar compatibilidad entre casco, lámpara, gafas, protección respiratoria, auditiva, arnés y comunicación.', true),
  ('20758dc1-419b-5664-bcb9-e5e52e1faf5c'::uuid, '934d0522-95cc-55e2-81db-247fa64f5c50'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('8b03334a-b2dc-5e42-a0b8-bf6221e03ae8'::uuid, '934d0522-95cc-55e2-81db-247fa64f5c50'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('857e6e28-ec91-547b-97c2-d9a60c56f1fe'::uuid, 'abbf3da4-8f0e-59a4-9600-99327969724e'::uuid, 1, 'Conocer las limitaciones: El filtro y ajuste deben corresponder al contaminante; los equipos filtrantes no sirven con oxígeno insuficiente. El autorrescatador facilita el escape y no sustituye una ruta viable. Retirar herramientas defectuosas y definir acceso, anclajes, comunicación y rescate antes de trabajos complejos.', true),
  ('e2c2a293-fc60-52a2-9c3e-767d949a121b'::uuid, 'abbf3da4-8f0e-59a4-9600-99327969724e'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('cee5d629-6d56-50ae-b949-c1a3bf9b52f2'::uuid, 'abbf3da4-8f0e-59a4-9600-99327969724e'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('000cd320-7f61-5842-a735-c6b6a264c3e8'::uuid, 'abbf3da4-8f0e-59a4-9600-99327969724e'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('9c484aeb-d6e7-5203-b3ca-c65fb063571d'::uuid, '98b79df2-83bd-583f-86eb-454b6128f74b'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('dd09a52f-ad48-5e41-beb1-ea14447e17da'::uuid, '98b79df2-83bd-583f-86eb-454b6128f74b'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('17e6e913-a08e-56dc-9423-c2a29cf2aebd'::uuid, '98b79df2-83bd-583f-86eb-454b6128f74b'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('da736e3a-bfc6-52c4-9d0e-bb9ed96f1d62'::uuid, '98b79df2-83bd-583f-86eb-454b6128f74b'::uuid, 4, 'Inspeccionar para decidir: Detectar desviaciones antes de que produzcan daño. Verificar que las barreras existen, funcionan y se adaptan a los cambios. Asignar acciones, responsables, plazos y criterios de cierre; marcar una lista no basta.', true),
  ('ac09b35f-540c-508a-85a5-ce67fd21bf63'::uuid, '18c569d7-53ac-5ae5-b721-4dfd03fca63a'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('d03ea774-98e7-50a5-8bf0-027411875739'::uuid, '18c569d7-53ac-5ae5-b721-4dfd03fca63a'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('9485b35e-c5cc-5ccd-a4b1-27fc40e251cc'::uuid, '18c569d7-53ac-5ae5-b721-4dfd03fca63a'::uuid, 3, 'Orden de exposición: Primero presencia, accesos y evacuación; después atmósfera y ventilación. Continuar con terreno, sostenimiento, agua, transporte y equipos. Revisar tareas, energías, permisos e interferencias sin entrar en zonas no verificadas.', true),
  ('5baa2368-ed18-52e0-8c25-5cd2a4a1ebfb'::uuid, '18c569d7-53ac-5ae5-b721-4dfd03fca63a'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('d2593d07-ab68-5f23-928f-7395a45e330a'::uuid, '000be05f-c91f-557b-b93c-5edb240dae3a'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('cc93809a-fd85-5c65-b7ba-ff110539e7ff'::uuid, '000be05f-c91f-557b-b93c-5edb240dae3a'::uuid, 2, 'Criticidad y cambio: Antes de turno o entrada y durante operaciones críticas. Después de voladura, parada, incidente, lluvia, sismo, incendio, alarma o cambio. A mayor posibilidad de cambio, gravedad o pérdida de barrera, mayor frecuencia.', true),
  ('20bb6ba2-eda1-5205-b202-8b0799f6f6f3'::uuid, '000be05f-c91f-557b-b93c-5edb240dae3a'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('f30bc1a0-f332-54b4-99ab-3f95b463ac22'::uuid, '000be05f-c91f-557b-b93c-5edb240dae3a'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('0318c79c-b493-530f-b895-8ae225175210'::uuid, 'd544940b-b759-5758-b923-eac2f5ab519b'::uuid, 1, 'Nunca usar una persona como detector: Confirmar autorización, presencia e información del turno anterior. Restablecer servicios desde zona segura y medir atmósfera antes de avanzar. Inspeccionar terreno, agua, rutas, equipos y comunicaciones; corregir y verificar de nuevo.', true),
  ('e8a80f25-c89c-5cec-89d3-2701dea92dd0'::uuid, 'd544940b-b759-5758-b923-eac2f5ab519b'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('b200e0b0-c06a-55dc-bfe4-c4c3aaf8f5fc'::uuid, 'd544940b-b759-5758-b923-eac2f5ab519b'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('efb497db-b81a-50c4-b9d6-e13756c2de2f'::uuid, 'd544940b-b759-5758-b923-eac2f5ab519b'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('8b3d1c09-1911-5aac-9128-6535d86a5bd3'::uuid, 'c468fc6c-e716-5b4f-a95f-a73228edd0ce'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('d073e372-c9f5-5787-9f88-1495b91dd633'::uuid, 'c468fc6c-e716-5b4f-a95f-a73228edd0ce'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('d35cb6f7-cc25-5b12-b926-e8adf2a0ef7d'::uuid, 'c468fc6c-e716-5b4f-a95f-a73228edd0ce'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('b474a4ba-3b72-5c81-8d3e-5f0810acdb0e'::uuid, 'c468fc6c-e716-5b4f-a95f-a73228edd0ce'::uuid, 4, 'Reentrada controlada: Respetar la exclusión, ventilar y comprobar la atmósfera. Revisar barrenos fallidos, terreno, sostenimiento, servicios, polvo, humos y accesos. La persona competente verifica, registra y entrega la zona antes de la reentrada.', true),
  ('362d8e47-b0a6-58e4-bd8e-411e9ffdfd33'::uuid, '4830aa5a-aceb-5650-9245-3aa9876390bd'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('62f77f1d-9723-52e9-a99c-d9d768db002d'::uuid, '4830aa5a-aceb-5650-9245-3aa9876390bd'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('3347fbd5-8b5a-5fe6-a8b4-2301121c822b'::uuid, '4830aa5a-aceb-5650-9245-3aa9876390bd'::uuid, 3, 'Trazabilidad técnica: Indicar punto, método, instrumento, fecha, hora y condiciones de operación. Registrar resultado, criterio de aceptación, persona y decisión. La fotografía ayuda, pero no sustituye mediciones o pruebas necesarias.', true),
  ('cd608345-3603-5c58-8099-df99a00400b4'::uuid, '4830aa5a-aceb-5650-9245-3aa9876390bd'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('261fe93f-d944-51ff-a854-7010edf189f1'::uuid, '69229c86-e826-5d66-9b15-42c1bee185b0'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('0097ce4a-1836-5c54-bca1-c134c49b3d25'::uuid, '69229c86-e826-5d66-9b15-42c1bee185b0'::uuid, 2, 'Otra persona debe entenderlo: Ubicación exacta, condición observada, medida o fotografía y personas expuestas. Acción inmediata, responsable, plazo y criterio de cierre. Redactar hechos, distinguir corrección inmediata y acción contra la recurrencia.', true),
  ('a6c1f8d2-622b-5e0a-ad69-440b5b2a6f29'::uuid, '69229c86-e826-5d66-9b15-42c1bee185b0'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('061b865e-d876-5b46-8734-09bba704f69e'::uuid, '69229c86-e826-5d66-9b15-42c1bee185b0'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('1a8db678-b7c9-51bc-908b-30b1e09fbb44'::uuid, '03404694-d204-5750-b6bf-835ab7ae2f21'::uuid, 1, 'Hechos verificables: Evitar descripciones vagas como «Techo mal», «Ventilación baja» o «Arreglar frenos». Precisar labor, evidencia, valor medido, exposición y medida adoptada. Ejemplo: equipo identificado, prueba no conforme, fuera de servicio y llave controlada.', true),
  ('021ebe38-f9d2-58b5-9163-abdc89e3bdeb'::uuid, '03404694-d204-5750-b6bf-835ab7ae2f21'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('56fbf7a2-093b-514d-b5a6-681d509cbdd1'::uuid, '03404694-d204-5750-b6bf-835ab7ae2f21'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('7b1577d0-34ac-5187-971a-f7aee1427e54'::uuid, '03404694-d204-5750-b6bf-835ab7ae2f21'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('46dc3c9d-fbab-5acc-82c4-597ede1b2412'::uuid, '003644e5-d484-5bdc-9ce7-b869c4a2e324'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('cbd46c7e-f2ee-59bf-b865-037a362fc360'::uuid, '003644e5-d484-5bdc-9ce7-b869c4a2e324'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('01e0a48e-fce4-5f41-bd5e-593cff3bc718'::uuid, '003644e5-d484-5bdc-9ce7-b869c4a2e324'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('a79eed59-3c4b-5f0e-b3c7-5e72be05982e'::uuid, '003644e5-d484-5bdc-9ce7-b869c4a2e324'::uuid, 4, 'Continuidad sin lagunas: Personas y equipos dentro; cierres, barreras y accesos restringidos. Estado de ventilación, bombeo, energía, comunicaciones, salidas, voladuras y permisos. Cambios y acciones pendientes con responsable, plazo y autoridad de cierre.', true),
  ('0438e16a-c881-551f-bd75-d218412fe290'::uuid, '896e3b16-bc35-57c5-9815-968da8165516'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('603f8a11-cf41-5774-a7d6-e8f0693c2a0b'::uuid, '896e3b16-bc35-57c5-9815-968da8165516'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('aa9a5816-f932-5233-8a74-61cc15d6cabf'::uuid, '896e3b16-bc35-57c5-9815-968da8165516'::uuid, 3, 'Un cambio temporal también cuenta: Geología, deformación, ventilación, agua, equipos, método o secuencia. Organización, contratistas, horarios, rutas, energía o emergencia. Describir, evaluar, actualizar documentos, controlar, formar, verificar y revisar.', true),
  ('916a5aa9-0128-5b78-b8ac-6cc9ea38e6f4'::uuid, '896e3b16-bc35-57c5-9815-968da8165516'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('73208964-6299-50d7-8d94-42ed93b6aa05'::uuid, 'ac62f26c-ffeb-5295-829d-3bb314b90100'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('286030e6-e9d2-5fa8-a744-4a57b16da3ac'::uuid, 'ac62f26c-ffeb-5295-829d-3bb314b90100'::uuid, 2, 'Cerrar no es abandonar: Definir alcance y responsable; retirar o asegurar personas, explosivos, combustibles y equipos. Aislar energías, decidir ventilación y bombeo e instalar barreras y señalización. Conservar drenaje, estabilidad y vigilancia; registrar requisitos de reapertura.', true),
  ('bfb5b563-0fe1-5e2a-8368-0adc05cfe539'::uuid, 'ac62f26c-ffeb-5295-829d-3bb314b90100'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('227d1305-ea75-5f4f-b170-0ab615f96d15'::uuid, 'ac62f26c-ffeb-5295-829d-3bb314b90100'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('e1d2d0fa-160b-5b13-9ac1-4e3fe21f8865'::uuid, '4cef9faf-12e5-53f7-abda-ca2b39e2ef42'::uuid, 1, 'Reapertura progresiva: Revisar cierre, planos, DSS, DIS, permisos, incidentes y cambios. Restablecer servicios desde zona segura, medir atmósfera e inspeccionar progresivamente. Corregir, repetir pruebas y autorizar con restricciones documentadas; no usar personas como prueba.', true),
  ('bab57ffd-2210-5041-9dac-f913cc3e1988'::uuid, '4cef9faf-12e5-53f7-abda-ca2b39e2ef42'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('a90c5f19-bb98-5f0a-9c82-5fad347d6048'::uuid, '4cef9faf-12e5-53f7-abda-ca2b39e2ef42'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('028901df-04dc-5966-bf35-5b015b225280'::uuid, '4cef9faf-12e5-53f7-abda-ca2b39e2ef42'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('3167a072-8b6f-5613-a719-2ea90ed82faf'::uuid, '250b9790-3404-5e60-a040-c5a5c6931d69'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('66aa2b5f-beab-5d87-a5b3-1981d4e73ba0'::uuid, '250b9790-3404-5e60-a040-c5a5c6931d69'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('0543ee46-0121-5fcf-bfb3-4245a4212945'::uuid, '250b9790-3404-5e60-a040-c5a5c6931d69'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('3227dade-79dd-5852-8c6a-30fb307734f9'::uuid, '250b9790-3404-5e60-a040-c5a5c6931d69'::uuid, 4, 'Ver lo que no está al lado: Dos equipos pueden interferir en un cruce, pero también a distancia mediante aire, energía, agua o material. Una actividad puede afectar la circulación o eliminar una salida. Evaluar simultaneidad en espacio, tiempo y sistemas conectados.', true),
  ('34607d5e-4cb4-549c-a806-cdd2a7e60742'::uuid, 'ae94d166-cb3d-5c2a-947b-a4f6060c7c28'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('90d96414-d901-5c44-8479-5de3e6ab2e7f'::uuid, 'ae94d166-cb3d-5c2a-947b-a4f6060c7c28'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('ee0fbb8a-4a21-51f7-b270-f5bf317d6b67'::uuid, 'ae94d166-cb3d-5c2a-947b-a4f6060c7c28'::uuid, 3, 'Interacciones críticas: Cruzar actividades y revisar acceso, atmósfera, energía, estructura, comunicación y emergencia. Ejemplos: voladura-mantenimiento, diésel-peatón, nivel superior-tránsito inferior. Incluir ventilación-frentes conectados, bombeo-electricidad e izado-trabajo bajo carga.', true),
  ('46e66a11-f95a-5f3f-b5b8-5f81f80e0e08'::uuid, 'ae94d166-cb3d-5c2a-947b-a4f6060c7c28'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('2cc4b7c4-29f7-5e8a-8ab0-e355b57d6776'::uuid, '99b5bd4b-b6c2-5454-9b8c-874c2b1fbef3'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('9de000f0-5029-562c-bd04-39d1ad03cb64'::uuid, '99b5bd4b-b6c2-5454-9b8c-874c2b1fbef3'::uuid, 2, 'Una secuencia única: Cada permiso puede ser correcto y, sin embargo, la secuencia global ser incompatible. Impedir energizar, disparar, circular o reabrir mientras otra actividad mantenga personas expuestas. Definir ventanas, exclusiones, responsables, comunicaciones y entrega de la instalación.', true),
  ('b2f29021-6e82-563b-8eef-012a13940e9b'::uuid, '99b5bd4b-b6c2-5454-9b8c-874c2b1fbef3'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('437e4d55-cede-5b2d-87b2-be0dd548f3b2'::uuid, '99b5bd4b-b6c2-5454-9b8c-874c2b1fbef3'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('5b411611-4a9b-5d33-b0ca-3e69b4070cb5'::uuid, 'd4ea2d9f-4959-5b54-87f0-05f18f6f4b22'::uuid, 1, 'Servicios interdependientes: Una obstrucción puede eliminar una salida y un vehículo puede dañar conductos. El bombeo puede inundar aguas abajo o afectar a otras energías. El izado crea zonas de caída: coordinar rutas, servicios y criterios de parada.', true),
  ('e17c278e-20ba-5f30-a777-5a21f10cf79a'::uuid, 'd4ea2d9f-4959-5b54-87f0-05f18f6f4b22'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('c05e5965-abb7-5787-84e9-46fc11c68b3f'::uuid, 'd4ea2d9f-4959-5b54-87f0-05f18f6f4b22'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('a9c09105-a5b0-5c64-b76a-002d79024e62'::uuid, 'd4ea2d9f-4959-5b54-87f0-05f18f6f4b22'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('5d422de3-6da3-5b9b-bdbe-750ac7bed554'::uuid, '3363f4d5-edfa-5c4d-ae15-64595968ffb4'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('d9b49224-3cc4-50a3-a9c0-a52ac51ffcad'::uuid, '3363f4d5-edfa-5c4d-ae15-64595968ffb4'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('a748d2a0-dc55-547d-86f3-021e3ce37a1a'::uuid, '3363f4d5-edfa-5c4d-ae15-64595968ffb4'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('d0ecc45a-1bfc-56e4-baa6-8ad61b0b1029'::uuid, '3363f4d5-edfa-5c4d-ae15-64595968ffb4'::uuid, 4, 'Un sistema común: Intercambiar riesgos específicos y cambios; comprobar competencia, autorizaciones, equipos y DIS. Nombrar interlocutores y unificar tráfico, alarma, presencia y permisos. Coordinar secuencia y entrega, supervisar y corregir; los documentos no sustituyen el campo.', true),
  ('cad4b6be-9061-52a2-8ae0-f93879b226f8'::uuid, '7460b15e-4656-5a4a-a662-e9bb9d476ac7'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('714097f0-5ecf-5af9-923a-ef02d6853151'::uuid, '7460b15e-4656-5a4a-a662-e9bb9d476ac7'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('efa0d539-b7c4-592d-aa14-2383b4ad8e1e'::uuid, '7460b15e-4656-5a4a-a662-e9bb9d476ac7'::uuid, 3, 'El permiso depende de la condición: Aplicables a trabajos en caliente, eléctricos, izado, altura, accesos complejos y reentrada. Identificar alcance, lugar, vigencia, personas, aislamientos, mediciones e interferencias. Incluir vigilancia, emergencia y cierre; el permiso deja de valer cuando cambian las condiciones.', true),
  ('1615a137-1275-5e02-96af-1d509ec37808'::uuid, '7460b15e-4656-5a4a-a662-e9bb9d476ac7'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('e19c59b4-f582-5c13-838d-09e8423bf410'::uuid, '5bc4d9c7-eabd-596f-bbf3-1ca1eec82c04'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('e0853fe7-305e-5578-80bd-01172621514d'::uuid, '5bc4d9c7-eabd-596f-bbf3-1ca1eec82c04'::uuid, 2, 'Entrega formal: Definir límites, energías, personas, equipos, barreras, permisos y defectos pendientes. Comprobar la entrega por ambas partes y dejar registro. La devolución confirma limpieza, montaje, protecciones y preparación para prueba o producción autorizada.', true),
  ('a352f897-c266-53d7-b72d-4fb5b26349e1'::uuid, '5bc4d9c7-eabd-596f-bbf3-1ca1eec82c04'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('1a8f8b49-b756-5988-be0e-a9ce16e9f769'::uuid, '5bc4d9c7-eabd-596f-bbf3-1ca1eec82c04'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('7a1d1869-f7af-5207-b03b-11d2caaef7ed'::uuid, '63f6c93f-e867-5f20-9ca7-fcaff30eea38'::uuid, 1, 'Control conjunto: Mantenimiento bloquea una cinta mientras producción pretende probar el sistema aguas arriba. La interacción puede mover material o reenergizar aunque ambos permisos parezcan correctos. Exigir entrega única, responsable común y cierre de todos los bloqueos antes de probar.', true),
  ('a5258a1a-1df7-5d91-b076-178f9f5351ee'::uuid, '63f6c93f-e867-5f20-9ca7-fcaff30eea38'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('4d0361a7-02c1-5412-9926-dec5c7e9ee43'::uuid, '63f6c93f-e867-5f20-9ca7-fcaff30eea38'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('c4809e28-d1a7-5b23-b0f8-a3944094461d'::uuid, '63f6c93f-e867-5f20-9ca7-fcaff30eea38'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('9bebb068-4a10-50d7-8810-aa9558a538d6'::uuid, '1ea0320a-2137-53f7-a978-d43eb5282f1e'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('452c4f3f-4463-5b76-bc4d-43955276dc86'::uuid, '1ea0320a-2137-53f7-a978-d43eb5282f1e'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('f106898a-438e-5b45-bcd4-070511554597'::uuid, '1ea0320a-2137-53f7-a978-d43eb5282f1e'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('da1421df-0a9c-504d-88ff-5f85e940a3c7'::uuid, '1ea0320a-2137-53f7-a978-d43eb5282f1e'::uuid, 4, 'Aplicar la norma adecuada: Ley 31/1995, Real Decreto 39/1997 y Real Decreto 1389/1997. RGNBSM, ITC, proyecto, autorizaciones, DSS y DIS. Procedimientos, permisos e instrucciones: saber qué documento gobierna y cuándo elevar una duda.', true),
  ('9f3e1026-5416-5fa0-bcc5-b75ce0854d3c'::uuid, '2c24cecc-f3f0-5e1a-a8fd-f4d13fa0f7cb'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('bcabc826-6481-5b32-a9ff-50449fee3251'::uuid, '2c24cecc-f3f0-5e1a-a8fd-f4d13fa0f7cb'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('196afdfc-c301-50f1-9456-1039ab0e91e8'::uuid, '2c24cecc-f3f0-5e1a-a8fd-f4d13fa0f7cb'::uuid, 3, 'Prevención integrada: La Ley 31/1995 establece principios, obligaciones, consulta, formación y protección. La formación debe ser suficiente, adecuada y centrada en el puesto. Debe actualizarse cuando cambien funciones, tecnología o riesgos y no trasladar su coste al trabajador.', true),
  ('5fd69a31-2097-5136-b86b-02460d33c235'::uuid, '2c24cecc-f3f0-5e1a-a8fd-f4d13fa0f7cb'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('80a5cc62-cb00-5fb7-a427-60bb276cd15e'::uuid, '142fb452-0dce-59b5-af6a-6857ec2d85fe'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('80636f90-f3c2-5135-8799-72ccd24fc28d'::uuid, '142fb452-0dce-59b5-af6a-6857ec2d85fe'::uuid, 2, 'Mínimos mineros: Fija disposiciones mínimas de seguridad y salud en actividades mineras. Exige organización, supervisión, equipos, mantenimiento, instrucciones y control de riesgos especiales. Incluye incendio, explosión, atmósferas nocivas, evacuación, salvamento, comunicación y DSS.', true),
  ('9204f032-288d-54df-ab2c-b33076ad9db5'::uuid, '142fb452-0dce-59b5-af6a-6857ec2d85fe'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('c03cf619-64a1-5f09-a5c1-753a59c40c9f'::uuid, '142fb452-0dce-59b5-af6a-6857ec2d85fe'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('b0c62446-8484-54fc-ac08-952e8145e388'::uuid, '3b2da5ee-2a04-5bd6-bb76-0f7b867ea79c'::uuid, 1, 'Marco técnico: El Real Decreto 863/1985 establece el marco técnico minero desarrollado por ITC. Las decisiones se integran con proyecto, dirección facultativa, autorizaciones y reglas de la instalación. El marco minero y la prevención general se aplican coordinadamente.', true),
  ('0d8b8733-3d54-58b3-82d9-d0f7ac1f793c'::uuid, '3b2da5ee-2a04-5bd6-bb76-0f7b867ea79c'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('d0f30325-8685-5e4f-bb4f-c9b045bd14cc'::uuid, '3b2da5ee-2a04-5bd6-bb76-0f7b867ea79c'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('43a5c774-ae08-559d-899f-235759e58a9d'::uuid, '3b2da5ee-2a04-5bd6-bb76-0f7b867ea79c'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false),
  ('ad5a731b-e7e4-5a84-a02d-289988fac19d'::uuid, '63494837-76d3-5e84-a028-96c05b79fbf7'::uuid, 1, 'Continuar mientras no se haya producido un accidente.', false),
  ('5a714804-d06a-56fc-acd8-f3db7d05417e'::uuid, '63494837-76d3-5e84-a028-96c05b79fbf7'::uuid, 2, 'Sustituir la comprobación por una advertencia verbal al equipo.', false),
  ('a23faf79-5773-5492-b7de-a564052a5c5a'::uuid, '63494837-76d3-5e84-a028-96c05b79fbf7'::uuid, 3, 'Mantener la tarea hasta el final del turno y revisar después.', false),
  ('88c7ad67-dafd-5a76-88db-ec829fa7cf91'::uuid, '63494837-76d3-5e84-a028-96c05b79fbf7'::uuid, 4, 'Versión vigente y DSS: ITC 02.1.02: formación preventiva. ITC 02.0.02: polvo y sílice. ITC 04.7.06: ambiente y gases. ITC 05.0.02: metano en carbón o labores con riesgo. Orden de 22 de marzo de 1988 y normativa de explosivos, incluido el RD 130/2017.', true),
  ('64ae358a-33f0-5a3f-a8cc-24fb92580fda'::uuid, '1dae9076-0064-5656-a42e-d9405f61426d'::uuid, 1, 'Considerar suficiente una firma sin observación, medición ni prueba.', false),
  ('f65ef5f4-9622-5ba4-b713-75b38c0a2130'::uuid, '1dae9076-0064-5656-a42e-d9405f61426d'::uuid, 2, 'Trasladar la decisión a quien ejecuta sin definir un criterio de aceptación.', false),
  ('98a30192-4682-55ed-b4b9-e39542a33780'::uuid, '1dae9076-0064-5656-a42e-d9405f61426d'::uuid, 3, 'Regla de aplicación: El DSS identifica peligros, evaluación, organización, planificación, mantenimiento y emergencia. Debe mantenerse actualizado y revisarse al menos anualmente o ante cambios importantes. Las DIS convierten requisitos en reglas operativas específicas de la explotación.', true),
  ('bac1206f-0633-595c-944e-1f5857b1627d'::uuid, '1dae9076-0064-5656-a42e-d9405f61426d'::uuid, 4, 'Aceptar la condición porque el trabajo se ha realizado así otras veces.', false),
  ('b52efc76-bb4d-5e59-b970-20e84f00db8d'::uuid, '90a08272-14f3-57bb-bce8-98f8525889e1'::uuid, 1, 'Reanudar en cuanto desaparezca el síntoma, sin verificar la causa ni las barreras.', false),
  ('7bb0962e-6ff6-5a68-b50d-a8260725d2c0'::uuid, '90a08272-14f3-57bb-bce8-98f8525889e1'::uuid, 2, 'Formación trazable: Grupo 5.3.a: técnicos titulados que trabajan en actividades extractivas de interior. Las 20 horas son una propuesta curricular de InmínerCampus; no se presenta como ET 2003-1-10 ni como homologación no acreditada. Reciclaje general de 5 horas, máximo 4 años, y evidencias completas de la formación.', true),
  ('45a1bc11-334b-54fc-a0e5-023ad0bc7da8'::uuid, '90a08272-14f3-57bb-bce8-98f8525889e1'::uuid, 3, 'Usar el equipo de protección individual como sustituto de los controles técnicos.', false),
  ('5756cf7f-ebf7-57e9-9d15-9b9e806aed4e'::uuid, '90a08272-14f3-57bb-bce8-98f8525889e1'::uuid, 4, 'Limitar la revisión al punto visible e ignorar labores o sistemas conectados.', false),
  ('c18f440f-d5ba-5767-8b68-4950947a1264'::uuid, '0b50c2ea-1b71-5704-a2b9-57cf9d5304d2'::uuid, 1, 'Autorizar solo con evidencias: Tarea, zona, responsables, presencia, rutas y salidas autorizados. Ventilación, atmósfera, terreno, agua, bombeo, comunicaciones, equipos y energías verificados. Permisos, interferencias, emergencia y criterio de parada conocidos; si falta una condición crítica, detener y corregir.', true),
  ('d2379202-0b0a-5a37-bba7-a2a8b0e2de9b'::uuid, '0b50c2ea-1b71-5704-a2b9-57cf9d5304d2'::uuid, 2, 'Dar por válido el permiso aunque hayan cambiado las condiciones que lo sustentaban.', false),
  ('3143cf0c-d2ee-512f-ad62-f1b9f2d09a79'::uuid, '0b50c2ea-1b71-5704-a2b9-57cf9d5304d2'::uuid, 3, 'Confiar únicamente en la experiencia del turno anterior.', false),
  ('c3938d2e-0569-53e4-a181-2935a354dcf5'::uuid, '0b50c2ea-1b71-5704-a2b9-57cf9d5304d2'::uuid, 4, 'Esperar a la revisión periódica aunque exista una desviación crítica.', false)
on conflict (id) do update set
  question_id = excluded.question_id,
  position = excluded.position,
  option_text = excluded.option_text,
  is_correct = excluded.is_correct,
  updated_at = now();

insert into public.quizzes (
  id, lesson_id, question_bank_id, title, question_count, passing_percent,
  required_perfect_streak, randomize_questions, randomize_options,
  minimum_retry_seconds, active, completion_mode
)
values
  ('463e21b9-38bc-5a95-86ed-c56d9014265e'::uuid, '960a4113-506b-5ad4-b700-ddf0a5851d1d'::uuid, 'a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'Test del bloque 1 · 10 preguntas', 10, 100, 2, true, true, 0, true, 'cumulative_perfect'),
  ('65eba0cb-4d27-541b-80b3-e939e14d31b2'::uuid, '024a10b2-f6a0-5471-a016-c26c16a69bd5'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, 'Test del bloque 2 · 10 preguntas', 10, 100, 2, true, true, 0, true, 'cumulative_perfect'),
  ('48acae21-ab36-5163-b6ad-c5b6eaef84c2'::uuid, 'ff9312ac-3141-51cf-bf52-8891bd66d7a6'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, 'Test del bloque 3 · 10 preguntas', 10, 100, 2, true, true, 0, true, 'cumulative_perfect'),
  ('402e087c-22bc-5f34-bc57-8b3ab03bdeca'::uuid, '8a09405d-734c-5e9f-b5cb-cc12988dfe6f'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, 'Test del bloque 4 · 10 preguntas', 10, 100, 2, true, true, 0, true, 'cumulative_perfect'),
  ('af62492c-1cb1-56e4-b3e2-e1c0a3484320'::uuid, 'f8f1475f-b96e-5a32-b747-c47fb46dfb2b'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, 'Test del bloque 5 · 8 preguntas', 8, 100, 2, true, true, 0, true, 'cumulative_perfect'),
  ('0c898f13-40d3-5cd8-be37-1b4ef9c849aa'::uuid, '1d36f0c6-5739-53a5-a719-9e336f509bcd'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid, 'Test del bloque 6 · 8 preguntas', 8, 100, 2, true, true, 0, true, 'cumulative_perfect')
on conflict (lesson_id) do update set
  question_bank_id = excluded.question_bank_id,
  title = excluded.title,
  question_count = excluded.question_count,
  passing_percent = excluded.passing_percent,
  required_perfect_streak = excluded.required_perfect_streak,
  randomize_questions = excluded.randomize_questions,
  randomize_options = excluded.randomize_options,
  minimum_retry_seconds = excluded.minimum_retry_seconds,
  active = excluded.active,
  completion_mode = excluded.completion_mode,
  updated_at = now();

do $$
declare
  v_modules integer;
  v_lessons integer;
  v_segments integer;
  v_slides integer;
  v_notes integer;
  v_banks integer;
  v_questions integer;
  v_options integer;
  v_quizzes integer;
begin
  select count(*) into v_modules from public.course_modules
    where course_version_id = '99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de'::uuid;
  select count(*) into v_lessons from public.lessons l
    join public.course_modules m on m.id = l.module_id
    where m.course_version_id = '99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de'::uuid;
  select count(*) into v_segments from public.lesson_audio_segments s
    join public.lessons l on l.id = s.lesson_id
    join public.course_modules m on m.id = l.module_id
    where m.course_version_id = '99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de'::uuid;
  select count(*) into v_slides from public.lesson_segment_slides p
    join public.lesson_audio_segments s on s.id = p.segment_id
    join public.lessons l on l.id = s.lesson_id
    join public.course_modules m on m.id = l.module_id
    where m.course_version_id = '99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de'::uuid;
  select count(*) into v_notes from public.lesson_segment_notes n
    join public.lesson_audio_segments s on s.id = n.segment_id
    join public.lessons l on l.id = s.lesson_id
    join public.course_modules m on m.id = l.module_id
    where m.course_version_id = '99de5e6c-318f-5bb9-91b4-c5b7a0b1f2de'::uuid;
  select count(*) into v_banks from public.question_banks where id in ('a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid);
  select count(*) into v_questions from public.questions where question_bank_id in ('a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid);
  select count(*) into v_options from public.question_options o
    join public.questions qn on qn.id = o.question_id
    where qn.question_bank_id in ('a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid);
  select count(*) into v_quizzes from public.quizzes
    where question_bank_id in ('a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid)
      and passing_percent = 100
      and required_perfect_streak = 2
      and completion_mode = 'cumulative_perfect'
      and active;

  if v_modules <> 6 or v_lessons <> 10 or v_segments <> 80
     or v_slides <> 80 or v_notes <> 80 or v_banks <> 6
     or v_questions <> 80 or v_options <> 320 or v_quizzes <> 6 then
    raise exception 'Paquete interior incompleto: módulos %, lecciones %, audios %, diapositivas %, explicaciones %, bancos %, preguntas %, opciones %, tests %',
      v_modules, v_lessons, v_segments, v_slides, v_notes, v_banks,
      v_questions, v_options, v_quizzes;
  end if;

  if exists (
    select qn.id
    from public.questions qn
    left join lateral (
      select count(*) as option_count,
             count(*) filter (where qo.is_correct) as correct_count
      from public.question_options qo
      where qo.question_id = qn.id
    ) checked on true
    where qn.question_bank_id in ('a4e9ce6f-ff4e-56bd-a1a3-6681dbd99657'::uuid, 'd03daf20-5016-5dda-b957-1b3f07062327'::uuid, '27aa0234-701a-5ddb-8b8c-fe2c8c9b01f6'::uuid, '9a91cbc1-ef97-55b1-a170-6a2c2baccc34'::uuid, '0248803c-50b4-50f2-a522-995c595c9658'::uuid, '2273b20f-74f7-5f54-9210-30a7f00e92ae'::uuid)
      and (checked.option_count <> 4 or checked.correct_count <> 1)
  ) then
    raise exception 'Cada pregunta del curso interior debe tener cuatro opciones y una sola correcta';
  end if;
end $$;

commit;
